package org.apache.curator.framework.recipes.cache;

import java.util.List;
import org.apache.curator.framework.state.ConnectionState;

/**
 * Event emitted by {@link PathChildrenCache}
 */
public class PathChildrenCacheEvent {
    private final Type type;
    private final ChildData data;

    /**
     * Enumerated type for {@link PathChildrenCacheEvent}s
     */
    public enum Type {
        /**
         * A new child was added to the path
         */
        CHILD_ADDED,

        /**
         * A child's data changed
         */
        CHILD_UPDATED,

        /**
         * A child was removed from the path
         */
        CHILD_REMOVED,

        /**
         * The connection state changed to {@link ConnectionState#SUSPENDED}
         */
        CONNECTION_SUSPENDED,

        /**
         * The connection state changed to {@link ConnectionState#RECONNECTED}
         */
        CONNECTION_RECONNECTED,

        /**
         * The connection state changed to {@link ConnectionState#LOST}
         */
        CONNECTION_LOST,

        /**
         * The initial cache has been filled
         */
        INITIALIZED
    }

    public PathChildrenCacheEvent(Type type, ChildData data) {
        this.type = type;
        this.data = data;
    }

    public Type getType() {
        return type;
    }

    public ChildData getData() {
        return data;
    }

    /**
     * If {@link PathChildrenCacheEvent#getType()} is {@link Type#INITIALIZED}, this will return the
     * initial data in the cache.
     *
     * @return initial data or null
     */
    public List<ChildData> getInitialData() {
        return null;
    }

    @Override
    public String toString() {
        return "PathChildrenCacheEvent{" + "type=" + type + ", data=" + data + '}';
    }
}

