package org.apache.curator.framework.recipes.barriers;

import java.util.concurrent.TimeUnit;
import org.apache.curator.framework.CuratorFramework;
import org.apache.curator.utils.PathUtils;
import org.apache.zookeeper.KeeperException;
import org.apache.zookeeper.WatchedEvent;
import org.apache.zookeeper.Watcher;

/**
 * Distributed barrier. All processes/threads that want to wait on the barrier
 * must call {@link #waitOnBarrier()} until {@link #removeBarrier()} is called.
 */
public class DistributedBarrier {
    private final CuratorFramework client;
    private final String barrierPath;
    private final Watcher watcher = new Watcher() {
        @Override
        public void process(WatchedEvent event) {
            client.postSafeNotify(DistributedBarrier.this);
        }
    };

    /**
     * @param client the client
     * @param barrierPath the barrier path
     */
    public DistributedBarrier(CuratorFramework client, String barrierPath) {
        this.client = client;
        this.barrierPath = PathUtils.validatePath(barrierPath);
    }

    /**
     * Set the barrier
     *
     * @throws Exception errors
     */
    public synchronized void setBarrier() throws Exception {
        try {
            client.create()
                    .creatingParentContainersIfNeeded()
                    .forPath(barrierPath);
        } catch (KeeperException.NodeExistsException e) {
            // ignore
        }
    }

    /**
     * Remove the barrier
     *
     * @throws Exception errors
     */
    public synchronized void removeBarrier() throws Exception {
        try {
            client.delete().forPath(barrierPath);
        } catch (KeeperException.NoNodeException e) {
            // ignore
        }
    }

    /**
     * Wait on the barrier
     *
     * @throws Exception errors
     */
    public synchronized void waitOnBarrier() throws Exception {
        waitOnBarrier(-1, null);
    }

    /**
     * Wait on the barrier
     *
     * @param maxWait max wait
     * @param unit max wait unit
     * @return true if barrier was removed, false if timed out
     * @throws Exception errors
     */
    public synchronized boolean waitOnBarrier(long maxWait, TimeUnit unit) throws Exception {
        long start = System.currentTimeMillis();
        boolean hasMaxWait = unit != null;
        while (client.checkExists().usingWatcher(watcher).forPath(barrierPath) != null) {
            if (hasMaxWait) {
                long thisWaitMs = unit.convert(maxWait, TimeUnit.MILLISECONDS) - (System.currentTimeMillis() - start);
                if (thisWaitMs <= 0) {
                    return false;
                }
                wait(thisWaitMs);
            } else {
                wait();
            }
        }
        return true;
    }
}

