package org.apache.curator.framework.imps;

import com.google.common.annotations.VisibleForTesting;
import java.util.Optional;
import java.util.UUID;
import org.apache.curator.framework.api.CreateBuilderMain;
import org.apache.curator.utils.ZKPaths;

/**
 * Utilities for {@link CreateBuilderMain#withProtection()}
 */
public final class ProtectedUtils {
    private ProtectedUtils() {
        // throw new RuntimeException("Protected Utils is a helper class");
    }

    @VisibleForTesting
    static final String PROTECTED_PREFIX = "_c_";

    @VisibleForTesting
    static final char PROTECTED_SEPARATOR = '-';

    @VisibleForTesting
    static final int PROTECTED_PREFIX_WITH_UUID_LENGTH = PROTECTED_PREFIX.length() + 36 + 1;

    /**
     * Return the protected prefix
     *
     * @param protectedId the protected id
     * @return the protected prefix
     */
    public static String getProtectedPrefix(final String protectedId) {
        return PROTECTED_PREFIX + protectedId + PROTECTED_SEPARATOR;
    }

    private static String extractProtectedIdInternal(final String znodeName) {
        return znodeName.substring(3, PROTECTED_PREFIX_WITH_UUID_LENGTH - 1);
    }

    /**
     * Return true if the given znode is a protected znode
     *
     * @param znodeName the znode name
     * @return true if the given znode is a protected znode
     */
    public static boolean isProtectedZNode(final String znodeName) {
        if (znodeName.length() > PROTECTED_PREFIX_WITH_UUID_LENGTH) {
            if (znodeName.startsWith(PROTECTED_PREFIX)) {
                if (znodeName.charAt(PROTECTED_PREFIX_WITH_UUID_LENGTH - 1) == PROTECTED_SEPARATOR) {
                    try {
                        UUID.fromString(extractProtectedIdInternal(znodeName));
                        return true;
                    } catch (IllegalArgumentException e) {
                        return false;
                    }
                }
            }
        }
        return false;
    }

    /**
     * Return the znode name without the protected prefix
     *
     * @param znodeName the znode name
     * @return the znode name without the protected prefix
     */
    public static String normalize(final String znodeName) {
        if (isProtectedZNode(znodeName)) {
            return znodeName.substring(PROTECTED_PREFIX_WITH_UUID_LENGTH);
        }
        return znodeName;
    }

    /**
     * Return the znode path without the protected prefix
     *
     * @param path the znode path
     * @return the znode path without the protected prefix
     */
    public static String normalizePath(final String path) {
        final ZKPaths.PathAndNode pathAndNode = ZKPaths.getPathAndNode(path);
        final String name = pathAndNode.getNode();
        if (isProtectedZNode(name)) {
            final String normalizedName = normalize(name);
            return ZKPaths.makePath(pathAndNode.getPath(), normalizedName);
        }
        return path;
    }

    /**
     * Return the protected id
     *
     * @param znodeName the znode name
     * @return the protected id
     */
    public static Optional<String> extractProtectedId(final String znodeName) {
        return isProtectedZNode(znodeName) ? Optional.ofNullable(extractProtectedIdInternal(znodeName)) : null;
    }

    /**
     * Return the znode name with the protected prefix
     *
     * @param znodeName the znode name
     * @param protectedId the protected id
     * @return the znode name with the protected prefix
     */
    public static String toProtectedZNode(final String znodeName, final String protectedId) {
        return protectedId == null ? znodeName : getProtectedPrefix(protectedId) + znodeName;
    }

    /**
     * Return the znode path with the protected prefix
     *
     * @param path the znode path
     * @param protectedId the protected id
     * @return the znode path with the protected prefix
     */
    public static String toProtectedZNodePath(final String path, final String protectedId) {
        return protectedId == null ? path : ZKPaths.makePath(
                ZKPaths.getPathAndNode(path).getPath(),
                toProtectedZNode(ZKPaths.getPathAndNode(path).getNode(), protectedId));
    }
}

