import com.google.common.base.Preconditions;
import com.google.common.util.concurrent.MoreExecutors;
import java.util.concurrent.Executor;
import java.util.concurrent.Executors;
import java.util.concurrent.ThreadFactory;
import java.util.concurrent.TimeUnit;
import org.apache.curator.framework.CuratorFramework;
import org.apache.curator.utils.PathUtils;
import org.apache.curator.utils.ThreadUtils;

/**
 * Builder for various DistributedQueue implementations
 */
public class QueueBuilder<T> {
    private final CuratorFramework client;
    private final QueueConsumer<T> consumer;
    private final QueueSerializer<T> serializer;
    private final String queuePath;
    private ThreadFactory factory;
    private Executor executor;
    private String lockPath;
    private int maxItems;
    private boolean putInBackground;
    private int finalFlushMs;

    static final ThreadFactory defaultThreadFactory = ThreadUtils.newThreadFactory("QueueBuilder");
    static final int NOT_SET = Integer.MAX_VALUE;

    /**
     * @param client the client
     * @param consumer the consumer
     * @param serializer the serializer
     * @param queuePath the queue path
     * @param <T> the type
     * @return a new QueueBuilder
     */
    public static <T> QueueBuilder<T> builder(
            CuratorFramework client,
            QueueConsumer<T> consumer,
            QueueSerializer<T> serializer,
            String queuePath) {
        return new QueueBuilder<>(client, consumer, serializer, queuePath);
    }

    /**
     * Build a DistributedQueue
     *
     * @return a new DistributedQueue
     */
    public DistributedQueue<T> buildQueue() {
        return new DistributedQueue<>(
                client,
                consumer,
                serializer,
                queuePath,
                factory,
                executor,
                Integer.MAX_VALUE,
                false,
                lockPath,
                maxItems,
                putInBackground,
                finalFlushMs);
    }

    /**
     * Build a DistributedIdQueue
     *
     * @return a new DistributedIdQueue
     */
    public DistributedIdQueue<T> buildIdQueue() {
        return new DistributedIdQueue<>(
                client,
                consumer,
                serializer,
                queuePath,
                factory,
                executor,
                Integer.MAX_VALUE,
                false,
                lockPath,
                maxItems,
                putInBackground,
                finalFlushMs);
    }

    /**
     * Build a DistributedPriorityQueue
     *
     * @param minItemsBeforeRefresh the minimum number of items before a refresh
     * @return a new DistributedPriorityQueue
     */
    public DistributedPriorityQueue<T> buildPriorityQueue(int minItemsBeforeRefresh) {
        return new DistributedPriorityQueue<>(
                client,
                consumer,
                serializer,
                queuePath,
                factory,
                executor,
                minItemsBeforeRefresh,
                lockPath,
                maxItems,
                putInBackground,
                finalFlushMs);
    }

    /**
     * Build a DistributedDelayQueue
     *
     * @return a new DistributedDelayQueue
     */
    public DistributedDelayQueue<T> buildDelayQueue() {
        return new DistributedDelayQueue<>(
                client,
                consumer,
                serializer,
                queuePath,
                factory,
                executor,
                Integer.MAX_VALUE,
                lockPath,
                maxItems,
                putInBackground,
                finalFlushMs);
    }

    /**
     * Set the thread factory
     *
     * @param factory the thread factory
     * @return this
     */
    public QueueBuilder<T> threadFactory(ThreadFactory factory) {
        this.factory = Preconditions.checkNotNull(factory, "factory cannot be null");
        return this;
    }

    /**
     * Set the executor
     *
     * @param executor the executor
     * @return this
     */
    public QueueBuilder<T> executor(Executor executor) {
        this.executor = Preconditions.checkNotNull(executor, "executor cannot be null");
        return this;
    }

    /**
     * Set the lock path
     *
     * @param path the lock path
     * @return this
     */
    public QueueBuilder<T> lockPath(String path) {
        this.lockPath = PathUtils.validatePath(path);
        return this;
    }

    /**
     * Set the maximum number of items
     *
     * @param maxItems the maximum number of items
     * @return this
     */
    public QueueBuilder<T> maxItems(int maxItems) {
        this.maxItems = maxItems;
        this.putInBackground = false;
        return this;
    }

    /**
     * Set whether to put in background
     *
     * @param putInBackground whether to put in background
     * @return this
     */
    public QueueBuilder<T> putInBackground(boolean putInBackground) {
        this.putInBackground = putInBackground;
        return this;
    }

    /**
     * Set the final flush time
     *
     * @param time the final flush time
     * @param unit the time unit
     * @return this
     */
    public QueueBuilder<T> finalFlushTime(int time, TimeUnit unit) {
        this.finalFlushMs = (int) unit.toMillis(time);
        return this;
    }

    private QueueBuilder(
            CuratorFramework client,
            QueueConsumer<T> consumer,
            QueueSerializer<T> serializer,
            String queuePath) {
        this.client = client;
        this.consumer = consumer;
        this.serializer = serializer;
        this.queuePath = PathUtils.validatePath(queuePath);
        this.factory = defaultThreadFactory;
        this.executor = MoreExecutors.directExecutor();
    }
}

