package org.apache.curator.framework.schema;

import com.google.common.base.Function;
import com.google.common.base.Preconditions;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.cache.LoadingCache;
import com.google.common.collect.ImmutableList;
import com.google.common.collect.ImmutableMap;
import com.google.common.collect.Maps;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ExecutionException;
import org.apache.curator.framework.CuratorFramework;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Set of schemas for a Curator instance
 */
public class SchemaSet {
    private final Logger log = LoggerFactory.getLogger(getClass());
    private final Map<String, Schema> schemas;
    private final Map<String, Schema> pathToSchemas;
    private final List<Schema> regexSchemas;
    private final CacheLoader<String, Schema> cacheLoader;
    private final LoadingCache<String, Schema> regexCache;

    private static final Schema nullSchema = new Schema(null, "", new DefaultSchemaValidator(), true, true, true, true, null);
    private static final Schema defaultSchema = new Schema(null, "", new DefaultSchemaValidator(), true, true, true, true, null);
    private final boolean useDefaultSchema;

    /**
     * Return a default schema set
     *
     * @return default schema set
     */
    public static SchemaSet getDefaultSchemaSet() {
        return new SchemaSet(Collections.<Schema>emptyList(), true) {
            @Override
            public String toDocumentation() {
                return "Default schema";
            }
        };
    }

    /**
     * @param schemas schemas
     * @param useDefaultSchema use default schema
     */
    public SchemaSet(List<Schema> schemas, boolean useDefaultSchema) {
        this.schemas = Maps.uniqueIndex(
                Preconditions.checkNotNull(schemas, "schemas cannot be null"),
                new Function<Schema, String>() {
                    @Override
                    public String apply(Schema schema) {
                        return schema.getName();
                    }
                });

        this.useDefaultSchema = useDefaultSchema;

        ImmutableMap.Builder<String, Schema> pathToSchemasBuilder = ImmutableMap.builder();
        ImmutableList.Builder<Schema> regexSchemasBuilder = ImmutableList.builder();
        for (Schema schema : schemas) {
            if (schema.getPath() != null) {
                pathToSchemasBuilder.put(schema.getPath(), schema);
            } else {
                regexSchemasBuilder.add(schema);
            }
        }
        pathToSchemas = pathToSchemasBuilder.build();
        regexSchemas = regexSchemasBuilder.build();

        cacheLoader = new CacheLoader<String, Schema>() {
            @Override
            public Schema load(String path) throws Exception {
                for (Schema schema : regexSchemas) {
                    if (schema.getPathRegex().matcher(path).matches()) {
                        log.debug("path -> {}", schema);
                        return schema;
                    }
                }
                return nullSchema;
            }
        };
        regexCache = CacheBuilder.newBuilder().softValues().build(cacheLoader);
    }

    /**
     * Return all schemas
     *
     * @return all schemas
     */
    public Collection<Schema> getSchemas() {
        return schemas.values();
    }

    /**
     * Return the schema that matches the given path
     *
     * @param path path
     * @return schema
     */
    public Schema getSchema(String path) {
        if (schemas.size() > 0) {
            Schema schema = pathToSchemas.get(path);
            if (schema != null) {
                return schema;
            }

            try {
                schema = regexCache.get(path);
                if (schema == nullSchema) {
                    schema = useDefaultSchema ? defaultSchema : null;
                }
            } catch (ExecutionException e) {
                throw new RuntimeException(e);
            }

            return schema;
        }

        return useDefaultSchema ? defaultSchema : null;
    }

    /**
     * Return the path for the given schema
     *
     * @param client client
     * @param name name
     * @return path
     */
    public static String getNamedPath(CuratorFramework client, String name) {
        return client.getSchemaSet().getNamedSchema(name).getRawPath();
    }

    /**
     * Return the schema with the given name
     *
     * @param name name
     * @return schema
     */
    public Schema getNamedSchema(String name) {
        return schemas.get(name);
    }

    /**
     * Return a string that can be displayed to a user
     *
     * @return documentation
     */
    public String toDocumentation() {
        StringBuilder sb = new StringBuilder("Curator Schemas:\n\n");
        for (Map.Entry<String, Schema> entry : schemas.entrySet()) {
            sb.append(entry.getKey()).append("\n");
            sb.append(entry.getValue().toDocumentation()).append("\n");
        }
        return sb.toString();
    }
}

