/**
 * Legacy HTTP codec — parses legacy HTTP requests (backpressureure) and hands them to {@link
 * LegacyHttpBridge} for delivery.
 */
public interface LegacyHttpCodec {

    /**
     * Parse a legacy HTTP publish request.
     *
     * @param body legacy HTTP body
     * @return parsed request
     */
    LegacyPublishRequest parsePublish(byte[] body);

    /**
     * Parse a legacy HTTP subscribe command.
     *
     * @param body legacy HTTP body
     * @return parsed request
     */
    LegacySubscribeRequest parseSubscribe(byte[] body);

    /**
     * Legacy HTTP publish request.
     */
    final class LegacyPublishRequest {
        private final String topic;
        private final CloudEvent event;

        public LegacyPublishRequest(String topic, CloudEvent event) {
            this.topic = topic;
            this.event = event;
        }

        public String getTopic() {
            return topic;
        }

        public CloudEvent getEvent() {
            return event;
        }
    }

    /**
     * Legacy HTTP subscribe command (webhook push).
     */
    final class LegacySubscribeRequest {
        private final String clientId;
        private final String url;
        private final String secret;
        private final List<String> topics;
        private final DistributionMode mode;

        public LegacySubscribeRequest(
            String clientId, String url, String secret, List<String> topics, DistributionMode mode) {
            this.clientId = clientId;
            this.url = url;
            this.secret = secret;
            this.topics = topics;
            this.mode = mode;
        }

        public String getClientId() {
            return clientId;
        }

        public String getUrl() {
            return url;
        }

        public String getSecret() {
            return secret;
        }

        public List<String> getTopics() {
            return topics;
        }

        public DistributionMode getMode() {
            return mode;
        }
    }
}

