package org.apache.eventmesh.runtime.cluster;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * Deterministic partition assignment for a set of instances.
 *
 * <p>Each instance computes the same assignment given the same liveInstances list, so the same
 * assignment is computed on every instance. This is used to implement a simple self-assignment
 * scheme in the EventMesh cluster, where the leader assigns partitions to instances in a round-robin
 * fashion. Production uses a metadata service to assign partitions, but the self-assignment path
 * is still used for tests.</p>
 */
public final class PartitionAssigner {

    private PartitionAssigner() {
        // Prevent instantiation
    }

    /**
     * Assign partitions to instances in a deterministic way.
     *
     * @param partitionCount number of partitions
     * @param liveInstances   list of live instance ids
     * @return partition → instance map
     */
    public static Map<Integer, String> assign(int partitionCount, List<String> liveInstances) {
        if (liveInstances.isEmpty()) {
            throw new IllegalArgumentException("liveInstances must not be empty");
        }

        // Sort the instance list so every instance computes the same assignment.
        List<String> sorted = new ArrayList<>(liveInstances);
        Collections.sort(sorted);

        Map<Integer, String> out = new HashMap<>();
        for (int p = 0; p < partitionCount; p++) {
            out.put(p, sorted.get(p % sorted.size()));
        }
        return out;
    }

    /**
     * Return the list of partitions owned by the given instance.
     *
     * @param assignment assignment map
     * @param instanceId  instance id
     * @return list of partitions
     */
    public static List<Integer> ownedBy(Map<Integer, String> assignment, String instanceId) {
        List<Integer> owned = new ArrayList<>();
        for (Map.Entry<Integer, String> e : assignment.entrySet()) {
            if (e.getValue().equals(instanceId)) {
                owned.add(e.getKey());
            }
        }
        Collections.sort(owned);
        return owned;
    }
}

