package org.apache.eventmesh.runtime.transport.tcp;

import org.apache.eventmesh.runtime.delivery.AckCallback;

import java.util.concurrent.ConcurrentHashMap;

import lombok.extern.slf4j.Slf4j;

/**
 * A temporary registry of deliveryId → AckCallback for the legacy TCP push path.
 *
 * <p>The {@link ReliableDispatcher} registers a delivery with the {@link TcpPushChannel} and
 * waits for the client to ACK. The ACK frame carries the deliveryId so the registry can find the
 * correct callback and invoke it. The callback then advances the dispatcher's offset so it can
 * resend the delivery if the client times out or retries.</p>
 *
 * <p>The callback is removed from the registry once the delivery is ACKed or the dispatcher
 * times out the delivery. The callback is never invoked twice, so the dispatcher never has to
 * worry about a race between the callback and the dispatcher's offset advancement.</p>
 */
@Slf4j
public class TcpAckRegistry {

    private final ConcurrentHashMap<String, AckCallback> pending = new ConcurrentHashMap<>();

    /**
     * Register a deliveryId → AckCallback for the legacy TCP push path.
     *
     * @param deliveryId the deliveryId
     * @param callback the ACK callback
     */
    public void register(String deliveryId, AckCallback callback) {
        pending.put(deliveryId, callback);
    }

    /**
     * A client ACK frame has arrived. Find the callback and invoke it.
     *
     * @param deliveryId the deliveryId
     * @return true if the callback was found and invoked, false if the deliveryId was unknown
     */
    public boolean onClientAck(String deliveryId) {
        AckCallback callback = pending.remove(deliveryId);
        if (callback == null) {
            return false;
        }
        callback.ack();
        return true;
    }

    /**
     * How many deliveries are pending ACK?
     *
     * @return the number of pending deliveries
     */
    public int pending() {
        return pending.size();
    }
}

