package org.apache.eventmesh.runtime.push;

import java.util.List;

import lombok.extern.slf4j.Slf4j;

/**
 * Pump a {@link Connection} from a {@link PushService} until it closes.
 *
 * <p>The connection is responsible for ACKing events once it has processed them, so the pump
 * just writes them out until the connection closes. The connection is responsible for
 * reconnecting on close so the pump never sees a closed connection.</p>
 */
@Slf4j
public class ConnectionPushPump {

    private final PushService pushService;
    private final String clientId;
    private final Connection connection;

    public ConnectionPushPump(PushService pushService, String clientId, Connection connection) {
        this.pushService = pushService;
        this.clientId = clientId;
        this.connection = connection;
    }

    /**
     * Pump one batch of events from the {@link PushService} into the connection.
     *
     * @param max maximum number of events to pull
     * @return number of events pumped
     */
    public int pumpOnce(int max) {
        if (!connection.isOpen()) {
            return 0;
        }
        List<BufferedEvent> batch = pushService.poll(clientId, max, 0L);
        if (batch.isEmpty()) {
            return 0;
        }
        int pushed = 0;
        for (BufferedEvent event : batch) {
            if (!connection.isOpen()) {
                log.debug("Connection closed during batch; events still buffered in {}", clientId);
                break;
            }
            String deliveryId = event.getDeliveryId();
            connection.send(deliveryId, event.getEvent());
            pushed++;
        }
        return pushed;
    }
}

