package org.apache.eventmesh.common;

import java.util.concurrent.TimeUnit;
import java.util.concurrent.locks.AbstractQueuedSynchronizer;

/**
 * A resettable CountDownLatch.
 *
 * <p>This class provides a resettable CountDownLatch. It has the same methods as {@link java.util.concurrent.CountDownLatch}
 * but also provides a {@link #reset()} method to reset the countdown to the initial value.
 *
 * <p>The main difference between this class and {@link java.util.concurrent.CountDownLatch} is that
 * {@link java.util.concurrent.CountDownLatch} can only be used once, while {@link ResetCountDownLatch}
 * can be reset.
 *
 * <p>Usage:
 * <pre>
 * ResetCountDownLatch latch = new ResetCountDownLatch(1);
 *
 * // Wait for the latch to be reset
 * latch.await();
 *
 * // Reset the latch
 * latch.reset();
 *
 * // Wait for the latch to be reset
 * latch.await();
 * </pre>
 *
 * <p>Note: This class is not thread-safe. It should only be used by one thread at a time.
 */
public class ResetCountDownLatch {

    private final RestSync restSync;

    /**
     * Create a new ResetCountDownLatch with the given count.
     *
     * @param count the initial count
     */
    public ResetCountDownLatch(int count) {
        this.restSync = new RestSync(count);
    }

    /**
     * Wait for the countdown to reach zero.
     *
     * @throws InterruptedException if the current thread is interrupted while waiting
     */
    public void await() throws InterruptedException {
        restSync.acquireSharedInterruptibly(1);
    }

    /**
     * Wait for the countdown to reach zero, with a timeout.
     *
     * @param timeout the timeout
     * @param unit the time unit
     * @return true if the countdown reached zero, false if the timeout elapsed
     * @throws InterruptedException if the current thread is interrupted while waiting
     */
    public boolean await(long timeout, TimeUnit unit) throws InterruptedException {
        return restSync.tryAcquireSharedNanos(1, unit.toNanos(timeout));
    }

    /**
     * Decrement the countdown.
     *
     * If the countdown reaches zero, any threads waiting in {@link #await()} will be unblocked.
     */
    public void countDown() {
        restSync.releaseShared(1);
    }

    /**
     * Get the current countdown value.
     *
     * This method is intended primarily for debugging and testing purposes. It is not guaranteed to
     * return the current countdown value at any given moment, as it may be changed by other threads.
     *
     * @return the current countdown value
     */
    public int getCount() {
        return restSync.getCount();
    }

    /**
     * Reset the countdown to the initial value.
     */
    public void reset() {
        restSync.reset();
    }

    private static final class RestSync extends AbstractQueuedSynchronizer {

        private final int initCount;

        RestSync(int count) {
            if (count < 0) {
                throw new IllegalArgumentException("count must be greater than or equal to 0");
            }
            this.initCount = count;
            setState(count);
        }

        protected void reset() {
            setState(initCount);
        }

        int getCount() {
            return getState();
        }

        @Override
        protected int tryAcquireShared(int acquires) {
            return getState() == 0 ? 1 : -1;
        }

        @Override
        protected boolean tryReleaseShared(int releases) {
            while (true) {
                int oldCount = getState();
                if (oldCount == 0) {
                    return false;
                }
                if (compareAndSetState(oldCount, oldCount - 1)) {
                    return oldCount == 0;
                }
            }
        }
    }
}

