package org.apache.eventmesh.runtime.security;

import java.nio.charset.StandardCharsets;
import java.util.Locale;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;

import io.cloudevents.CloudEvent;

/**
 * Verify CloudEvents carry a valid HMAC-SHA256 signature. The signature is a string extension
 * {@code emsignature} containing a hex-encoded HMAC-SHA256 signature of the CloudEvents {@code id},
 * {@code source}, and {@code type} attributes, concatenated with {@code |}. The signature is
 * computed using a shared secret provided to the filter on construction.
 *
 * <p>The signature is checked by the filter on ingress, and the {@code emsignature} extension is
 * removed from the event before it is passed on to the ingress pipeline. The signature is
 * re-computed by the client and added to the event before it is sent, so the filter can verify it
 * without needing to know the secret.</p>
 */
public class SignatureVerifierFilter implements IngressFilter {

    /**
     * The CloudEvents extension name used to carry the signature.
     */
    public static final String EXT_SIGNATURE = "emsignature";

    private final byte[] secret;

    /**
     * Create a new filter that verifies signatures using the given shared secret.
     *
     * @param secret the shared secret
     */
    public SignatureVerifierFilter(String secret) {
        this.secret = secret.getBytes(StandardCharsets.UTF_8);
    }

    @Override
    public FilterVerdict check(CloudEvent event, FilterContext ctx) {
        Object provided = event.getExtension(EXT_SIGNATURE);
        if (!(provided instanceof String)) {
            return FilterVerdict.deny(FilterVerdict.STATUS_UNAUTHENTICATED, "missing signature");
        }
        String expected = sign(canonical(event));
        if (constantTimeEquals((String) provided, expected)) {
            return FilterVerdict.allow();
        }
        return FilterVerdict.deny(FilterVerdict.STATUS_UNAUTHENTICATED, "signature mismatch");
    }

    /**
     * Sign the given message using the shared secret.
     *
     * @param message the message to sign
     * @return the signature
     */
    public String sign(String message) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(secret, "HmacSHA256"));
            byte[] digest = mac.doFinal(message.getBytes(StandardCharsets.UTF_8));
            return toHex(digest);
        } catch (Exception e) {
            throw new IllegalStateException("HMAC-SHA256 unavailable", e);
        }
    }

    static String canonical(CloudEvent event) {
        return String.valueOf(event.getId()) + "|" + String.valueOf(event.getSource()) + "|"
            + String.valueOf(event.getType());
    }

    private static String toHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder(bytes.length * 2);
        for (byte b : bytes) {
            sb.append(String.format(Locale.ROOT, "%02x", b & 0xff));
        }
        return sb.toString();
    }

    private static boolean constantTimeEquals(String a, String b) {
        if (a.length() != b.length()) {
            return false;
        }
        int diff = 0;
        for (int i = 0; i < a.length(); i++) {
            diff |= a.charAt(i) ^ b.charAt(i);
        }
        return diff == 0;
    }
}

