package org.apache.eventmesh.common.utils;

import java.io.File;
import java.io.IOException;
import java.lang.reflect.Method;

/**
 * System Utilities
 */
public abstract class SystemUtils {

    public static final String OS_NAME = System.getProperty("os.name");

    private static boolean isLinuxPlatform = false;
    private static boolean isWindowsPlatform = false;

    private SystemUtils() {
        // do nothing
    }

    public static boolean isLinuxPlatform() {
        return isLinuxPlatform;
    }

    public static boolean isWindowsPlatform() {
        return isWindowsPlatform;
    }

    public static String getProcessId() {
        try {
            Class<?> managementFactoryClass = Class.forName("java.lang.management.ManagementFactory");
            Method getRuntimeMXBeanMethod = managementFactoryClass.getDeclaredMethod("getRuntimeMXBean");
            Class<?> runtimeMXBeanClass = Class.forName("java.lang.management.RuntimeMXBean");
            Method getNameMethod = runtimeMXBeanClass.getDeclaredMethod("getName");
            Object runtimeMXBean = getRuntimeMXBeanMethod.invoke(null);
            String name = (String) getNameMethod.invoke(runtimeMXBean);
            return name.split("@")[0];
        } catch (Exception e) {
            try {
                File file = new File("/proc/self");
                File canonicalFile = file.getCanonicalFile();
                return canonicalFile.getName();
            } catch (IOException e1) {
                // ignore
            }
        }
        return "-1";
    }

    static {
        if (OS_NAME != null) {
            isLinuxPlatform = OS_NAME.toLowerCase().contains("linux");
            isWindowsPlatform = OS_NAME.toLowerCase().contains("windows");
        }
    }
}

