package org.apache.eventmesh.common.protocol.http;

import org.apache.eventmesh.common.Constants;
import org.apache.eventmesh.common.protocol.ProtocolTransportObject;
import org.apache.eventmesh.common.protocol.http.body.BaseResponseBody;
import org.apache.eventmesh.common.protocol.http.body.Body;
import org.apache.eventmesh.common.protocol.http.common.EventMeshRetCode;
import org.apache.eventmesh.common.protocol.http.common.RequestCode;
import org.apache.eventmesh.common.protocol.http.header.BaseResponseHeader;
import org.apache.eventmesh.common.protocol.http.header.Header;
import org.apache.eventmesh.common.utils.JsonUtils;

import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;

import io.netty.buffer.Unpooled;
import io.netty.handler.codec.http.DefaultFullHttpResponse;
import io.netty.handler.codec.http.HttpHeaderNames;
import io.netty.handler.codec.http.HttpHeaderValues;
import io.netty.handler.codec.http.HttpHeaders;
import io.netty.handler.codec.http.HttpResponseStatus;
import io.netty.handler.codec.http.HttpVersion;

import java.util.Objects;
import java.util.Optional;
import java.util.concurrent.atomic.AtomicLong;

import lombok.Data;

/**
 * HTTP Command
 */
@Deprecated
@Data
public class HttpCommand implements ProtocolTransportObject {

    private static final long serialVersionUID = -8763824685105888009L;

    private static final AtomicLong requestId = new AtomicLong(0);

    private long opaque;

    private String requestCode;

    public String httpMethod;

    public String httpVersion;

    private transient Header header;

    private transient Body body;

    public long reqTime;

    public long resTime;

    public CmdType cmdType = CmdType.REQ;

    public HttpCommand() {
        this(null, null, null);
    }

    public HttpCommand(String httpMethod, String httpVersion, String requestCode) {
        this.httpMethod = httpMethod;
        this.httpVersion = httpVersion;
        this.requestCode = requestCode;
        this.reqTime = System.currentTimeMillis();
        this.opaque = requestId.incrementAndGet();
    }

    public HttpCommand createHttpCommandResponse(Header header, Body body) {
        if (this.requestCode == null) {
            this.requestCode = RequestCode.UNKNOWN.getRequestCode().toString();
        }
        HttpCommand httpCommand = new HttpCommand(this.httpMethod, this.httpVersion, this.requestCode);
        httpCommand.opaque = this.opaque;
        httpCommand.reqTime = this.reqTime;
        httpCommand.header = header;
        httpCommand.body = body;
        httpCommand.cmdType = CmdType.RES;
        httpCommand.resTime = System.currentTimeMillis();
        return httpCommand;
    }

    public HttpCommand createHttpCommandResponse(EventMeshRetCode eventMeshRetCode) {
        if (this.requestCode == null) {
            this.requestCode = RequestCode.UNKNOWN.getRequestCode().toString();
        }
        HttpCommand httpCommand = new HttpCommand(this.httpMethod, this.httpVersion, this.requestCode);
        httpCommand.opaque = this.opaque;
        httpCommand.reqTime = this.reqTime;
        httpCommand.header = new BaseResponseHeader();
        ((BaseResponseHeader) httpCommand.header).setCode(this.requestCode);
        httpCommand.body = new BaseResponseBody();
        ((BaseResponseBody) httpCommand.body).setRetCode(eventMeshRetCode.getRetCode());
        ((BaseResponseBody) httpCommand.body).setRetMsg(eventMeshRetCode.getErrMsg());
        httpCommand.cmdType = CmdType.RES;
        httpCommand.resTime = System.currentTimeMillis();
        return httpCommand;
    }

    @Override
    public String toString() {
        StringBuilder sb = new StringBuilder();
        sb.append("httpCommand={");
        sb.append("cmdType=").append(cmdType);
        sb.append(", httpMethod=").append(httpMethod);
        sb.append(", httpVersion=").append(httpVersion);
        sb.append(", requestCode=").append(requestCode);
        sb.append(", opaque=").append(opaque);
        if (cmdType == CmdType.RES) {
            sb.append(", cost=").append(resTime - reqTime);
        }
        sb.append(", header=").append(header);
        sb.append(", body=").append(body);
        sb.append("}");
        return sb.toString();
    }

    public String abstractDesc() {
        StringBuilder sb = new StringBuilder();
        sb.append("httpCommand={");
        sb.append("cmdType=").append(cmdType);
        sb.append(", httpMethod=").append(httpMethod);
        sb.append(", httpVersion=").append(httpVersion);
        sb.append(", requestCode=").append(requestCode);
        sb.append(", opaque=").append(opaque);
        if (cmdType == CmdType.RES) {
            sb.append(", cost=").append(resTime - reqTime);
        }
        sb.append(", header=").append(header);
        sb.append(", bodySize=").append(body.toString().length());
        sb.append("}");
        return sb.toString();
    }

    public String simpleDesc() {
        StringBuilder sb = new StringBuilder();
        sb.append("httpCommand={");
        sb.append("cmdType=").append(cmdType);
        sb.append(", httpMethod=").append(httpMethod);
        sb.append(", httpVersion=").append(httpVersion);
        sb.append(", requestCode=").append(requestCode);
        sb.append("}");
        return sb.toString();
    }

    public DefaultFullHttpResponse httpResponse() throws Exception {
        if (cmdType == CmdType.REQ) {
            return null;
        }
        DefaultFullHttpResponse response = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, HttpResponseStatus.OK,
            Unpooled.wrappedBuffer(Objects.requireNonNull(JsonUtils.toJSONString(body)).getBytes(Constants.DEFAULT_CHARSET)));
        response.headers().add(HttpHeaderNames.CONTENT_TYPE, "text/plain; charset=" + Constants.DEFAULT_CHARSET);
        response.headers().add(HttpHeaderNames.CONTENT_LENGTH, response.content().readableBytes());
        response.headers().add(HttpHeaderNames.CONNECTION, HttpHeaderValues.KEEP_ALIVE);
        Optional.of(getHeader().toMap()).ifPresent(map -> map.forEach(response.headers()::add));
        return response;
    }

    public DefaultFullHttpResponse httpResponse(HttpResponseStatus httpResponseStatus) throws Exception {
        if (cmdType == CmdType.REQ) {
            return null;
        }
        DefaultFullHttpResponse response = new DefaultFullHttpResponse(HttpVersion.HTTP_1_1, httpResponseStatus,
            Unpooled.wrappedBuffer(Objects.requireNonNull(JsonUtils.toJSONString(body)).getBytes(Constants.DEFAULT_CHARSET)));
        response.headers().add(HttpHeaderNames.CONTENT_TYPE, "text/plain; charset=" + Constants.DEFAULT_CHARSET);
        response.headers().add(HttpHeaderNames.CONTENT_LENGTH, response.content().readableBytes());
        response.headers().add(HttpHeaderNames.CONNECTION, HttpHeaderValues.KEEP_ALIVE);
        Optional.of(getHeader().toMap()).ifPresent(map -> map.forEach(response.headers()::add));
        return response;
    }

    public enum CmdType {
        REQ, RES
    }
}

