package org.apache.hc.client5.http.impl.auth;

import java.io.IOException;
import java.io.OutputStream;
import java.security.MessageDigest;

/**
 * HTTP entity digester that can be plugged into HTTP
 * response processing to calculate response entity hash.
 */
class HttpEntityDigester extends OutputStream {

    private final MessageDigest digester;
    private boolean closed;
    private byte[] digest;

    HttpEntityDigester(final MessageDigest digester) {
        super();
        this.digester = digester;
        this.digester.reset();
    }

    @Override
    public void write(final int b) throws IOException {
        if (!closed) {
            this.digester.update((byte) b);
        } else {
            throw new IOException("Stream has been already closed");
        }
    }

    @Override
    public void write(final byte[] b, final int off, final int len) throws IOException {
        if (!closed) {
            this.digester.update(b, off, len);
        } else {
            throw new IOException("Stream has been already closed");
        }
    }

    @Override
    public void close() throws IOException {
        if (!closed) {
            closed = true;
            digest = this.digester.digest();
            super.close();
        }
    }

    public byte[] getDigest() {
        return digest;
    }

}

