package org.apache.hc.client5.http.classic;

import java.io.IOException;

import org.apache.hc.client5.http.HttpRoute;
import org.apache.hc.client5.http.protocol.HttpClientContext;
import org.apache.hc.core5.annotation.Contract;
import org.apache.hc.core5.annotation.ThreadingBehavior;
import org.apache.hc.core5.http.ClassicHttpRequest;
import org.apache.hc.core5.http.ClassicHttpResponse;
import org.apache.hc.core5.http.HttpException;
import org.apache.hc.core5.util.Args;

/**
 * Represents a single element in a classic request execution chain.
 *
 * @since 5.0
 */
@Contract(threading = ThreadingBehavior.STATELESS)
public interface ExecChain {

    /**
     * Represents a set of execution metadata for a particular request execution.
     */
    final class Scope {

        /**
         * The exchange id.
         */
        public final String exchangeId;

        /**
         * The route.
         */
        public final HttpRoute route;

        /**
         * The original request.
         */
        public final ClassicHttpRequest originalRequest;

        /**
         * The execution runtime.
         */
        public final ExecRuntime execRuntime;

        /**
         * The client context.
         */
        public final HttpClientContext clientContext;

        public Scope(
                final String exchangeId,
                final HttpRoute route,
                final ClassicHttpRequest originalRequest,
                final ExecRuntime execRuntime,
                final HttpClientContext clientContext) {
            this.exchangeId = Args.notNull(exchangeId, "Exchange id");
            this.route = Args.notNull(route, "Route");
            this.originalRequest = Args.notNull(originalRequest, "Original request");
            this.execRuntime = Args.notNull(execRuntime, "Exec runtime");
            this.clientContext = Args.notNull(clientContext, "HTTP context");
        }

    }

    /**
     * Processes the given request with the given execution context.
     *
     * @param request the request to process
     * @param scope the execution context
     * @return the response
     * @throws IOException
     * @throws HttpException
     */
    ClassicHttpResponse proceed(ClassicHttpRequest request, Scope scope) throws IOException, HttpException;

}

