package org.opengis.example.geometry;

import java.util.Arrays;
import java.util.Objects;

import org.opengis.geometry.DirectPosition;
import org.opengis.referencing.crs.CoordinateReferenceSystem;
import org.opengis.coordinate.MismatchedDimensionException;


/**
 * A {@link DirectPosition} implementation backed by a {@link double} array.
 *
 * @author  Martin Desruisseaux (Geomatys)
 * @version 1.0
 * @since   1.0
 */
public class SimpleDirectPosition implements DirectPosition {
    /**
     * The coordinates of this position.
     */
    public final double[] coordinates;

    /**
     * The {@linkplain CoordinateReferenceSystem} associated to this position, or {@code null}.
     */
    protected CoordinateReferenceSystem crs;

    /**
     * Creates a new position of the given dimension.
     *
     * @param dimension  the dimension of the new position.
     */
    public SimpleDirectPosition(final int dimension) {
        coordinates = new double[dimension];
    }

    /**
     * Creates a new position of the given {@linkplain CoordinateReferenceSystem}.
     *
     * @param crs  the {@linkplain CoordinateReferenceSystem} of the new position.
     */
    public SimpleDirectPosition(final CoordinateReferenceSystem crs) {
        coordinates = new double[crs.getCoordinateSystem().getDimension()];
        this.crs = crs;
    }

    /**
     * Creates a new position of the given {@linkplain CoordinateReferenceSystem}.
     *
     * @param crs  the {@linkplain CoordinateReferenceSystem} of the new position.
     * @param coordinates  the coordinates of the new position.
     * @throws MismatchedDimensionException if the {@linkplain CoordinateReferenceSystem} dimension
     *         does not match the {@linkplain CoordinateReferenceSystem} dimension.
     */
    public SimpleDirectPosition(final CoordinateReferenceSystem crs, final double... coordinates) throws MismatchedDimensionException {
        this.coordinates = Objects.requireNonNull(coordinates);
        this.crs = crs;
        if (crs != null) {
            if (crs.getCoordinateSystem().getDimension() != coordinates.length) {
                throw new MismatchedDimensionException();
            }
        }
    }

    /**
     * Creates a new position initialized to the same content as the given {@link DirectPosition}.
     *
     * @param position  the {@link DirectPosition} to copy.
     */
    public SimpleDirectPosition(final DirectPosition position) {
        coordinates = position.getCoordinates();
        crs = position.getCoordinateReferenceSystem();
    }

    /**
     * Returns the {@linkplain CoordinateReferenceSystem} associated to this position, or {@code null}.
     */
    @Override
    public CoordinateReferenceSystem getCoordinateReferenceSystem() {
        return crs;
    }

    /**
     * Returns the dimension of this position.
     */
    @Override
    public int getDimension() {
        return coordinates.length;
    }

    /**
     * Returns a clone of the {@linkplain #coordinates} array.
     */
    @Override
    public double[] getCoordinates() {
        return coordinates.clone();
    }

    /**
     * Returns the coordinate value at the given dimension.
     *
     * @param  dimension  the dimension from 0 inclusive to {@linkplain #getDimension} exclusive.
     * @return the coordinate value at the given dimension.
     * @throws IndexOutOfBoundsException if the given index is out of bounds.
     */
    @Override
    public double getCoordinate(final int dimension) throws IndexOutOfBoundsException {
        return coordinates[dimension];
    }

    /**
     * Sets the coordinate value at the given dimension.
     *
     * @param  dimension  the dimension from 0 inclusive to {@linkplain #getDimension} exclusive.
     * @param  value       the coordinate value to set.
     * @throws IndexOutOfBoundsException if the given index is out of bounds.
     */
    @Override
    public void setCoordinate(final int dimension, final double value) throws IndexOutOfBoundsException {
        coordinates[dimension] = value;
    }

    /**
     * Returns {@code true} if the given {@link DirectPosition} contains the same coordinate values
     * as this {@link DirectPosition}.
     *
     * @param  object  the {@link DirectPosition} to compare with this {@link DirectPosition}.
     * @return {@code true} if the given {@link DirectPosition} contains the same coordinate values
     *         as this {@link DirectPosition}.
     */
    @Override
    public boolean equals(final Object object) {
        if (object instanceof DirectPosition) {
            final DirectPosition other = (DirectPosition) object;
            return Arrays.equals(coordinates, other.getCoordinates()) &&
                   Objects.equals(crs, other.getCoordinateReferenceSystem());
        }
        return false;
    }

    /**
     * Returns a hash code value for this {@link DirectPosition}.
     */
    @Override
    public int hashCode() {
        return Arrays.hashCode(coordinates) + Objects.hashCode(crs);
    }

    /**
     * Returns a {@linkplain StringBuilder} containing the {@linkplain #coordinates} values.
     */
    @Override
    public String toString() {
        final StringBuilder buffer = new StringBuilder("POINT");
        buffer.append('(');
        for (final double coordinate : coordinates) {
            if (buffer.length() != 7) {
                buffer.append(' ');
            }
            buffer.append(coordinate);
        }
        buffer.append(')');
        return buffer.toString();
    }
}

