package org.apache.hc.client5.http.classic.methods;

import java.net.URI;
import java.util.HashSet;
import java.util.Iterator;
import java.util.Set;

import org.apache.hc.core5.http.HeaderElement;
import org.apache.hc.core5.http.HttpResponse;
import org.apache.hc.core5.http.message.MessageSupport;
import org.apache.hc.core5.util.Args;

/**
 * HTTP OPTIONS method.
 *
 * @since 4.0
 */
public class HttpOptions extends HttpUriRequestBase {

    private static final long serialVersionUID = 1L;

    /**
     * The method name {@value}.
     */
    public final static String METHOD_NAME = "OPTIONS";

    /**
     * Creates a new HTTP OPTIONS method with the given URI.
     *
     * @param uri the request URI.
     * @throws IllegalArgumentException if the request URI is invalid.
     */
    public HttpOptions(final URI uri) {
        super(METHOD_NAME, uri);
    }

    /**
     * Creates a new HTTP OPTIONS method with the given URI.
     *
     * @param uri the request URI.
     * @throws IllegalArgumentException if the request URI is invalid.
     */
    public HttpOptions(final String uri) {
        this(URI.create(uri));
    }

    @Override
    public String getMethod() {
        return METHOD_NAME;
    }

    /**
     * Gets the set of methods allowed by the server in response to this request.
     *
     * @param response the HTTP response.
     * @return the set of methods allowed by the server in response to this request.
     */
    public Set<String> getAllowedMethods(final HttpResponse response) {
        Args.notNull(response, "HTTP response");
        final Iterator<HeaderElement> it = MessageSupport.iterate(response, "Allow");
        final Set<String> allowedMethods = new HashSet<>();
        while (it.hasNext()) {
            allowedMethods.add(it.next().getName());
        }
        return allowedMethods;
    }

}

