package org.apache.hc.client5.http.observation;

import java.util.EnumSet;
import java.util.List;
import java.util.function.Predicate;

import io.micrometer.core.instrument.Tag;
import io.micrometer.observation.ObservationPredicate;
import org.apache.hc.core5.util.Args;

/**
 * Configuration for HTTP client metrics and tracing.
 *
 * @since 5.6
 */
public final class ObservingOptions {

    /**
     * Enumeration of available metrics.
     */
    public enum MetricSet {

        /**
         * Basic metrics: request count, latency histograms, and active connections.
         */
        BASIC,

        /**
         * I/O metrics: bytes read/written, socket connects, and socket reads/writes.
         */
        IO,

        /**
         * Connection pool metrics: pool size, leased connections, and pending requests.
         */
        CONN_POOL,

        /**
         * TLS metrics: handshake latency histograms, session reuse rate, and session cache size.
         * <p>
         * Requires {@link org.apache.hc.core5.http.nio.AsyncSSLSocketFactory} wrapped in
         * {@link org.apache.hc.core5.http.nio.AsyncMeteredSSLSocketFactory}.
         */
        TLS,

        /**
         * DNS metrics: latency histograms, cache hits, and cache misses.
         * <p>
         * Requires {@link org.apache.hc.core5.http.nio.AsyncDNSResolver} wrapped in
         * {@link org.apache.hc.core5.http.nio.AsyncMeteredDNSResolver}.
         */
        DNS
    }

    /**
     * Enumeration of available tag levels.
     */
    public enum TagLevel {

        /**
         * Low tag level: method, status, protocol, target, and URI.
         */
        LOW,

        /**
         * Extended tag level: all low tags plus request headers and response headers.
         */
        EXTENDED
    }

    /**
     * Function for customizing tags.
     */
    @FunctionalInterface
    public interface TagCustomizer {

        /**
         * Customize the tag list.
         *
         * @param base  base tag list
         * @param method HTTP method
         * @param status response status
         * @param protocol protocol
         * @param target target
         * @param uri URI
         * @return customized tag list
         */
        List<Tag> apply(List<Tag> base, String method, int status, String protocol, String target, String uri);
    }

    /**
     * All available metrics.
     */
    public static EnumSet<MetricSet> allMetricSets() {
        return EnumSet.allOf(MetricSet.class);
    }

    /**
     * Enabled metrics.
     */
    public final EnumSet<MetricSet> metricSets;

    /**
     * Tag level.
     */
    public final TagLevel tagLevel;

    /**
     * Micrometer observation filter.
     */
    public final ObservationPredicate micrometerFilter;

    /**
     * Span sampling predicate.
     */
    public final Predicate<String> spanSampling;

    /**
     * Tag customizer.
     */
    public final TagCustomizer tagCustomizer;

    /**
     * Creates builder instance.
     */
    public static Builder builder() {
        return new Builder();
    }

    /**
     * Builder for {@link ObservingOptions}.
     */
    public static final class Builder {

        private EnumSet<MetricSet> sets;
        private TagLevel tag;
        private ObservationPredicate obs;
        private Predicate<String> span;
        private TagCustomizer customizer;

        /**
         * Sets the enabled metrics.
         *
         * @param s enabled metrics
         * @return this instance
         */
        public Builder metrics(final EnumSet<MetricSet> s) {
            this.sets = EnumSet.copyOf(s);
            return this;
        }

        /**
         * Sets the tag level.
         *
         * @param t tag level
         * @return this instance
         */
        public Builder tagLevel(final TagLevel t) {
            this.tag = Args.notNull(t, "tag");
            return this;
        }

        /**
         * Sets the Micrometer observation filter.
         *
         * @param p observation filter
         * @return this instance
         */
        public Builder micrometerFilter(final ObservationPredicate p) {
            this.obs = Args.notNull(p, "pred");
            return this;
        }

        /**
         * Sets the span sampling predicate.
         *
         * @param p span sampling predicate
         * @return this instance
         */
        public Builder spanSampling(final Predicate<String> p) {
            this.span = Args.notNull(p, "pred");
            return this;
        }

        /**
         * Sets the tag customizer.
         *
         * @param c tag customizer
         * @return this instance
         */
        public Builder tagCustomizer(final TagCustomizer c) {
            this.customizer = Args.notNull(c, "tagCustomizer");
            return this;
        }

        /**
         * Builds {@link ObservingOptions}.
         */
        public ObservingOptions build() {
            return new ObservingOptions(this);
        }
    }

    /**
     * Default options.
     */
    public static final ObservingOptions DEFAULT = builder().build();

    private ObservingOptions(final Builder b) {
        this.metricSets = b.sets;
        this.tagLevel = b.tag;
        this.micrometerFilter = b.obs;
        this.spanSampling = b.span;
        this.tagCustomizer = b.customizer;
    }
}

