package org.apache.hc.client5.http.auth;

import java.util.Queue;

import org.apache.hc.core5.util.Args;

/**
 * Represents a sequence of authentication challenges and
 * authentication responses sent back and forth during an
 * authentication handshake.
 *
 * @since 4.3
 */
public class AuthExchange {

    /**
     * Enumeration of various states an authentication exchange
     * can be in.
     */
    public enum State {

        /**
         * The initial state of an authentication exchange.
         */
        UNCHALLENGED,
        /**
         * The state in which authentication challenges are received
         * from the server.
         */
        CHALLENGED,
        /**
         * The state in which authentication handshake messages
         * are exchanged.
         */
        HANDSHAKE,
        /**
         * The state in which authentication failures are handled.
         */
        FAILURE,
        /**
         * The state in which authentication successes are handled.
         */
        SUCCESS

    }

    private State state;
    private AuthScheme authScheme;
    private Queue<AuthScheme> authOptions;
    private String pathPrefix;

    /**
     * Creates a new AuthExchange instance.
     */
    public AuthExchange() {
        super();
        this.state = State.UNCHALLENGED;
    }

    /**
     * Resets this authentication exchange so that it can be reused.
     */
    public void reset() {
        this.state = State.UNCHALLENGED;
        this.authOptions = null;
        this.authScheme = null;
        this.pathPrefix = null;
    }

    /**
     * Gets the current state of this authentication exchange.
     *
     * @return the current state of this authentication exchange
     */
    public State getState() {
        return this.state;
    }

    /**
     * Sets the current state of this authentication exchange.
     *
     * @param state the current state of this authentication exchange
     */
    public void setState(final State state) {
        this.state = state != null ? state : State.UNCHALLENGED;
    }

    /**
     * Gets the authentication scheme currently selected in this
     * authentication exchange.
     *
     * @return the authentication scheme currently selected in this
     *   authentication exchange
     */
    public AuthScheme getAuthScheme() {
        return this.authScheme;
    }

    /**
     * Gets whether the authentication scheme in this exchange
     * is connection based.
     *
     * @return whether the authentication scheme in this exchange
     *   is connection based
     */
    public boolean isConnectionBased() {
        return this.authScheme != null && this.authScheme.isConnectionBased();
    }

    /**
     * Gets the path prefix associated with this authentication
     * exchange.
     *
     * @return the path prefix associated with this authentication
     *   exchange
     */
    public String getPathPrefix() {
        return this.pathPrefix;
    }

    /**
     * Sets the path prefix associated with this authentication
     * exchange.
     *
     * @param pathPrefix the path prefix associated with this authentication
     *   exchange
     */
    public void setPathPrefix(final String pathPrefix) {
        this.pathPrefix = pathPrefix;
    }

    /**
     * Selects the given authentication scheme in this exchange.
     *
     * @param authScheme the authentication scheme to select
     */
    public void select(final AuthScheme authScheme) {
        Args.notNull(authScheme, "Auth scheme");
        this.authScheme = authScheme;
        this.authOptions = null;
    }

    /**
     * Gets the queue of authentication options associated with
     * this authentication exchange.
     *
     * @return the queue of authentication options associated with
     *   this authentication exchange
     */
    public Queue<AuthScheme> getAuthOptions() {
        return this.authOptions;
    }

    /**
     * Sets the queue of authentication options associated with
     * this authentication exchange.
     *
     * @param authOptions the queue of authentication options associated with
     *   this authentication exchange
     */
    public void setOptions(final Queue<AuthScheme> authOptions) {
        this.authOptions = Args.notEmpty(authOptions, "Queue of auth options");
    }

    @Override
    public String toString() {
        final StringBuilder buffer = new StringBuilder();
        buffer.append('[');
        buffer.append(this.state);
        if (this.authScheme != null) {
            buffer.append(' ');
            buffer.append(this.authScheme);
        }
        buffer.append(']');
        return buffer.toString();
    }

}

