/**
 * Records request latency and response status counters for classic
 * (blocking) clients.
 *
 * <p>If {@link ObservingOptions#spanSampling} is enabled, latency is
 * measured using a {@link Timer} and a {@link Counter} is incremented
 * for each response status. If {@link ObservingOptions#tagLevel} is
 * {@link ObservingOptions.TagLevel#EXTENDED}, the {@link Tag}s
 * {@code protocol} and {@code target} are added to the {@link Timer}
 * and {@link Counter}.</p>
 *
 * <p>Metrics:</p>
 * <ul>
 *   <li>{@code &lt;prefix&gt;.request} (timer)</li>
 *   <li>{@code &lt;prefix&gt;.response} (counter)</li>
 *   <li>{@code &lt;prefix&gt;.inflight} (gauge)</li>
 * </ul>
 *
 * <p>Tags:</p>
 * <ul>
 *   <li>{@code method} (string)</li>
 *   <li>{@code status} (string)</li>
 *   <li>{@code protocol} (string)</li>
 *   <li>{@code target} (string)</li>
 *   <li>{@code kind} (string)</li>
 *   <li>common tags (if {@link MetricConfig#commonTags} is set)</li>
 * </ul>
 *
 * @since 5.6
 */
public final class TimerExec implements ExecChainHandler {

    private final MeterRegistry registry;
    private final ObservingOptions cfg;
    private final MetricConfig mc;
    private final AtomicInteger inflight;

    /**
     * Create a new TimerExec.
     *
     * @param reg MeterRegistry
     * @param cfg ObservingOptions
     */
    public TimerExec(final MeterRegistry reg, final ObservingOptions cfg) {
        this(reg, cfg, null);
    }

    /**
     * Create a new TimerExec.
     *
     * @param reg MeterRegistry
     * @param cfg ObservingOptions
     * @param mc MetricConfig
     */
    public TimerExec(final MeterRegistry reg, final ObservingOptions cfg, final MetricConfig mc) {
        this.registry = Args.notNull(reg, "registry");
        this.cfg = Args.notNull(cfg, "config");
        this.mc = mc != null ? mc : MetricConfig.builder().build();
        this.inflight = new AtomicInteger(0);

        // Register the in-flight gauge if it doesn't exist
        if (registry.find(mc.prefix + ".inflight")
                .tags("kind", "classic")
                .tags(mc.commonTags)
                .gauge() == null) {
            Gauge.builder(mc.prefix + ".inflight", inflight, AtomicInteger::doubleValue)
                    .tag("kind", "classic")
                    .tags(mc.commonTags)
                    .register(registry);
        }
    }

    @Override
    public ClassicHttpResponse execute(
            final ClassicHttpRequest request,
            final ExecChain.Scope scope,
            final ExecChain chain) throws IOException, HttpException {
        final String requestUri = request.getRequestUri();
        if (!cfg.spanSampling.test(requestUri)) {
            return chain.proceed(request, scope);
        }

        final int inflightBefore = inflight.incrementAndGet();
        final long start = System.nanoTime();
        ClassicHttpResponse response = null;
        try {
            response = chain.proceed(request, scope);
            return response;
        } finally {
            final long durNanos = System.nanoTime() - start;
            final int status = response != null ? response.getCode() : 599;
            final List<Tag> tags = new ArrayList<>(4);
            tags.add(Tag.of("method", request.getMethod()));
            tags.add(Tag.of("status", Integer.toString(status)));
            if (cfg.tagLevel == ObservingOptions.TagLevel.EXTENDED) {
                final String protocol = scope.route.getTargetHost().getSchemeName();
                final String target = scope.route.getTargetHost().getHostName();
                tags.add(Tag.of("protocol", protocol));
                tags.add(Tag.of("target", target));
            }

            // Record the request latency
            Timer.builder(mc.prefix + ".request")
                    .tags(mc.commonTags)
                    .tags(tags)
                    .publishPercentiles(mc.percentiles)
                    .serviceLevelObjectives(mc.slo)
                    .register(registry)
                    .record(durNanos, TimeUnit.NANOSECONDS);

            // Record the response status
            Counter.builder(mc.prefix + ".response")
                    .tags(mc.commonTags)
                    .tags(tags)
                    .register(registry)
                    .increment();

            inflight.decrementAndGet();
        }
    }
}

