package org.apache.hc.core5.websocket.extension;

import java.io.ByteArrayOutputStream;
import java.util.zip.Deflater;
import java.util.zip.Inflater;

import org.apache.hc.core5.annotation.Internal;
import org.apache.hc.core5.websocket.exceptions.WebSocketProtocolException;
import org.apache.hc.core5.websocket.frame.FrameHeaderBits;

/**
 * RFC 7692 permessage-deflate extension.
 *
 * <p>The extension is negotiated by the client and server in the WebSocket handshake. The client
 * and server agree on a set of parameters that define the maximum window size and whether to
 * support context takeover. The extension is then enabled on both sides of the connection.</p>
 *
 * <p>When enabled, the client and server use the RSV1 bit in the WebSocket frame header to indicate
 * the extension is in use. The client then compresses the payload of each message or fragment
 * using the DEFLATE algorithm and sets the RSV1 bit in the header of the first frame. The server
 * decompresses the payload using the DEFLATE algorithm with the RFC 7692 sync flush tail
 * appended to the end of the payload.</p>
 */
@Internal
public final class PerMessageDeflate implements WebSocketExtensionChain {

    private static final byte[] TAIL = new byte[]{0x00, 0x00, (byte) 0xFF, (byte) 0xFF};

    private final boolean enabled;
    private final boolean serverNoContextTakeover;
    private final boolean clientNoContextTakeover;
    private final Integer clientMaxWindowBits;
    private final Integer serverMaxWindowBits;

    /**
     * Create a new PerMessageDeflate extension.
     *
     * @param enabled whether the extension is enabled
     * @param serverNoContextTakeover whether the server supports context takeover
     * @param clientNoContextTakeover whether the client supports context takeover
     * @param clientMaxWindowBits the client's maximum window bits
     * @param serverMaxWindowBits the server's maximum window bits
     */
    public PerMessageDeflate(
            final boolean enabled,
            final boolean serverNoContextTakeover,
            final boolean clientNoContextTakeover,
            final Integer clientMaxWindowBits,
            final Integer serverMaxWindowBits) {
        this.enabled = enabled;
        this.serverNoContextTakeover = serverNoContextTakeover;
        this.clientNoContextTakeover = clientNoContextTakeover;
        this.clientMaxWindowBits = clientMaxWindowBits;
        this.serverMaxWindowBits = serverMaxWindowBits;
    }

    @Override
    public int rsvMask() {
        return FrameHeaderBits.RSV1;
    }

    @Override
    public Encoder newEncoder() {
        if (!enabled) {
            return (data, first, fin) -> new Encoded(data, false);
        }
        return new Encoder();
    }

    @Override
    public Decoder newDecoder() {
        if (!enabled) {
            return payload -> payload;
        }
        return new Decoder();
    }

    public boolean isEnabled() {
        return enabled;
    }

    public boolean isServerNoContextTakeover() {
        return serverNoContextTakeover;
    }

    public boolean isClientNoContextTakeover() {
        return clientNoContextTakeover;
    }

    public Integer getClientMaxWindowBits() {
        return clientMaxWindowBits;
    }

    public Integer getServerMaxWindowBits() {
        return serverMaxWindowBits;
    }

    private final class Encoder implements WebSocketExtensionChain.Encoder {

        private final Deflater def = new Deflater(Deflater.DEFAULT_COMPRESSION, true);

        @Override
        public Encoded encode(final byte[] data, final boolean first, final boolean fin) {
            if (first && fin) {
                return new Encoded(compressMessage(data), first);
            }
            return new Encoded(compressFragment(data, fin), first);
        }

        @Override
        public void close() {
            def.end();
        }

        private byte[] compressMessage(final byte[] data) {
            return doDeflate(data, true, true, clientNoContextTakeover);
        }

        private byte[] compressFragment(final byte[] data, final boolean fin) {
            return doDeflate(data, fin, !fin, fin && clientNoContextTakeover);
        }

        private byte[] doDeflate(
                final byte[] data,
                final boolean fin,
                final boolean stripTail,
                final boolean maybeReset) {
            final byte[] input = data == null ? new byte[0] : data;
            def.setInput(input);
            final ByteArrayOutputStream buf = new ByteArrayOutputStream(
                    Math.max(128, input.length / 2));
            final byte[] tmp = new byte[Math.min(16384, Math.max(1024, input.length))];
            int n;
            while (true) {
                n = def.deflate(tmp, 0, tmp.length, Deflater.SYNC_FLUSH);
                if (n > 0) {
                    buf.write(tmp, 0, n);
                }
                if (n == tmp.length) {
                    continue;
                }
                break;
            }
            final byte[] output = buf.toByteArray();
            if (stripTail && output.length > 4) {
                if (output[output.length - 4] == 0x00 && output[output.length - 3] == 0x00
                        && output[output.length - 2] == (byte) 0xFF && output[output.length - 1] == (byte) 0xFF) {
                    final byte[] tmp = new byte[output.length - 4];
                    System.arraycopy(output, 0, tmp, 0, tmp.length);
                    output = tmp;
                }
            }
            if (fin && maybeReset) {
                def.reset();
            }
            return output;
        }
    }

    private final class Decoder implements WebSocketExtensionChain.Decoder {

        private final Inflater inf = new Inflater(true);

        @Override
        public byte[] decode(final byte[] compressedMessage) throws Exception {
            return decode(compressedMessage, 0L);
        }

        @Override
        public byte[] decode(final byte[] compressedMessage, final long maxDecodedSize) throws Exception {
            final byte[] withTail = compressedMessage == null || compressedMessage.length == 0
                    ? TAIL.clone()
                    : new byte[compressedMessage.length + 4];
            if (compressedMessage != null) {
                System.arraycopy(compressedMessage, 0, withTail, 0, compressedMessage.length);
                System.arraycopy(TAIL, 0, withTail, compressedMessage.length, 4);
            }
            inf.setInput(withTail);
            final ByteArrayOutputStream buf = new ByteArrayOutputStream(
                    Math.max(128, withTail.length * 2));
            final byte[] tmp = new byte[Math.min(16384, Math.max(1024, withTail.length * 2))];
            int produced = 0;
            while (!inf.needsInput()) {
                final int n = inf.inflate(tmp);
                if (n > 0) {
                    if (maxDecodedSize > 0L && produced + n > maxDecodedSize) {
                        throw new WebSocketProtocolException(
                                "Message too big",
                                WebSocketProtocolException.CLOSE_CODE_TOO_BIG);
                    }
                    buf.write(tmp, 0, n);
                    produced += n;
                }
                if (n == 0) {
                    break;
                }
            }
            if (serverNoContextTakeover) {
                inf.reset();
            }
            return buf.toByteArray();
        }

        @Override
        public void close() {
            inf.end();
        }
    }
}

