package org.apache.hc.client5.http.impl.auth;

import java.util.ArrayList;
import java.util.List;

import org.apache.hc.client5.http.auth.AuthChallenge;
import org.apache.hc.client5.http.auth.ChallengeType;
import org.apache.hc.core5.http.NameValuePair;
import org.apache.hc.core5.http.ParseException;
import org.apache.hc.core5.http.message.BasicHeaderValueParser;
import org.apache.hc.core5.http.message.BasicNameValuePair;
import org.apache.hc.core5.http.message.ParserCursor;
import org.apache.hc.core5.util.TextUtils;
import org.apache.hc.core5.util.Tokenizer;

/**
 * HTTP authentication challenge parser.
 *
 * @since 4.3
 */
public class AuthChallengeParser {

    /**
     * Default instance of {@link AuthChallengeParser}.
     */
    public static final AuthChallengeParser INSTANCE = new AuthChallengeParser();

    private final Tokenizer tokenParser = Tokenizer.INSTANCE;

    private static final char BLANK = ' ';
    private static final char COMMA_CHAR = ',';
    private static final char EQUAL_CHAR = '=';

    private static final Tokenizer.Delimiter TERMINATORS = Tokenizer.delimiters(BLANK, EQUAL_CHAR, COMMA_CHAR);
    private static final Tokenizer.Delimiter DELIMITER = Tokenizer.delimiters(COMMA_CHAR);
    private static final Tokenizer.Delimiter SPACE = Tokenizer.delimiters(BLANK);

    static class ChallengeInt {
        final String schemeName;
        final List<NameValuePair> params;

        ChallengeInt(final String schemeName) {
            this.schemeName = schemeName;
            this.params = new ArrayList<>();
        }

        @Override
        public String toString() {
            return "ChallengeInternal{" +
                    "schemeName='" + schemeName + '\'' +
                    ", params=" + params +
                    '}';
        }
    }

    /**
     * Parses a list of auth challenges from a given char sequence.
     *
     * @param challengeType the challenge type
     * @param buffer the char sequence to be parsed
     * @param cursor the parser cursor
     * @return a list of auth challenges
     * @throws ParseException if the given char sequence could not be parsed
     */
    public List<AuthChallenge> parse(
            final ChallengeType challengeType,
            final CharSequence buffer,
            final ParserCursor cursor) throws ParseException {
        this.tokenParser.skipWhiteSpace(buffer, cursor);
        if (cursor.atEnd()) {
            throw new ParseException("Malformed auth challenge");
        }
        final String schemeName = this.tokenParser.parseToken(buffer, cursor, SPACE);
        if (TextUtils.isBlank(schemeName)) {
            throw new ParseException("Malformed auth challenge");
        }
        final ChallengeInt currentChallenge = new ChallengeInt(schemeName);
        final List<ChallengeInt> internalChallenges = new ArrayList<>();
        while (!cursor.atEnd()) {
            internalChallenges.add(parseChallenge(buffer, cursor, currentChallenge));
            if (currentChallenge == null) {
                break;
            }
        }
        final List<AuthChallenge> result = new ArrayList<>(internalChallenges.size());
        for (final ChallengeInt internalChallenge : internalChallenges) {
            result.add(parseInt(challengeType, internalChallenge));
        }
        return result;
    }

    /**
     * Parses a single auth challenge from a given char sequence.
     *
     * @param challengeType the challenge type
     * @param schemeName the auth scheme name
     * @param buffer the char sequence to be parsed
     * @param cursor the parser cursor
     * @return a single auth challenge
     */
    public AuthChallenge parse(
            final ChallengeType challengeType,
            final String schemeName,
            final CharSequence buffer,
            final ParserCursor cursor) {
        final List<NameValuePair> params = new ArrayList<>();
        while (!cursor.atEnd()) {
            final NameValuePair param = BasicHeaderValueParser.INSTANCE.parseNameValuePair(buffer, cursor);
            params.add(param);
        }
        if (!cursor.atEnd()) {
            final char ch = buffer.charAt(cursor.getPos());
            if (ch == COMMA_CHAR) {
                cursor.updatePos(1);
            }
        }
        return new AuthChallenge(challengeType, schemeName, null, params);
    }

    AuthChallenge parseInt(final ChallengeType challengeType, final ChallengeInt internal) {
        final List<NameValuePair> params = internal.params;
        String token68 = null;
        if (params.size() == 1) {
            final NameValuePair param = params.get(0);
            if (param.getValue() == null) {
                token68 = param.getName();
                params.clear();
            }
        }
        return new AuthChallenge(challengeType, internal.schemeName, token68, params);
    }

    ChallengeInt parseChallenge(
            final CharSequence buffer,
            final ParserCursor cursor,
            final ChallengeInt currentChallenge) throws ParseException {
        this.tokenParser.skipWhiteSpace(buffer, cursor);
        if (cursor.atEnd()) {
            return null;
        }
        final String token = parseToken(buffer, cursor);
        if (TextUtils.isBlank(token)) {
            throw new ParseException("Malformed auth challenge");
        }
        this.tokenParser.skipWhiteSpace(buffer, cursor);
        if (cursor.atEnd()) {
            currentChallenge.params.add(new BasicNameValuePair(token, null));
            return null;
        }
        if (buffer.charAt(cursor.getPos()) == EQUAL_CHAR) {
            cursor.updatePos(1);
            final String value = this.tokenParser.parseValue(buffer, cursor, DELIMITER);
            this.tokenParser.skipWhiteSpace(buffer, cursor);
            if (!cursor.atEnd() && buffer.charAt(cursor.getPos()) == COMMA_CHAR) {
                cursor.updatePos(1);
            }
            currentChallenge.params.add(new BasicNameValuePair(token, value));
        } else if (buffer.charAt(cursor.getPos()) == COMMA_CHAR) {
            cursor.updatePos(1);
            currentChallenge.params.add(new BasicNameValuePair(token, null));
        } else {
            final ChallengeInt nextChallenge = new ChallengeInt(token);
            if (currentChallenge.params.isEmpty()) {
                throw new ParseException("Malformed auth challenge");
            }
            return nextChallenge;
        }
        return currentChallenge;
    }

    String parseToken(final CharSequence buf, final ParserCursor cursor) {
        final int pos = cursor.getPos();
        final int upper = cursor.getUpperBound();
        final StringBuilder buffer = new StringBuilder();
        while (pos < upper) {
            final char ch = buf.charAt(pos);
            if (TERMINATORS.contains(ch)) {
                break;
            }
            if (ch == EQUAL_CHAR) {
                if (pos + 1 < upper) {
                    final char next = buf.charAt(pos + 1);
                    if (next != EQUAL_CHAR) {
                        break;
                    }
                }
            }
            if (ch == BLANK || ch == COMMA_CHAR) {
                break;
            }
            buffer.append(ch);
            cursor.updatePos(1);
        }
        return buffer.toString();
    }

}

