package org.apache.hc.client5.http.protocol;

import java.net.URI;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Set;

/**
 * Represents a collection of {@link java.net.URI}s
 * that are used to keep track of redirect locations
 * in the HTTP protocol.
 *
 * @since 4.3
 */
public final class RedirectLocations {

    private final Set<URI> unique = new HashSet<>();
    private final List<URI> all = new ArrayList<>();

    /**
     * Creates a new instance.
     */
    public RedirectLocations() {
        super();
    }

    /**
     * Checks whether the given {@link java.net.URI} is contained
     * in this collection.
     *
     * @param uri the {@link java.net.URI} to be checked
     * @return {@code true} if the given {@link java.net.URI} is contained
     * in this collection, otherwise {@code false}
     */
    public boolean contains(final URI uri) {
        return unique.contains(uri);
    }

    /**
     * Adds the given {@link java.net.URI} to this collection.
     *
     * @param uri the {@link java.net.URI} to be added
     */
    public void add(final URI uri) {
        unique.add(uri);
        all.add(uri);
    }

    /**
     * Returns a list of {@link java.net.URI}s contained in this collection.
     *
     * @return a list of {@link java.net.URI}s contained in this collection
     */
    public List<URI> getAll() {
        return new ArrayList<>(this.all);
    }

    /**
     * Returns the {@link java.net.URI} at the given index.
     *
     * @param index the index
     * @return the {@link java.net.URI} at the given index
     */
    public URI get(final int index) {
        return all.get(index);
    }

    /**
     * Returns the number of {@link java.net.URI}s contained in this collection.
     *
     * @return the number of {@link java.net.URI}s contained in this collection
     */
    public int size() {
        return all.size();
    }

    /**
     * Clears this collection.
     */
    public void clear() {
        unique.clear();
        all.clear();
    }

}

