package org.apache.hc.client5.http.observation.impl;

import java.io.IOException;

import io.micrometer.observation.Observation;
import io.micrometer.observation.ObservationRegistry;

import org.apache.hc.client5.http.async.AsyncExecCallback;
import org.apache.hc.client5.http.async.AsyncExecChain;
import org.apache.hc.client5.http.async.AsyncExecChainHandler;
import org.apache.hc.client5.http.observation.ObservingOptions;
import org.apache.hc.core5.http.EntityDetails;
import org.apache.hc.core5.http.HttpException;
import org.apache.hc.core5.http.HttpRequest;
import org.apache.hc.core5.http.HttpResponse;
import org.apache.hc.core5.http.nio.AsyncDataConsumer;
import org.apache.hc.core5.http.nio.AsyncEntityProducer;
import org.apache.hc.core5.util.Args;

/**
 * Micrometer {@link AsyncExecChainHandler} that wraps each request/response
 * with an {@link Observation}.
 *
 * <p>Usage:</p>
 * <pre>
 * CloseableHttpAsyncClient client = HttpClients.custom()
 *     .addInterceptorFirst(new ObservationAsyncExecInterceptor())
 *     .build();
 * </pre>
 *
 * <p>The {@link ObservationRegistry} can be customized with
 * {@link ObservingOptions}.</p>
 *
 * @since 5.6
 */
public final class ObservationAsyncExecInterceptor implements AsyncExecChainHandler {

    private final ObservationRegistry registry;
    private final ObservingOptions opts;

    /**
     * @since 5.6
     */
    public ObservationAsyncExecInterceptor(
            final ObservationRegistry registry,
            final ObservingOptions opts) {
        this.registry = Args.notNull(registry, "observationRegistry");
        this.opts = opts != null ? opts : ObservingOptions.DEFAULT;
    }

    @Override
    public void execute(
            final HttpRequest request,
            final AsyncEntityProducer entityProducer,
            final AsyncExecChain.Scope scope,
            final AsyncExecChain chain,
            final AsyncExecCallback asyncExecCallback) throws HttpException, IOException {
        if (!opts.spanSampling.test(request.getRequestUri())) {
            chain.proceed(request, entityProducer, scope, asyncExecCallback);
            return;
        }
        final HttpClientObservationContext observationContext = new HttpClientObservationContext(request);
        final Observation observation = Observation.createNotStarted("http.client.request", () -> observationContext, registry)
                .contextualName(request.getMethod() + " " + request.getRequestUri())
                .lowCardinalityKeyValue("http.method", request.getMethod())
                .lowCardinalityKeyValue("net.peer.name", scope.route.getTargetHost().getHostName())
                .start();
        final AsyncExecCallback wrappedCallback = new AsyncExecCallback() {
            @Override
            public AsyncDataConsumer handleResponse(
                    final HttpResponse response,
                    final EntityDetails entityDetails) throws HttpException, IOException {
                observationContext.setResponse(response);
                observation.lowCardinalityKeyValue("http.status_code", Integer.toString(response.getCode()));
                return asyncExecCallback.handleResponse(response, entityDetails);
            }

            @Override
            public void handleInformationResponse(
                    final HttpResponse response) throws HttpException, IOException {
                asyncExecCallback.handleInformationResponse(response);
            }

            @Override
            public void completed() {
                observation.stop();
                asyncExecCallback.completed();
            }

            @Override
            public void failed(final Exception cause) {
                observation.error(cause);
                observation.stop();
                asyncExecCallback.failed(cause);
            }
        };
        try {
            chain.proceed(request, entityProducer, scope, wrappedCallback);
        } catch (final IOException | HttpException | RuntimeException | Error ex) {
            observation.error(ex);
            observation.stop();
            throw ex;
        }
    }
}

