/**
 * Cookie {@link CommonCookieAttributeHandler} that uses the Public Suffix List
 * to block {@link Cookie}s with domain names that are not under the same
 * registrant as the origin site.
 *
 * @since 4.4
 */
@Contract(threading = ThreadingBehavior.STATELESS)
public class PublicSuffixDomainFilter implements CommonCookieAttributeHandler {

    private static final Logger LOG = LoggerFactory.getLogger(PublicSuffixDomainFilter.class);

    private final CommonCookieAttributeHandler handler;
    private final PublicSuffixMatcher publicSuffixMatcher;
    private final Map<String, Boolean> localDomainMap;

    private static Map<String, Boolean> createLocalDomainMap() {
        final Map<String, Boolean> localDomainMap = new ConcurrentHashMap<>();
        localDomainMap.put(".localhost.", Boolean.TRUE);
        localDomainMap.put(".test.", Boolean.TRUE);
        localDomainMap.put(".local.", Boolean.TRUE);
        localDomainMap.put(".local", Boolean.TRUE);
        localDomainMap.put(".localdomain", Boolean.TRUE);
        return localDomainMap;
    }

    /**
     * Creates a new instance.
     *
     * @param handler the {@link CommonCookieAttributeHandler} to be wrapped
     * @param publicSuffixMatcher the {@link PublicSuffixMatcher} to be used
     */
    public PublicSuffixDomainFilter(
            final CommonCookieAttributeHandler handler,
            final PublicSuffixMatcher publicSuffixMatcher) {
        this.handler = Args.notNull(handler, "Cookie handler");
        this.publicSuffixMatcher = Args.notNull(publicSuffixMatcher, "Public suffix matcher");
        this.localDomainMap = createLocalDomainMap();
    }

    /**
     * Creates a new instance.
     *
     * @param handler the {@link CommonCookieAttributeHandler} to be wrapped
     * @param suffixList the {@link PublicSuffixList} to be used
     */
    public PublicSuffixDomainFilter(
            final CommonCookieAttributeHandler handler,
            final PublicSuffixList suffixList) {
        this.handler = Args.notNull(handler, "Cookie handler");
        this.publicSuffixMatcher = new PublicSuffixMatcher(
                suffixList.getRules(), suffixList.getExceptions());
        this.localDomainMap = createLocalDomainMap();
    }

    private boolean verifyHost(final String host) {
        if (publicSuffixMatcher.verify(host)) {
            return true;
        }
        if (LOG.isDebugEnabled()) {
            LOG.debug("Public Suffix List verification failed for host '{}'", host);
        }
        return false;
    }

    @Override
    public boolean match(final Cookie cookie, final CookieOrigin origin) {
        final String host = cookie.getDomain();
        if (host == null) {
            return false;
        }
        if (host.contains(".")) {
            final int i = host.indexOf('.');
            final String domain = host.substring(i);
            if (!localDomainMap.containsKey(domain)) {
                if (!verifyHost(host)) {
                    return false;
                }
            }
        } else {
            if (!host.equalsIgnoreCase(origin.getHost())) {
                if (!verifyHost(host)) {
                    return false;
                }
            }
        }
        return handler.match(cookie, origin);
    }

    @Override
    public void parse(final SetCookie cookie, final String value) throws MalformedCookieException {
        handler.parse(cookie, value);
    }

    @Override
    public void validate(final Cookie cookie, final CookieOrigin origin) throws MalformedCookieException {
        handler.validate(cookie, origin);
    }

    @Override
    public String getAttributeName() {
        return handler.getAttributeName();
    }

    /**
     * Decorates the given {@link CommonCookieAttributeHandler} with the Public Suffix List
     * filtering.
     *
     * @param handler the {@link CommonCookieAttributeHandler} to be decorated
     * @param publicSuffixMatcher the {@link PublicSuffixMatcher} to be used
     */
    public static CommonCookieAttributeHandler decorate(
            final CommonCookieAttributeHandler handler,
            final PublicSuffixMatcher publicSuffixMatcher) {
        Args.notNull(handler, "Cookie attribute handler");
        if (publicSuffixMatcher != null) {
            return new PublicSuffixDomainFilter(handler, publicSuffixMatcher);
        }
        return handler;
    }

}

