package org.apache.hc.client5.http.entity.mime;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import org.apache.hc.core5.http.NameValuePair;

/**
 * Minimal MIME field representation.
 *
 * @since 4.3
 */
public class MimeField {

    private final String name;
    private final String value;
    private final List<NameValuePair> parameters;

    /**
     * Creates a new MimeField with the specified name and value.
     *
     * @param name the field name
     * @param value the field value
     */
    public MimeField(final String name, final String value) {
        super();
        this.name = name;
        this.value = value;
        this.parameters = Collections.emptyList();
    }

    /**
     * Creates a new MimeField with the specified name, value and parameters.
     *
     * @param name the field name
     * @param value the field value
     * @param parameters the field parameters
     */
    public MimeField(final String name, final String value, final List<NameValuePair> parameters) {
        super();
        this.name = name;
        this.value = value;
        this.parameters = parameters != null ? Collections.unmodifiableList(new ArrayList<>(parameters)) : Collections.emptyList();
    }

    /**
     * Creates a new MimeField with the same name, value and parameters as the given one.
     *
     * @param from the field to copy
     */
    public MimeField(final MimeField from) {
        this(from.name, from.value, from.parameters);
    }

    /**
     * Gets the field name.
     *
     * @return the field name
     */
    public String getName() {
        return this.name;
    }

    /**
     * Gets the field value.
     *
     * @return the field value
     */
    public String getValue() {
        return this.value;
    }

    /**
     * Gets the field body.
     *
     * @return the field body
     */
    public String getBody() {
        final StringBuilder buffer = new StringBuilder();
        buffer.append(this.value);
        this.parameters.forEach(parameter -> {
            buffer.append("; ");
            buffer.append(parameter.getName());
            buffer.append("=\"");
            final String paramValue = parameter.getValue();
            for (int i = 0; i < paramValue.length(); i++) {
                final char ch = paramValue.charAt(i);
                if (ch == '"' || ch == '\\') {
                    buffer.append('\\');
                }
                buffer.append(ch);
            }
            buffer.append("\"");
        });
        return buffer.toString();
    }

    /**
     * Gets the field parameters.
     *
     * @return the field parameters
     */
    public List<NameValuePair> getParameters() {
        return this.parameters;
    }

    @Override
    public String toString() {
        final StringBuilder buffer = new StringBuilder();
        buffer.append(this.name);
        buffer.append(": ");
        buffer.append(getBody());
        return buffer.toString();
    }

}

