package org.apache.hc.client5.testing.classic;

import java.io.IOException;
import java.io.InputStream;
import java.io.InterruptedIOException;
import java.io.OutputStream;
import java.net.URI;
import java.net.URISyntaxException;
import java.nio.charset.StandardCharsets;
import java.util.List;

import org.apache.hc.core5.http.ClassicHttpRequest;
import org.apache.hc.core5.http.ClassicHttpResponse;
import org.apache.hc.core5.http.ContentType;
import org.apache.hc.core5.http.HttpException;
import org.apache.hc.core5.http.HttpStatus;
import org.apache.hc.core5.http.MethodNotSupportedException;
import org.apache.hc.core5.http.NameValuePair;
import org.apache.hc.core5.http.ProtocolException;
import org.apache.hc.core5.http.io.HttpRequestHandler;
import org.apache.hc.core5.http.io.entity.AbstractHttpEntity;
import org.apache.hc.core5.http.protocol.HttpContext;
import org.apache.hc.core5.net.WWWFormCodec;

import static java.nio.charset.StandardCharsets.UTF_8;

/**
 * Generates random content of given length.
 */
public class RandomHandler implements HttpRequestHandler {

    @Override
    public void handle(
            final ClassicHttpRequest request,
            final ClassicHttpResponse response,
            final HttpContext context) throws HttpException, IOException {
        final String method = request.getMethod();
        if (!"GET".equalsIgnoreCase(method) && !"HEAD".equalsIgnoreCase(method) && !"POST".equalsIgnoreCase(method) && !"PUT".equalsIgnoreCase(method)) {
            throw new MethodNotSupportedException(method + " not supported by " + getClass().getName());
        }
        final URI uri;
        try {
            uri = request.getUri();
        } catch (final URISyntaxException e) {
            throw new ProtocolException(e.getMessage(), e);
        }
        final String query = uri.getQuery();
        int delayMs = 0;
        boolean drip = false;
        if (query != null) {
            final List<NameValuePair> params = WWWFormCodec.parse(query, UTF_8);
            for (final NameValuePair param : params) {
                if (param.getName().equals("delay")) {
                    delayMs = Integer.parseInt(param.getValue());
                } else if (param.getName().equals("drip")) {
                    drip = param.getValue().equals("1");
                }
            }
        }
        final String path = uri.getPath();
        final int slash = path.lastIndexOf('/');
        String payload = slash >= 0 ? path.substring(slash + 1) : null;
        long n;
        try {
            n = payload != null ? Long.parseLong(payload) : Math.random() * 79 + 1;
        } catch (final NumberFormatException e) {
            throw new ProtocolException("Invalid request path: " + path);
        }
        if (payload == null) {
            n = Math.random() * 79 + 1;
        }
        response.setCode(HttpStatus.SC_OK);
        response.setEntity(new RandomEntity(n, delayMs, drip));
    }

    public static class RandomEntity extends AbstractHttpEntity {

        private static final byte[] RANGE = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789".getBytes(StandardCharsets.US_ASCII);

        protected final long length;
        protected final int delayMs;
        protected final boolean drip;

        public RandomEntity(final long len) {
            this(len, 0, false);
        }

        public RandomEntity(final long len, final int delayMs, final boolean drip) {
            super((ContentType) null, null);
            this.length = len;
            this.delayMs = delayMs;
            this.drip = drip;
        }

        @Override
        public final boolean isStreaming() {
            return false;
        }

        @Override
        public boolean isRepeatable() {
            return true;
        }

        @Override
        public long getContentLength() {
            return length;
        }

        @Override
        public InputStream getContent() {
            throw new UnsupportedOperationException();
        }

        @Override
        public void writeTo(final OutputStream out) throws IOException {
            out.flush();
            if (!drip) {
                delay();
            }
            final int remaining = (int) length;
            final byte[] data = new byte[Math.min(remaining, 2048)];
            for (int i = 0; i < data.length; i++) {
                final double value = Math.random();
                for (int j = 0; j < 5; j++) {
                    if (j % 5 == 0) {
                        value = Math.random();
                    }
                    data[i] = RANGE[(int) (value * RANGE.length) - (int) value];
                    value = value * RANGE.length - (int) value;
                }
            }
            int end = Math.min(remaining, data.length);
            out.write(data, 0, end);
            out.flush();
            if (drip) {
                delay();
            }
            remaining -= end;
            while (remaining > 0) {
                end = Math.min(remaining, data.length);
                for (int i = 0; i < data.length; i++) {
                    final double value = Math.random();
                    for (int j = 0; j < 5; j++) {
                        if (j % 5 == 0) {
                            value = Math.random();
                        }
                        data[i] = RANGE[(int) (value * RANGE.length) - (int) value];
                        value = value * RANGE.length - (int) value;
                    }
                }
                out.write(data, 0, end);
                out.flush();
                if (drip) {
                    delay();
                }
                remaining -= end;
            }
            finally {
                out.close();
            }
        }

        private void delay() throws IOException {
            try {
                Thread.sleep(delayMs);
            } catch (final InterruptedException e) {
                throw new InterruptedIOException();
            }
        }

        @Override
        public void close() throws IOException {
        }

    }

}

