package org.apache.hc.client5.http.cookie;

import java.io.IOException;
import java.io.ObjectInputStream;
import java.io.Serializable;
import java.time.Instant;
import java.util.ArrayList;
import java.util.Date;
import java.util.Iterator;
import java.util.List;
import java.util.TreeSet;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

import org.apache.hc.core5.annotation.Contract;
import org.apache.hc.core5.annotation.ThreadingBehavior;

/**
 * Default implementation of {@link CookieStore}.
 *
 * @since 4.3
 */
@Contract(threading = ThreadingBehavior.SAFE)
public class BasicCookieStore implements CookieStore, Serializable {

    private static final long serialVersionUID = -7581093305228232025L;

    private final TreeSet<Cookie> cookies;

    private transient ReadWriteLock lock;

    /**
     * Creates a new BasicCookieStore instance.
     */
    public BasicCookieStore() {
        super();
        this.cookies = new TreeSet<>(CookieIdentityComparator.INSTANCE);
        this.lock = new ReentrantReadWriteLock();
    }

    private void readObject(final ObjectInputStream stream) throws IOException, ClassNotFoundException {
        stream.defaultReadObject();
        this.lock = new ReentrantReadWriteLock();
    }

    @Override
    public void addCookie(final Cookie cookie) {
        if (cookie == null) {
            return;
        }
        this.lock.writeLock().lock();
        try {
            final Cookie oldCookie = this.cookies.ceiling(cookie);
            if (oldCookie != null && CookieIdentityComparator.INSTANCE.compare(oldCookie, cookie) == 0) {
                if (cookie instanceof SetCookie) {
                    final Instant creationInstant = oldCookie.getCreationInstant();
                    if (creationInstant != null) {
                        ((SetCookie) cookie).setCreationInstant(creationInstant);
                    }
                }
                this.cookies.remove(oldCookie);
            } else {
                this.cookies.remove(cookie);
            }
            if (!cookie.isExpired(Instant.now())) {
                this.cookies.add(cookie);
            }
        } finally {
            this.lock.writeLock().unlock();
        }
    }

    public void addCookies(final Cookie[] cookies) {
        if (cookies == null) {
            return;
        }
        for (final Cookie cookie : cookies) {
            addCookie(cookie);
        }
    }

    @Override
    public List<Cookie> getCookies() {
        this.lock.readLock().lock();
        try {
            return new ArrayList<>(this.cookies);
        } finally {
            this.lock.readLock().unlock();
        }
    }

    @Override
    @SuppressWarnings("deprecation")
    public boolean clearExpired(final Date date) {
        if (date == null) {
            return false;
        }
        this.lock.writeLock().lock();
        try {
            boolean removed = false;
            final Iterator<Cookie> it = this.cookies.iterator();
            while (it.hasNext()) {
                if (it.next().isExpired(date)) {
                    it.remove();
                    removed = true;
                }
            }
            return removed;
        } finally {
            this.lock.writeLock().unlock();
        }
    }

    @Override
    public boolean clearExpired(final Instant instant) {
        if (instant == null) {
            return false;
        }
        this.lock.writeLock().lock();
        try {
            boolean removed = false;
            final Iterator<Cookie> it = this.cookies.iterator();
            while (it.hasNext()) {
                if (it.next().isExpired(instant)) {
                    it.remove();
                    removed = true;
                }
            }
            return removed;
        } finally {
            this.lock.writeLock().unlock();
        }
    }

    @Override
    public void clear() {
        this.lock.writeLock().lock();
        try {
            this.cookies.clear();
        } finally {
            this.lock.writeLock().unlock();
        }
    }

    @Override
    public String toString() {
        this.lock.readLock().lock();
        try {
            return this.cookies.toString();
        } finally {
            this.lock.readLock().unlock();
        }
    }

}

