package org.apache.hc.client5.http.observation.impl;

import java.net.SocketAddress;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Tag;
import io.micrometer.core.instrument.Timer;
import org.apache.hc.client5.http.observation.MetricConfig;
import org.apache.hc.client5.http.observation.ObservingOptions;
import org.apache.hc.core5.concurrent.FutureCallback;
import org.apache.hc.core5.http.HttpHost;
import org.apache.hc.core5.http.nio.ssl.TlsStrategy;
import org.apache.hc.core5.net.NamedEndpoint;
import org.apache.hc.core5.reactor.ssl.TransportSecurityLayer;
import org.apache.hc.core5.util.Args;
import org.apache.hc.core5.util.Timeout;

/**
 * TLS strategy that wraps a delegate and records handshake metrics
 * using Micrometer.
 *
 * @since 5.6
 */
public final class MeteredTlsStrategy implements TlsStrategy {

    private final TlsStrategy delegate;
    private final MeterRegistry registry;
    private final MetricConfig mc;
    private final ObservingOptions opts;

    /**
     * @since 5.6
     */
    public MeteredTlsStrategy(
            final TlsStrategy delegate,
            final MeterRegistry registry,
            final MetricConfig mc,
            final ObservingOptions opts) {
        this.delegate = Args.notNull(delegate, "delegate");
        this.registry = Args.notNull(registry, "registry");
        this.mc = mc != null ? mc : MetricConfig.builder().build();
        this.opts = opts != null ? opts : ObservingOptions.DEFAULT;
    }

    @Deprecated
    public MeteredTlsStrategy(
            final TlsStrategy delegate,
            final MeterRegistry registry,
            final String prefix) {
        this(delegate, registry, MetricConfig.builder().prefix(prefix != null ? prefix : "hc").build(), ObservingOptions.DEFAULT);
    }

    private List<Tag> tags(final String result, final String sniOrNull) {
        final List<Tag> t = new ArrayList<>(2);
        t.add(Tag.of("result", result));
        if (opts.tagLevel == ObservingOptions.TagLevel.EXTENDED && sniOrNull != null) {
            t.add(Tag.of("sni", sniOrNull));
        }
        if (!mc.commonTags.isEmpty()) {
            t.addAll(mc.commonTags);
        }
        return t;
    }

    @Override
    public void upgrade(
            final TransportSecurityLayer sessionLayer,
            final NamedEndpoint endpoint,
            final Object attachment,
            final Timeout handshakeTimeout,
            final FutureCallback<TransportSecurityLayer> callback) {
        final long t0 = System.nanoTime();
        final String sniOrNull = endpoint != null ? endpoint.getHostName() : null;
        delegate.upgrade(sessionLayer, endpoint, attachment, handshakeTimeout, new FutureCallback<TransportSecurityLayer>() {
            @Override
            public void completed(final TransportSecurityLayer result) {
                Timer.builder(mc.prefix + ".tls.handshake")
                        .tags(tags("ok", sniOrNull))
                        .register(registry)
                        .record(System.nanoTime() - t0, TimeUnit.NANOSECONDS);
                Counter.builder(mc.prefix + ".tls.handshakes")
                        .tags(tags("ok", sniOrNull))
                        .register(registry)
                        .increment();
                if (callback != null) {
                    callback.completed(result);
                }
            }

            @Override
            public void failed(final Exception ex) {
                Timer.builder(mc.prefix + ".tls.handshake")
                        .tags(tags("error", sniOrNull))
                        .register(registry)
                        .record(System.nanoTime() - t0, TimeUnit.NANOSECONDS);
                Counter.builder(mc.prefix + ".tls.handshakes")
                        .tags(tags("error", sniOrNull))
                        .register(registry)
                        .increment();
                if (callback != null) {
                    callback.failed(ex);
                }
            }

            @Override
            public void cancelled() {
                Timer.builder(mc.prefix + ".tls.handshake")
                        .tags(tags("cancel", sniOrNull))
                        .register(registry)
                        .record(System.nanoTime() - t0, TimeUnit.NANOSECONDS);
                Counter.builder(mc.prefix + ".tls.handshakes")
                        .tags(tags("cancel", sniOrNull))
                        .register(registry)
                        .increment();
                if (callback != null) {
                    callback.cancelled();
                }
            }
        });
    }

    @Deprecated
    @Override
    public boolean upgrade(
            final TransportSecurityLayer sessionLayer,
            final HttpHost host,
            final SocketAddress localAddress,
            final SocketAddress remoteAddress,
            final Object attachment,
            final Timeout handshakeTimeout) {
        final long t0 = System.nanoTime();
        final String sniOrNull = host != null ? host.getHostName() : null;
        try {
            final boolean result = delegate.upgrade(sessionLayer, host, localAddress, remoteAddress, attachment, handshakeTimeout);
            Timer.builder(mc.prefix + ".tls.handshake")
                    .tags(tags("ok", sniOrNull))
                    .register(registry)
                    .record(System.nanoTime() - t0, TimeUnit.NANOSECONDS);
            Counter.builder(mc.prefix + ".tls.handshakes")
                    .tags(tags("ok", sniOrNull))
                    .register(registry)
                    .increment();
            return result;
        } catch (final RuntimeException ex) {
            Timer.builder(mc.prefix + ".tls.handshake")
                    .tags(tags("error", sniOrNull))
                    .register(registry)
                    .record(System.nanoTime() - t0, TimeUnit.NANOSECONDS);
            Counter.builder(mc.prefix + ".tls.handshakes")
                    .tags(tags("error", sniOrNull))
                    .register(registry)
                    .increment();
            throw ex;
        }
    }
}

