/**
 * Abstract HTTP client that implements the closeable interface.
 *
 * @since 5.0
 */
@Contract(threading = ThreadingBehavior.STATELESS)
public abstract class CloseableHttpAsyncClient implements HttpAsyncClient, ModalCloseable {

    /**
     * Starts the client.
     */
    public abstract void start();

    /**
     * Gets the status of the I/O reactor.
     */
    public abstract IOReactorStatus getStatus();

    /**
     * Awaits the shutdown of the client.
     *
     * @param waitTime the amount of time to wait
     */
    public abstract void awaitShutdown(TimeValue waitTime) throws InterruptedException;

    /**
     * Initiates the shutdown of the client.
     */
    public abstract void initiateShutdown();

    /**
     * Executes a request with the given callback.
     *
     * @param target the target host
     * @param requestProducer the request producer
     * @param responseConsumer the response consumer
     * @param pushHandlerFactory the push handler factory
     * @param context the context
     * @param callback the callback
     * @param <T> the response type
     */
    protected abstract <T> Future<T> doExecute(
            final HttpHost target,
            final AsyncRequestProducer requestProducer,
            final AsyncResponseConsumer<T> responseConsumer,
            final HandlerFactory<AsyncPushConsumer> pushHandlerFactory,
            final HttpContext context,
            final FutureCallback<T> callback);

    /**
     * Executes a request with the given callback.
     *
     * @param target the target host
     * @param requestProducer the request producer
     * @param responseConsumer the response consumer
     * @param pushHandlerFactory the push handler factory
     * @param context the context
     * @param callback the callback
     * @param <T> the response type
     */
    public final <T> Future<T> execute(
            final HttpHost target,
            final AsyncRequestProducer requestProducer,
            final AsyncResponseConsumer<T> responseConsumer,
            final HandlerFactory<AsyncPushConsumer> pushHandlerFactory,
            final HttpContext context,
            final FutureCallback<T> callback) {
        Args.notNull(requestProducer, "Request producer");
        Args.notNull(responseConsumer, "Response consumer");
        return doExecute(target, requestProducer, responseConsumer, pushHandlerFactory, context, callback);
    }

    @Override
    public final <T> Future<T> execute(
            final AsyncRequestProducer requestProducer,
            final AsyncResponseConsumer<T> responseConsumer,
            final HandlerFactory<AsyncPushConsumer> pushHandlerFactory,
            final HttpContext context,
            final FutureCallback<T> callback) {
        Args.notNull(requestProducer, "Request producer");
        Args.notNull(responseConsumer, "Response consumer");
        return doExecute(null, requestProducer, responseConsumer, pushHandlerFactory, context, callback);
    }

    /**
     * Executes a request with the given callback.
     *
     * @param requestProducer the request producer
     * @param responseConsumer the response consumer
     * @param pushHandlerFactory the push handler factory
     * @param context the context
     * @param callback the callback
     * @param <T> the response type
     */
    public final <T> Future<T> execute(
            final AsyncRequestProducer requestProducer,
            final AsyncResponseConsumer<T> responseConsumer,
            final HttpContext context,
            final FutureCallback<T> callback) {
        Args.notNull(requestProducer, "Request producer");
        Args.notNull(responseConsumer, "Response consumer");
        return execute(requestProducer, responseConsumer, pushHandlerFactory -> null, context, callback);
    }

    /**
     * Executes a request with the given callback.
     *
     * @param requestProducer the request producer
     * @param responseConsumer the response consumer
     * @param callback the callback
     * @param <T> the response type
     */
    public final <T> Future<T> execute(
            final AsyncRequestProducer requestProducer,
            final AsyncResponseConsumer<T> responseConsumer,
            final FutureCallback<T> callback) {
        Args.notNull(requestProducer, "Request producer");
        Args.notNull(responseConsumer, "Response consumer");
        return execute(requestProducer, responseConsumer, null, null, callback);
    }

    /**
     * Executes a request with the given callback.
     *
     * @param request the request
     * @param context the context
     * @param callback the callback
     */
    public final Future<SimpleHttpResponse> execute(
            final SimpleHttpRequest request,
            final HttpContext context,
            final FutureCallback<SimpleHttpResponse> callback) {
        Args.notNull(request, "Request");
        final AsyncRequestProducer requestProducer = SimpleRequestProducer.create(request);
        final AsyncResponseConsumer<SimpleHttpResponse> responseConsumer = SimpleResponseConsumer.create();
        return execute(requestProducer, responseConsumer, context, callback);
    }

    /**
     * Executes a request with the given callback.
     *
     * @param request the request
     * @param callback the callback
     */
    public final Future<SimpleHttpResponse> execute(
            final SimpleHttpRequest request,
            final FutureCallback<SimpleHttpResponse> callback) {
        return execute(request, null, callback);
    }

    /**
     * @deprecated Do not use.
     */
    @Deprecated
    public abstract void register(
            String hostname,
            String uriPattern,
            Supplier<AsyncPushConsumer> supplier);

    /**
     * @deprecated Do not use.
     */
    @Deprecated
    public final void register(
            final String uriPattern,
            final Supplier<AsyncPushConsumer> supplier) {
        register(null, uriPattern, supplier);
    }

}

