package org.eclipse.leshan.client.send;

import java.time.Instant;
import java.util.List;
import java.util.Map;

import org.eclipse.leshan.client.servers.LwM2mServer;
import org.eclipse.leshan.core.node.LwM2mNode;
import org.eclipse.leshan.core.node.LwM2mPath;
import org.eclipse.leshan.core.node.TimestampedLwM2mNodes;
import org.eclipse.leshan.core.request.ContentFormat;

/**
 * Data sender which collects data when requested by application and send it later.
 */
public class ManualDataSender implements DataSender {

    public static final String DEFAULT_NAME = "MANUAL_SENDER";

    private TimestampedLwM2mNodes.Builder builder = new TimestampedLwM2mNodes.Builder();

    private DataSenderManager dataSenderManager;

    private final String name;

    public ManualDataSender() {
        this.name = DEFAULT_NAME;
    }

    public ManualDataSender(String name) {
        this.name = name;
    }

    /**
     * Collect data from system server.
     *
     * @param paths paths to collect
     */
    public synchronized void collectData(List<LwM2mPath> paths) {
        Instant currentTimestamp = Instant.now();
        Map<LwM2mPath, LwM2mNode> currentValues = dataSenderManager.getCurrentValues(LwM2mServer.SYSTEM, paths);

        synchronized (this) {
            builder.addNodes(currentTimestamp, currentValues);
        }
    }

    /**
     * Send collected data.
     *
     * @param server server to send data to
     * @param format content format
     * @param timeoutInMs timeout
     * @param noFlush if true, data will be kept in cache
     * @throws NoDataException if no data collected
     */
    public void sendCollectedData(LwM2mServer server, ContentFormat format, long timeoutInMs, boolean noFlush)
            throws NoDataException {
        TimestampedLwM2mNodes data;
        synchronized (this) {
            data = builder.build();
            if (data.isEmpty()) {
                throw new NoDataException("Unable to send data to %s : no data collected");
            }
            if (!noFlush) {
                builder = new TimestampedLwM2mNodes.Builder();
            }
        }

        dataSenderManager.sendData(server, format, data, response -> {
            if (response.isFailure()) {
                restoreData(data);
            }
        }, error -> {
            restoreData(data);
        }, timeoutInMs);
    }

    @Override
    public void setDataSenderManager(DataSenderManager dataSenderManager) {
        this.dataSenderManager = dataSenderManager;
    }

    @Override
    public String getName() {
        return name;
    }

    private synchronized void restoreData(TimestampedLwM2mNodes data) {
        builder.add(data);
    }
}

