package org.mapfish.print;

import java.util.Collection;
import java.util.Set;

/**
 * Thrown when one or more properties are not used. The properties may be in the config.yaml file or in
 * the request JSON.
 */
public final class ExtraPropertyException extends RuntimeException {
  private final Collection<String> extraProperties;
  private final Set<String> attributeNames;

  /**
   * Constructor.
   *
   * @param message the error message
   * @param extraProperties the extra properties
   * @param attributeNames the attribute names
   */
  public ExtraPropertyException(
      final String message,
      final Collection<String> extraProperties,
      final Set<String> attributeNames) {
    super(createMessage(message, extraProperties, attributeNames));
    this.extraProperties = extraProperties;
    this.attributeNames = attributeNames;
  }

  private static String createMessage(
      final String message,
      final Collection<String> extraProperties,
      final Set<String> attributeNames) {
    final StringBuilder sb = new StringBuilder(message);
    sb.append("\nExtra Properties: \n");
    for (String extraProperty : extraProperties) {
      sb.append("\n\t* ").append(extraProperty);
    }
    sb.append("\nAll allowed properties are: \n");
    for (String attributeName : attributeNames) {
      sb.append("\n\t* ").append(attributeName);
    }
    return sb.toString();
  }

  /**
   * Get the extra properties.
   *
   * @return the extra properties
   */
  public Collection<String> getExtraProperties() {
    return extraProperties;
  }

  /**
   * Get the attribute names.
   *
   * @return the attribute names
   */
  public Set<String> getAttributeNames() {
    return attributeNames;
  }
}

package org.mapfish.print;

import java.util.Map;
import java.util.Set;

/**
 * Thrown when a property is missing in the config.yaml or the request JSON.
 *
 * @param message the message
 * @param missingProperties the missing properties
 * @param attributeNames the attribute names
 */
public final class MissingPropertyException extends RuntimeException {
  private final Map<String, Class<?>> missingProperties;
  private final Set<String> attributeNames;

  /**
   * Constructor.
   *
   * @param message the message
   * @param missingProperties the missing properties
   * @param attributeNames the attribute names
   */
  public MissingPropertyException(
      final String message,
      final Map<String, Class<?>> missingProperties,
      final Set<String> attributeNames) {
    super(createMessage(message, missingProperties, attributeNames));
    this.missingProperties = missingProperties;
    this.attributeNames = attributeNames;
  }

  private static String createMessage(
      final String message,
      final Map<String, Class<?>> missingProperties,
      final Set<String> attributeNames) {
    final StringBuilder sb = new StringBuilder(message);
    sb.append("\n\n");
    sb.append("Missing Properties: \n");
    for (Map.Entry<String, Class<?>> entry : missingProperties.entrySet()) {
      sb.append("\n");
      sb.append("\t* ");
      sb.append(entry.getValue().getName());
      sb.append(" ");
      sb.append(entry.getKey());
    }
    sb.append("\n\n");
    sb.append("All allowed properties are: \n");
    for (String attributeName : attributeNames) {
      sb.append("\n");
      sb.append("\t* ");
      sb.append(attributeName);
    }
    return sb.toString();
  }

  /**
   * Get the missing properties.
   *
   * @return the missing properties
   */
  public Map<String, Class<?>> getMissingProperties() {
    return missingProperties;
  }

  /**
   * Get the attribute names.
   *
   * @return the attribute names
   */
  public Set<String> getAttributeNames() {
    return attributeNames;
  }
}

