package org.eclipse.leshan.core.tlv;

import java.util.Arrays;
import java.util.Objects;

/**
 * A Type-Length-Value container.
 */
public class Tlv {

    private final TlvType type;
    private final Tlv[] children;
    private final byte[] value;
    private final int identifier;

    public Tlv(TlvType type, Tlv[] children, byte[] value, int identifier) {
        this.type = type;
        this.children = children;
        this.value = value;
        this.identifier = identifier;

        if (type == TlvType.RESOURCE_VALUE || type == TlvType.RESOURCE_INSTANCE) {
            if (value == null) {
                throw new IllegalArgumentException("a " + type.name() + " must have a value");
            }
            if (children != null) {
                throw new IllegalArgumentException("a " + type.name() + " can't have children");
            }
        } else {
            if (value != null) {
                throw new IllegalArgumentException("a " + type.name() + " can't have a value");
            }
            if (children == null) {
                throw new IllegalArgumentException("a " + type.name() + " must have children");
            }
        }
    }

    public TlvType getType() {
        return type;
    }

    public Tlv[] getChildren() {
        return children;
    }

    public byte[] getValue() {
        return value;
    }

    public int getIdentifier() {
        return identifier;
    }

    @Override
    public final boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof Tlv)) {
            return false;
        }
        Tlv tlv = (Tlv) o;
        return identifier == tlv.identifier && type == tlv.type && Objects.deepEquals(children, tlv.children)
                && Arrays.equals(value, tlv.value);
    }

    @Override
    public final int hashCode() {
        return Objects.hash(type, Arrays.hashCode(children), Arrays.hashCode(value), identifier);
    }

    public enum TlvType {
        OBJECT_INSTANCE, RESOURCE_INSTANCE, MULTIPLE_RESOURCE, RESOURCE_VALUE
    }

    @Override
    public String toString() {
        return String.format("Tlv [type=%s, children=%s, value=%s, identifier=%s]", type.name(),
                Arrays.toString(children), Arrays.toString(value), Integer.toString(identifier));
    }
}

package org.mapfish.print.config;

import java.util.List;
import java.util.Optional;
import org.mapfish.print.OptionalUtils;

/** Configuration for PDF output. */
public class PDFConfig implements ConfigurationObject {
  private static final String MAPFISH_PRINT = "Mapfish Print";

  private Optional<Boolean> compressed = Optional.empty();
  private Optional<String> title = Optional.empty();
  private Optional<String> author = Optional.empty();
  private Optional<String> subject = Optional.empty();
  private Optional<String> keywords = Optional.empty();
  private Optional<String> creator = Optional.empty();

  PDFConfig getMergedInstance(final PDFConfig other) {
    PDFConfig merged = new PDFConfig();
    merged.compressed = OptionalUtils.or(this.compressed, other.compressed);
    merged.title = OptionalUtils.or(this.title, other.title);
    merged.author = OptionalUtils.or(this.author, other.author);
    merged.subject = OptionalUtils.or(this.subject, other.subject);
    merged.keywords = OptionalUtils.or(this.keywords, other.keywords);
    merged.creator = OptionalUtils.or(this.creator, other.creator);
    return merged;
  }

  @Override
  public void validate(final List<Throwable> validationErrors, final Configuration configuration) {
    // no checks required
  }

  public boolean isCompressed() {
    return this.compressed.orElse(false);
  }

  public void setCompressed(final boolean compressed) {
    this.compressed = Optional.of(compressed);
  }

  public String getTitle() {
    return this.title.orElse(MAPFISH_PRINT);
  }

  public void setTitle(final String title) {
    this.title = Optional.of(title);
  }

  public String getAuthor() {
    return this.author.orElse(MAPFISH_PRINT);
  }

  public void setAuthor(final String author) {
    this.author = Optional.of(author);
  }

  public String getSubject() {
    return this.subject.orElse(MAPFISH_PRINT);
  }

  public void setSubject(final String subject) {
    this.subject = Optional.of(subject);
  }

  public String getKeywordsAsString() {
    return this.keywords.orElse(MAPFISH_PRINT);
  }

  public void setKeywords(final List<String> keywords) {
    StringBuilder builder = new StringBuilder();
    for (String keyword : keywords) {
      if (!builder.isEmpty()) {
        builder.append(',');
      }
      builder.append(keyword.trim());
    }
    this.keywords = Optional.of(builder.toString());
  }

  public String getCreator() {
    return this.creator.orElse(MAPFISH_PRINT);
  }

  public void setCreator(final String creator) {
    this.creator = Optional.of(creator);
  }
}

package org.mapfish.print.servlet.fileloader;

import jakarta.servlet.ServletContext;
import java.io.File;
import java.net.URI;
import java.util.Collections;
import java.util.Iterator;
import org.springframework.beans.factory.annotation.Autowired;

/**
 * Load configuration files from the servlet context.
 *
 * <p>The URI scheme is <code>servlet://</code>.
 */
public final class ServletConfigFileLoader extends AbstractFileConfigFileLoader {
  /** The URI scheme. */
  public static final String PREFIX = "servlet";
  /** The length of the URI scheme. */
  public static final int PREFIX_LENGTH = (PREFIX + "://").length();

  @Autowired private ServletContext servletContext;

  @Override
  protected Iterator<File> resolveFiles(final URI fileURI) {
    if (fileURI.getScheme() != null && fileURI.getScheme().equals("file") && new File(fileURI).exists()) {
      return Collections.singletonList(new File(fileURI)).iterator();
    }
    if (fileURI.toString().startsWith(PREFIX)) {
      final String path = fileURI.toString().substring(PREFIX_LENGTH);
      final String realPath = this.servletContext.getRealPath(path);
      if (realPath == null) {
        return Collections.emptyIterator();
      }
      return Collections.singletonList(new File(realPath)).iterator();
    }
    return Collections.emptyIterator();
  }

  @Override
  public String getUriScheme() {
    return PREFIX;
  }

  public void setServletContext(final ServletContext servletContext) {
    this.servletContext = servletContext;
  }
}

package org.mapfish.print.map.geotools.grid;

import jakarta.annotation.Nonnull;
import java.util.concurrent.ForkJoinPool;
import org.geotools.api.data.FeatureSource;
import org.mapfish.print.OptionalUtils;
import org.mapfish.print.config.Template;
import org.mapfish.print.map.geotools.AbstractFeatureSourceLayerPlugin;
import org.mapfish.print.map.geotools.FeatureSourceSupplier;
import org.mapfish.print.map.geotools.StyleSupplier;
import org.springframework.beans.factory.annotation.Autowired;

/**
 * Renders a grid layer.
 *
 * <p>Type: <code>grid</code>
 */
public final class GridLayerPlugin extends AbstractFeatureSourceLayerPlugin<GridParam> {
  private static final String TYPE = "grid";

  @Autowired private ForkJoinPool pool;

  /** Constructor. */
  public GridLayerPlugin() {
    super(TYPE);
  }

  @Override
  public GridParam createParameter() {
    return new GridParam();
  }

  @Nonnull
  @Override
  public GridLayer parse(
      @Nonnull final Template template, @Nonnull final GridParam layerData) {
    LabelPositionCollector labels = new LabelPositionCollector();
    FeatureSourceSupplier featureSource =
        createFeatureSourceFunction(template, layerData, labels);
    StyleSupplier<FeatureSource<?, ?>> styleFunction = createStyleSupplier(template, layerData);
    boolean renderAsSvg = template.getConfiguration().renderAsSvg(layerData.renderAsSvg);
    return new GridLayer(
        this.pool, featureSource, styleFunction, renderAsSvg, layerData, labels);
  }

  private StyleSupplier<FeatureSource<?, ?>> createStyleSupplier(
      final Template template, final GridParam layerData) {
    return (requestFactory, featureSource) -> {
      String styleRef = layerData.style;
      return OptionalUtils.or(
              () -> template.getStyle(styleRef),
              () -> GridLayerPlugin.super.parser.loadStyle(template.getConfiguration(), requestFactory, styleRef))
          .orElseGet(() -> layerData.gridType.strategy.defaultStyle(template, layerData));
    };
  }

  private FeatureSourceSupplier createFeatureSourceFunction(
      final Template template, final GridParam layerData, final LabelPositionCollector labels) {
    return layerData.gridType.strategy.createFeatureSource(template, layerData, labels);
  }
}

