package org.eclipse.leshan.core.request;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Objects;
import java.util.Set;

import org.eclipse.leshan.core.LwM2m.LwM2mVersion;

public class ContentFormat implements Comparable<ContentFormat> {

    public static final int TLV_CODE = 11542;
    public static final int JSON_CODE = 11543;
    public static final int TEXT_CODE = 0;
    public static final int OPAQUE_CODE = 42;
    public static final int LINK_CODE = 40;
    public static final int CBOR_CODE = 60;

    // Old JSON and TLV code for backward compatibility
    public static final int OLD_JSON_CODE = 1543;
    public static final int OLD_TLV_CODE = 1542;

    // SenML
    public static final int SENML_JSON_CODE = 110;
    public static final int SENML_CBOR_CODE = 112;

    public static final ContentFormat TLV = new ContentFormat("TLV", "application/vnd.oma.lwm2m+tlv", TLV_CODE,
            Arrays.asList(LwM2mVersion.V1_0));
    public static final ContentFormat JSON = new ContentFormat("JSON", "application/vnd.oma.lwm2m+json", JSON_CODE);
    public static final ContentFormat TEXT = new ContentFormat("TEXT", "text/plain", TEXT_CODE,
            Arrays.asList(LwM2mVersion.V1_1));
    public static final ContentFormat OPAQUE = new ContentFormat("OPAQUE", "application/octet-stream", OPAQUE_CODE,
            Arrays.asList(LwM2mVersion.V1_1));
    public static final ContentFormat LINK = new ContentFormat("LINK", "application/link-format", LINK_CODE,
            Arrays.asList(LwM2mVersion.V1_1));
    public static final ContentFormat SENML_JSON = new ContentFormat("SENML_JSON", "application/senml+json", SENML_JSON_CODE);
    public static final ContentFormat SENML_CBOR = new ContentFormat("SENML_CBOR", "application/senml+cbor", SENML_CBOR_CODE);
    public static final ContentFormat CBOR = new ContentFormat("CBOR", "application/cbor", CBOR_CODE);

    public static final ContentFormat DEFAULT = TLV;

    public static final ContentFormat[] knownContentFormat = new ContentFormat[] { TLV, JSON, SENML_JSON, SENML_CBOR, TEXT,
            OPAQUE, CBOR, LINK };

    private final String name;
    private final String mediaType;
    private final int code;
    private Set<LwM2mVersion> mandatoryForClient;

    public ContentFormat(String name, String mediaType, int code, Collection<LwM2mVersion> mandatory) {
        this.name = name;
        this.mediaType = mediaType;
        this.code = code;
        this.mandatoryForClient = new HashSet<>(mandatory);
    }

    public ContentFormat(String name, String mediaType, int code) {
        this.name = name;
        this.mediaType = mediaType;
        this.code = code;
        this.mandatoryForClient = Collections.emptySet();
    }

    public ContentFormat(int code) {
        this.name = "UNKNOWN";
        this.mediaType = "unknown/unknown";
        this.code = code;
        this.mandatoryForClient = Collections.emptySet();
    }

    public String getName() {
        return name;
    }

    public String getMediaType() {
        return mediaType;
    }

    public int getCode() {
        return code;
    }

    public boolean isMandatoryForClient(LwM2mVersion lwM2mVersion) {
        return mandatoryForClient.contains(lwM2mVersion);
    }

    public static ContentFormat fromMediaType(String mediaType) {
        for (ContentFormat ct : knownContentFormat) {
            if (ct.getMediaType().equals(mediaType)) {
                return ct;
            }
        }
        return null;
    }

    public static ContentFormat fromCode(String code) throws NumberFormatException {
        return fromCode(Integer.parseInt(code));
    }

    public static ContentFormat fromCode(int code) {
        for (ContentFormat ct : knownContentFormat) {
            if (ct.getCode() == code) {
                return ct;
            }
        }
        return new ContentFormat(code);
    }

    public static ContentFormat fromName(String name) {
        for (ContentFormat ct : knownContentFormat) {
            if (ct.getName().equals(name)) {
                return ct;
            }
        }
        return null;
    }

    @Override
    public String toString() {
        return String.format("%s(%s)", name, code);
    }

    @Override
    public int compareTo(ContentFormat ct) {
        return Integer.compare(this.code, ct.code);
    }

    public static List<ContentFormat> getOptionalContentFormatForClient(Collection<ContentFormat> contentFormat,
            LwM2mVersion lwm2mVersion) {
        List<ContentFormat> optional = new ArrayList<>();
        for (ContentFormat ct : contentFormat) {
            if (!ct.isMandatoryForClient(lwm2mVersion)) {
                optional.add(ct);
            }
        }
        return optional;
    }

    @Override
    public final boolean equals(Object o) {
        if (this == o) {
            return true;
        }
        if (!(o instanceof ContentFormat)) {
            return false;
        }
        return ((ContentFormat) o).code == code;
    }

    @Override
    public final int hashCode() {
        return Objects.hashCode(code);
    }
}

package org.mapfish.print.processor.jasper;

import com.google.common.annotations.VisibleForTesting;
import java.awt.Dimension;
import java.io.File;
import java.net.URI;
import java.util.List;
import net.sf.jasperreports.engine.JRException;
import net.sf.jasperreports.engine.JasperCompileManager;
import net.sf.jasperreports.engine.design.JRDesignBand;
import net.sf.jasperreports.engine.design.JRDesignElement;
import net.sf.jasperreports.engine.design.JRDesignExpression;
import net.sf.jasperreports.engine.design.JRDesignImage;
import net.sf.jasperreports.engine.design.JasperDesign;
import net.sf.jasperreports.engine.type.HorizontalImageAlignEnum;
import net.sf.jasperreports.engine.type.ScaleImageEnum;
import net.sf.jasperreports.engine.type.WhenNoDataTypeEnum;
import net.sf.jasperreports.renderers.Renderable;

/** Creates a Jasper report that contains a set of images. */
public class ImagesSubReport {
  private final JasperDesign reportDesign;

  /**
   * Creates a Jasper report that contains a set of images.
   *
   * @param graphics the list of graphics
   * @param size the size
   * @param dpi the dpi
   */
  public ImagesSubReport(final List<URI> graphics, final Dimension size, final double dpi) {
    this.reportDesign = createReport(graphics, size, dpi);
  }

  private JasperDesign createReport(
      final List<URI> graphics, final Dimension size, final double dpi) {
    JasperDesign design = new JasperDesign();
    design.setName("map");
    design.setPageWidth(size.width);
    design.setPageHeight(size.height);
    design.setColumnWidth(size.width);
    design.setColumnSpacing(0);
    design.setLeftMargin(0);
    design.setRightMargin(0);
    design.setTopMargin(0);
    design.setBottomMargin(0);

    JRDesignBand band = new JRDesignBand();
    band.setHeight(size.height);
    addGraphics(graphics, band, size, design);
    design.setNoData(band);
    design.setWhenNoDataType(WhenNoDataTypeEnum.NO_DATA_SECTION);
    design.setProperty(Renderable.PROPERTY_IMAGE_DPI, String.valueOf(Math.round(dpi)));
    return design;
  }

  private void addGraphics(
      final List<URI> graphics,
      final JRDesignBand band,
      final Dimension size,
      final JasperDesign design) {
    for (URI graphicFile : graphics) {
      String imageExpression =
          "\"" + new File(graphicFile).getAbsolutePath().replace('\\', '/') + "\"";
      JRDesignElement image = getImage(imageExpression, size, design);
      band.addElement(image);
    }
  }

  private JRDesignElement getImage(
      final String imageExpression, final Dimension mapSize, final JasperDesign design) {
    JRDesignImage image = new JRDesignImage(design);
    image.setHorizontalImageAlign(HorizontalImageAlignEnum.CENTER);
    image.setX(0);
    image.setY(0);
    image.setWidth(mapSize.width);
    image.setHeight(mapSize.height);
    image.setScaleImage(ScaleImageEnum.RETAIN_SHAPE);
    JRDesignExpression expression = new JRDesignExpression();
    expression.setText(imageExpression);
    image.setExpression(expression);
    return image;
  }

  /**
   * Compile the report.
   *
   * @param compiledReportFile the compiled report file
   */
  public final void compile(final File compiledReportFile) throws JRException {
    JasperCompileManager.compileReportToFile(this.reportDesign, compiledReportFile.getAbsolutePath());
  }

  @VisibleForTesting
  protected final JasperDesign getReportDesign() {
    return this.reportDesign;
  }
}

