package org.mapfish.print.metrics;

import com.codahale.metrics.Counter;
import com.codahale.metrics.MetricRegistry;
import com.codahale.metrics.health.HealthCheck;
import java.util.HashSet;
import java.util.Set;
import org.springframework.beans.factory.annotation.Autowired;

/**
 * Checks if any of the counters are unhealthy.
 *
 * <p>If any of the counters are unhealthy, the check will return unhealthy with the counters that
 * are unhealthy.
 */
public class UnhealthyCountersHealthCheck extends HealthCheck {
  @Autowired private MetricRegistry metricRegistry;
  private final Set<String> unhealthyCounters = new HashSet<>();

  @Override
  protected HealthCheck.Result check() {
    StringBuilder messageBuilder = new StringBuilder();
    boolean first = true;
    for (String unhealthyCounter : this.unhealthyCounters) {
      if (!this.metricRegistry.getNames().contains(unhealthyCounter)) {
        continue;
      }
      Counter counter = this.metricRegistry.counter(unhealthyCounter);
      if (counter.getCount() == 0) {
        continue;
      }
      if (!first) {
        messageBuilder.append("\n");
      }
      first = false;
      messageBuilder.append(unhealthyCounter).append(" = ").append(counter.getCount());
    }
    if (first) {
      return Result.healthy("No unhealthy counter found.");
    }
    return Result.unhealthy(messageBuilder.toString());
  }

  /**
   * Record a counter that might be unhealthy.
   *
   * @param counterName the counter name
   */
  public void recordUnhealthyCounter(final String counterName) {
    this.unhealthyCounters.add(counterName);
  }

  /**
   * Record a problem that might be unhealthy.
   *
   * @param className the class name
   * @param description the description
   */
  public void recordUnhealthyProblem(final String className, final String description) {
    String counterName = MetricRegistry.name(className, description);
    Counter counter = this.metricRegistry.counter(counterName);
    counter.inc();
    this.recordUnhealthyCounter(counterName);
  }
}

package org.mapfish.print.config;

import com.google.common.annotations.VisibleForTesting;
import jakarta.annotation.PostConstruct;
import java.io.File;
import java.io.FileInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.ConfigurableApplicationContext;
import org.yaml.snakeyaml.DumperOptions;
import org.yaml.snakeyaml.LoaderOptions;
import org.yaml.snakeyaml.Yaml;
import org.yaml.snakeyaml.representer.Representer;

/** Configuration factory. */
public class ConfigurationFactory {
  private static final Logger LOGGER = LoggerFactory.getLogger(ConfigurationFactory.class);

  @Autowired private ConfigurableApplicationContext context;

  private ThreadLocal<Yaml> yamlThreadLocal;

  private boolean doValidation = true;

  /** Add the yaml parser to the context. */
  @PostConstruct
  public final void init() {
    LoaderOptions loaderOptions = new LoaderOptions();
    String maxAliases = System.getenv("PRINT_YAML_MAX_ALIASES");
    if (maxAliases != null) {
      loaderOptions.setMaxAliasesForCollections(Integer.parseInt(maxAliases));
    }

    DumperOptions dumperOptions = new DumperOptions();
    Representer representer = new Representer(dumperOptions);

    this.yamlThreadLocal =
        ThreadLocal.withInitial(() -> new Yaml(new MapfishPrintConstructor(this.context), representer, dumperOptions, loaderOptions));
  }

  /**
   * Load the configuration from the given file.
   *
   * @param configFile the configuration file
   */
  @VisibleForTesting
  public final Configuration getConfig(final File configFile) throws IOException {
    try (InputStream in = new FileInputStream(configFile)) {
      return getConfig(configFile, in);
    }
  }

  /**
   * Load the configuration from the given file.
   *
   * @param configFile the configuration file
   */
  public final Configuration getConfig(final File configFile, final InputStream configData)
      throws IOException {
    Configuration configuration = this.context.getBean(Configuration.class);
    configuration.setConfigurationFile(configFile);
    MapfishPrintConstructor.setConfigurationUnderConstruction(configuration);

    try (InputStreamReader reader = new InputStreamReader(configData, StandardCharsets.UTF_8)) {
      Configuration config = this.yamlThreadLocal.get().load(reader);

      if (this.doValidation) {
        List<Throwable> validate = config.validate();
        if (!validate.isEmpty()) {
          StringBuilder sb = new StringBuilder();
          for (Throwable throwable : validate) {
            sb.append("\n");
            sb.append("\t* ");
            sb.append(throwable.getMessage());
            LOGGER.error("Configuration Error found", throwable);
          }
          throw new Error(sb.toString(), validate.getFirst());
        }
      }

      return config;
    } finally {
      this.yamlThreadLocal.remove();
    }
  }

  /**
   * Set the doValidation flag.
   *
   * @param doValidation the doValidation flag
   */
  public final void setDoValidation(final boolean doValidation) {
    this.doValidation = doValidation;
  }
}

package org.mapfish.print.processor.map.scalebar;

import java.awt.BasicStroke;
import java.awt.Graphics2D;
import java.awt.geom.AffineTransform;
import org.mapfish.print.attribute.ScalebarAttribute.ScalebarAttributeValues;

/**
 * Abstract class for drawing scalebar.
 *
 * @param graphics2d the graphics context
 * @param settings the scalebar render settings
 */
public abstract class ScalebarDrawer {
  private final Graphics2D graphics2d;
  private final AffineTransform transform;
  private final ScaleBarRenderSettings settings;
  private final ScalebarAttributeValues params;

  /**
   * Constructor.
   *
   * @param graphics2d the graphics context
   * @param settings the scalebar render settings
   */
  protected ScalebarDrawer(
      final Graphics2D graphics2d, final ScaleBarRenderSettings settings) {
    this.graphics2d = graphics2d;
    this.transform = new AffineTransform(graphics2d.getTransform());
    this.settings = settings;
    this.params = settings.getParams();
  }

  /**
   * Draw the scalebar.
   *
   * <p>The scalebar is drawn in the following order:
   *
   * <ol>
   *   <li>Background
   *   <li>Labels
   *   <li>Scalebar
   * </ol>
   */
  public final void draw() {
    final AffineTransform transform = new AffineTransform(this.transform);
    transform.concatenate(getAlignmentTransform());
    this.graphics2d.setTransform(transform);

    if (this.params.getBackgroundColor().getAlpha() > 0) {
      this.graphics2d.setColor(this.params.getBackgroundColor());
      this.graphics2d.fillRect(0, 0, this.settings.getSize().width, this.settings.getSize().height);
    }

    this.graphics2d.setColor(this.params.getFontColor());
    drawLabels(transform, this.params.getOrientation(), this.params.getLabelRotation());

    final AffineTransform lineTransform = new AffineTransform(transform);
    setLineTranslate(lineTransform);
    if (this.params.getOrientation() == Orientation.VERTICAL_LABELS_LEFT
        || this.params.getOrientation() == Orientation.VERTICAL_LABELS_RIGHT) {
      lineTransform.concatenate(AffineTransform.getQuadrantRotateInstance(1));
    }
    this.graphics2d.setTransform(lineTransform);
    this.graphics2d.setStroke(new BasicStroke(this.settings.getLineWidth()));
    this.graphics2d.setColor(this.params.getColor());
    drawBar();
  }

  private AffineTransform getAlignmentTransform() {
    final int offsetX;
    final int offsetY;
    switch (this.params.getAlign()) {
      case LEFT:
        offsetX = 0;
        break;
      case RIGHT:
        offsetX = this.settings.getMaxSize().width - this.settings.getSize().width;
        break;
      case CENTER:
        offsetX = Math.round(this.settings.getMaxSize().width / 2.0f - this.settings.getSize().width / 2.0f);
        break;
      default:
        offsetX = 0;
    }
    switch (this.params.getVerticalAlign()) {
      case TOP:
        offsetY = 0;
        break;
      case BOTTOM:
        offsetY = this.settings.getMaxSize().height - this.settings.getSize().height;
        break;
      case CENTER:
        offsetY = Math.round(this.settings.getMaxSize().height / 2.0f - this.settings.getSize().height / 2.0f);
        break;
      default:
        offsetY = 0;
    }
    return AffineTransform.getTranslateInstance(offsetX, offsetY);
  }

  private void setLineTranslate(final AffineTransform lineTransform) {
    final int x;
    final int y;
    if (this.params.getOrientation() == Orientation.HORIZONTAL_LABELS_BELOW) {
      x = this.settings.getPadding() + this.settings.getLeftLabelMargin();
      y = this.settings.getPadding() + this.settings.getBarSize();
    } else if (this.params.getOrientation() == Orientation.HORIZONTAL_LABELS_ABOVE) {
      x = this.settings.getPadding() + this.settings.getLeftLabelMargin();
      y =
          this.settings.getPadding()
              + this.settings.getBarSize()
              + this.settings.getLabelDistance()
              + Label.getRotatedHeight(this.settings.getMaxLabelSize(), this.params.getLabelRotation());
    } else if (this.params.getOrientation() == Orientation.VERTICAL_LABELS_LEFT) {
      x =
          this.settings.getPadding()
              + this.settings.getMaxLabelSize().width
              + this.settings.getLabelDistance();
      y = this.settings.getPadding() + this.settings.getTopLabelMargin();
    } else {
      x = this.settings.getPadding();
      y = this.settings.getPadding() + this.settings.getTopLabelMargin();
    }
    lineTransform.translate(Math.round(x), Math.round(y));
  }

  private void setLabelTranslate(final AffineTransform labelTransform) {
    final int x;
    final int y;
    if (this.params.getOrientation() == Orientation.HORIZONTAL_LABELS_BELOW) {
      x = this.settings.getPadding() + this.settings.getLeftLabelMargin();
      y =
          this.settings.getPadding()
              + this.settings.getBarSize()
              + this.settings.getLabelDistance();
    } else if (this.params.getOrientation() == Orientation.HORIZONTAL_LABELS_ABOVE) {
      x = this.settings.getPadding() + this.settings.getLeftLabelMargin();
      y =
          this.settings.getPadding()
              + this.settings.getBarSize()
              + this.settings.getLabelDistance()
              + Label.getRotatedHeight(this.settings.getMaxLabelSize(), this.params.getLabelRotation());
    } else if (this.params.getOrientation() == Orientation.VERTICAL_LABELS_LEFT) {
      x =
          this.settings.getPadding()
              + this.settings.getMaxLabelSize().width
              + this.settings.getLabelDistance();
      y = this.settings.getPadding() + this.settings.getTopLabelMargin();
    } else {
      x = this.settings.getPadding() + this.settings.getLeftLabelMargin();
      y = this.settings.getPadding() + this.settings.getTopLabelMargin();
    }
    labelTransform.translate(Math.round(x), Math.round(y));
  }

  /**
   * Draw the scalebar.
   *
   * <p>The scalebar is drawn in the following order:
   *
   * <ol>
   *   <li>Background
   *   <li>Labels
   *   <li>Scalebar
   * </ol>
   */
  protected abstract void drawBar();

  private void drawLabels(
      final AffineTransform transform, final Orientation orientation, final float labelRotation) {
    int prevMargin = orientation.isHorizontal() ? this.settings.getMaxSize().width : this.settings.getMaxSize().height;
    final AffineTransform firstTickTransform = new AffineTransform(transform);
    setLabelTranslate(firstTickTransform);

    for (Label label : this.settings.getLabels()) {
      final AffineTransform centerTransform = new AffineTransform(firstTickTransform);
      centerTransform.translate(
          Math.round(label.getGraphicOffset()),
          Math.round(label.getGraphicOffset()));

      final float halfRotatedWidth = label.getRotatedWidth(labelRotation) / 2.0f;
      final float halfRotatedHeight = label.getRotatedHeight(labelRotation) / 2.0f;

      if (orientation.isHorizontal()) {
        centerTransform.translate(
            Math.round(label.getGraphicOffset()),
            orientation == Orientation.HORIZONTAL_LABELS_BELOW ? halfRotatedHeight : -halfRotatedHeight);
        final boolean overlap =
            label.getGraphicOffset() + halfRotatedWidth > prevMargin - 1;

