   * Get the access.
   *
   * @return the access
   */
  public final AccessAssertion getAccess() {
    return this.access;
  }

  /**
   * Set the access.
   *
   * @param access the access
   */
  public final void setAccess(final AccessAssertion access) {
    this.access = access;
  }

  /**
   * Get the app id.
   *
   * @return the app id
   */
  public final String getAppId() {
    return getRequestData().optString(MapPrinterServlet.JSON_APP, ServletMapPrinterFactory.DEFAULT_CONFIGURATION_FILE_KEY);
  }

  /**
   * Get the time since start.
   *
   * @return the time since start
   */
  public final long getTimeSinceStart() {
    return System.currentTimeMillis() - getStartTime();
  }

  /**
   * Assert access.
   *
   * @throws AccessDeniedException if access is denied
   */
  public final void assertAccess() {
    final String resourceDescription =
        getClass().getSimpleName() + ":" + getAppId() + ":" + getReferenceId();
    getAccess().assertAccess(resourceDescription, this);
  }

  /**
   * Configure access.
   *
   * @param template the template
   * @param context the context
   */
  public final void configureAccess(final Template template, final ApplicationContext context) {
    final Configuration configuration = template.getConfiguration();
    final AndAccessAssertion access = context.getBean(AndAccessAssertion.class);
    access.setPredicates(
        new AccessAssertion[] {configuration.getAccessAssertion(), template.getAccessAssertion()});
    this.access = access;
  }
