package org.mapfish.print.parser;

import jakarta.annotation.Nullable;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.util.Arrays;
import java.util.Collection;
import java.util.HashSet;
import java.util.Set;
import java.util.function.Function;
import java.util.function.Predicate;

/** Utilities for parsing. */
public final class ParserUtils {
  /** Filter that accepts only required attributes. */
  public static final Predicate<Field> FILTER_ONLY_REQUIRED_ATTRIBUTES =
      field -> {
        if (field == null) {
          return false;
        }
        return field.getAnnotation(HasDefaultValue.class) == null && !Modifier.isFinal(field.getModifiers());
      };

  /** Filter that accepts only attributes with default values. */
  public static final Predicate<Field> FILTER_HAS_DEFAULT_ATTRIBUTES =
      field -> field != null && field.getAnnotation(HasDefaultValue.class) != null;

  /** Filter that accepts only non-final attributes. */
  public static final Predicate<Field> FILTER_NON_FINAL_FIELDS =
      field -> field != null && !Modifier.isFinal(field.getModifiers());

  /** Filter that accepts only final attributes. */
  public static final Predicate<Field> FILTER_FINAL_FIELDS =
      @Nullable field -> field != null && Modifier.isFinal(field.getModifiers());

  private static final Function<Field, String> FIELD_TO_NAME = field -> field.getName();

  private ParserUtils() {
    // intentionally empty
  }

  /**
   * Get all the attributes from the class and its superclasses.
   *
   * @param classToInspect the class to inspect
   */
  public static Collection<Field> getAllAttributes(final Class<?> classToInspect) {
    final Set<Field> results = new HashSet<>();
    getAllAttributes(classToInspect, results, Function.identity(), field -> true);
    return results;
  }

  /**
   * Get all the attributes from the class and its superclasses.
   *
   * @param classToInspect the class to inspect
   * @param filter the filter to use
   */
  public static Collection<Field> getAttributes(
      final Class<?> classToInspect, final Predicate<Field> filter) {
    final Set<Field> results = new HashSet<>();
    getAllAttributes(classToInspect, results, Function.identity(), filter);
    return results;
  }

  private static <V> void getAllAttributes(
      final Class<?> classToInspect,
      final Set<V> results,
      final Function<Field, V> map,
      final Predicate<Field> filter) {
    if (classToInspect != null && classToInspect != Void.class) {
      final Field[] fields =
          classToInspect.isRecord()
              ? classToInspect.getDeclaredFields()
              : classToInspect.getFields();
      results.addAll(
          Arrays.stream(fields)
              .filter(filter)
              .map(map)
              .toList());
      if (classToInspect.getSuperclass() != null) {
        getAllAttributes(classToInspect.getSuperclass(), results, map, filter);
      }
    }
  }

  /**
   * Get all the attribute names from the class and its superclasses.
   *
   * @param classToInspect the class to inspect
   */
  public static Set<String> getAllAttributeNames(final Class<?> classToInspect) {
    final Set<String> results = new HashSet<>();
    getAllAttributeNames(classToInspect, results, FIELD_TO_NAME, field -> true);
    return results;
  }

  /**
   * Get all the attribute names from the class and its superclasses.
   *
   * @param classToInspect the class to inspect
   * @param filter the filter to use
   */
  public static Set<String> getAttributeNames(
      final Class<?> classToInspect, final Predicate<Field> filter) {
    final Set<String> results = new HashSet<>();
    getAllAttributeNames(classToInspect, results, FIELD_TO_NAME, filter);
    return results;
  }

  private static <V> void getAllAttributeNames(
      final Class<?> classToInspect,
      final Set<V> results,
      final Function<Field, V> map,
      final Predicate<Field> filter) {
    if (classToInspect != null && classToInspect != Void.class) {
      final Field[] fields =
          classToInspect.isRecord()
              ? classToInspect.getDeclaredFields()
              : classToInspect.getFields();
      results.addAll(
          Arrays.stream(fields)
              .filter(filter)
              .map(map)
              .toList());
      if (classToInspect.getSuperclass() != null) {
        getAllAttributeNames(classToInspect.getSuperclass(), results, map, filter);
      }
    }
  }
}

package org.mapfish.print.attribute.map;

import static org.mapfish.print.Constants.PDF_DPI;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.TreeSet;
import org.mapfish.print.config.Configuration;
import org.mapfish.print.config.ConfigurationException;
import org.mapfish.print.config.ConfigurationObject;
import org.mapfish.print.map.DistanceUnit;
import org.mapfish.print.map.Scale;

/**
 * The zoom levels.
 *
 * <p>Example 1:
 *
 * <pre><code>
 *     zoomLevels:
 *       - 1000
 *       - 500
 *       - 200
 *       - 100
 *       - 50
 *       - 20
 *       - 10
 *       - 5
 *       - 2
 *       - 1
 * </code></pre>
 *
 * <p>Example 2:
 *
 * <pre><code>
 *     zoomLevels:
 *       - 1000
 *       - 500
 *       - 200
 *       - 100
 *       - 50
 *       - 20
 *       - 10
 *       - 5
 *       - 2
 *       - 1
 *       - 0.5
 *       - 0.2
 *       - 0.1
 *       - 0.05
 *       - 0.02
 *       - 0.01
 *       - 0.005
 *       - 0.002
 *       - 0.001
 *       - 0.0005
 *       - 0.0002
 *       - 0.0001
 * </code></pre>
 */
public final class ZoomLevels implements ConfigurationObject {
  private double[] scaleDenominators;

  /**
   * Constructor.
   *
   * @param scaleDenominators the zoom levels
   */
  public ZoomLevels(final double... scaleDenominators) {
    this.setScales(scaleDenominators);
  }

  /**
   * Constructor.
   *
   * <p>This is intentionally empty. It is used so that spring framework can create the object and
   * then set the properties.
   */
  public ZoomLevels() {
    // do nothing
  }

  /**
   * Set the zoom levels.
   *
   * @param newScaleDenominators the zoom levels
   */
  public void setScales(final double[] newScaleDenominators) {
    TreeSet<Double> scales = new TreeSet<>(Collections.reverseOrder());
    for (double scaleDenominator : newScaleDenominators) {
      scales.add(scaleDenominator);
    }
    this.scaleDenominators = new double[scales.size()];
    int i = 0;
    for (Double scaleDenominator : scales) {
      this.scaleDenominators[i] = scaleDenominator;
      i++;
    }
  }

  /**
   * Get the number of zoom levels.
   *
   * @return the number of zoom levels
   */
  public int size() {
    return this.scaleDenominators.length;
  }

  /**
   * Get the zoom level.
   *
   * @param index the zoom level index
   * @param unit the unit
   * @return the zoom level
   */
  public Scale get(final int index, final DistanceUnit unit) {
    return new Scale(this.scaleDenominators[index], unit, PDF_DPI);
  }

  @Override
  public String toString() {
    return Arrays.toString(this.scaleDenominators);
  }

  @Override
  public boolean equals(final Object o) {
    if (this == o) {
      return true;
    }
    if (o == null || getClass() != o.getClass()) {
      return false;
    }

    ZoomLevels that = (ZoomLevels) o;

    return Arrays.equals(scaleDenominators, that.scaleDenominators);
  }

  @Override
  public int hashCode() {
    return Arrays.hashCode(scaleDenominators);
  }

  @Override
  public void validate(final List<Throwable> validationErrors, final Configuration configuration) {
    if (this.scaleDenominators == null || this.scaleDenominators.length == 0) {
      validationErrors.add(new ConfigurationException("No zoom levels defined in " + getClass()));
    }
  }

  public double[] getScaleDenominators() {
    double[] dest = new double[this.scaleDenominators.length];
    System.arraycopy(this.scaleDenominators, 0, dest, 0, this.scaleDenominators.length);
    return dest;
  }
}

package org.mapfish.print.map;

import static org.mapfish.print.Constants.INCH_TO_MM;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.measure.Unit;
import org.geotools.api.referencing.crs.CoordinateReferenceSystem;

/** Enumeration of all the supported distance units. */
public enum DistanceUnit {
  /** The meter unit. */
  M(1.0, new String[] {"m", "meter", "meters"}),
  /** The millimeter unit. */
  MM(0.001, new String[] {"mm", "millimeter", "millimeters"}),
  /** The centimeter unit. */
  CM(0.01, new String[] {"cm", "centimeter", "centimeters"}),
  /** The kilometer unit. */
  KM(1000.0, new String[] {"km", "kilometer", "kilometers"}),
  /** The foot unit. */
  FT(INCH_TO_MM / 1000.0 * 12.0, new String[] {"ft", "foot", "feet"}),
  /** The inch unit. */
  IN(1.0 / 12.0, new String[] {"in", "inch"}),
  /** The yard unit. */
  YD(3.0, new String[] {"yd", "yard", "yards"}),
  /** The mile unit. */
  MI(5280.0, new String[] {"mi", "mile", "miles"}),
  /** The degree unit. */
  DEGREES(40041470.0 / 360.0, new String[] {"°", "dd", "deg", "degree", "degrees"}),
  /** The minute unit. */
  MINUTE(1.0 / 60.0, new String[] {"min", "minute", "minutes"}),
  /** The second unit. */
  SECOND(1.0 / 60.0, new String[] {"sec", "second", "seconds"}),
  /** The pixel unit. */
  PX(1.0 / 72.0 * INCH_TO_MM / 1000.0, new String[] {"px", "pixel"}),
  /** The point unit. */
  PT(1.0 / 72.0, new String[] {"pt", "point"}),
  /** The pica unit. */
  PC(12.0, new String[] {"pc", "pica"});

  private static Map<String, DistanceUnit> translations;

  private final DistanceUnit baseUnit;
  private final double baseFactor;
  private final double metersFactor;
  private final String[] texts;
  private DistanceUnit[] allUnits;

  DistanceUnit(final double factor, final String[] texts) {
    this.baseUnit = this;
    this.baseFactor = 1.0;
    this.metersFactor = factor;
    this.texts = texts;
  }

  DistanceUnit(final DistanceUnit baseUnit, final double factor, final String[] texts) {
    this.baseUnit = baseUnit.baseUnit;
    this.baseFactor = factor * baseUnit.baseFactor;
    this.metersFactor = factor * baseUnit.metersFactor;
    this.texts = texts;
  }

  /**
   * Returns the distance unit from a string.
   *
   * @param val the string to convert
   */
  public static DistanceUnit fromString(final String val) {
    return getTranslations().get(val.toLowerCase());
  }

  /**
   * Returns the best unit to display a value.
   *
   * @param value the value
   * @param unit the unit
   */
  public static DistanceUnit getBestUnit(final double value, final DistanceUnit unit) {
    final DistanceUnit[] units = unit.getAllUnits();
    for (int i = units.length - 1; i >= 0; --i) {
      final DistanceUnit cur = units[i];
      if (Math.abs(unit.convertTo(1.0, cur) * value) >= 1.0) {
        return cur;
      }
    }
    return units[0];
  }

  private static synchronized Map<String, DistanceUnit> getTranslations() {
    if (translations == null) {
      translations = new HashMap<>();
      for (DistanceUnit value : DistanceUnit.values()) {
        for (String text : value.texts) {
          translations.put(text, value);
        }
      }
    }
    return translations;
  }

  /**
   * Returns the distance unit from a projection.
   *
   * @param projection the projection
   */
  public static DistanceUnit fromProjection(final CoordinateReferenceSystem projection) {
    return fromString(projection.getCoordinateSystem().getAxis(0).getUnit().toString());
  }

  /**
   * Returns true if this is a base unit.
   *
   * @return true if this is a base unit
   */
  public boolean isBase() {
    return this.baseUnit == this;
  }

  /**
   * Convert a value from this unit to another.
   *
   * @param value the value
   * @param targetUnit the target unit
   */
  public double convertTo(final double value, final DistanceUnit targetUnit) {
    if (targetUnit == this) {
      return value;
    }
    if (isSameBaseUnit(targetUnit)) {
      return baseFactor / targetUnit.baseFactor * value;
    }
    return metersFactor / targetUnit.metersFactor * value;
  }

  /**
   * Returns true if this unit and the target unit are the same base unit.
   *
   * @param target the target unit
   */
  public boolean isSameBaseUnit(final DistanceUnit target) {
    return baseUnit == target.baseUnit
        || target == baseUnit
        || target.baseUnit == baseUnit;
  }

  @Override
  public final String toString() {
    return texts[0];
  }

  /**
   * Returns all the units in the same base unit.
   *
   * @return all the units in the same base unit
   */
  public final synchronized DistanceUnit[] getAllUnits() {
    if (this.baseUnit != this) {
      return this.baseUnit.getAllUnits();
    }
    if (this.allUnits == null) {
      final List<DistanceUnit> units = new ArrayList<>();
      for (DistanceUnit value : DistanceUnit.values()) {
        if (value.baseUnit == this) {
          units.add(value);
        }
      }
      this.allUnits = units.toArray(new DistanceUnit[units.size()]);
      Arrays.sort(this.allUnits, Comparator.comparingDouble(unit -> unit.baseFactor));
    }
    return this.allUnits;
  }
}

package org.mapfish.print.url.data;

import java.net.Proxy;
import java.net.URL;
import java.net.URLConnection;
import java.net.URLStreamHandler;

/**
 * The handler for the data protocol.
 *
 * <p>This handler is registered with the Java URL framework so that the data protocol is handled
 * correctly.
 */
public class Handler extends URLStreamHandler {
  /**
   * Configure the protocol handler.
   *
   * <p>This method configures the Java URL framework to use the correct handler for the data
   * protocol.
   */
  public static void configureProtocolHandler() {
    String current = System.getProperty("java.protocol.handler.pkgs");
    String newValue = "org.mapfish.print.url";
    if (current == null) {
      newValue = "org.mapfish.print.url";
    } else if (!current.contains("org.mapfish.print.url")) {
      newValue = "org.mapfish.print.url" + "|" + current;
    }
    System.setProperty("java.protocol.handler.pkgs", newValue);
  }

  @Override
  protected URLConnection openConnection(final URL url) {
    return new DataUrlConnection(url);
  }

  @Override
  protected URLConnection openConnection(final URL url, final Proxy proxy) {
    return new DataUrlConnection(url);
  }
}

package org.mapfish.print.config.access;

import org.json.JSONException;
import org.json.JSONObject;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.ApplicationContext;

/** Used to marshal {@link AccessAssertion}s to/from JSON. */
public final class AccessAssertionPersister {
  private static final String JSON_CLASS_NAME = "className";

  @Autowired private ApplicationContext applicationContext;

  /**
   * Unmarshal the given JSON to an {@link AccessAssertion}.
   *
   * @param encodedAssertion the JSON to unmarshal
   */
  public AccessAssertion unmarshal(final JSONObject encodedAssertion) {
    try {
      final String className = encodedAssertion.getString(JSON_CLASS_NAME);
      final Class<?> assertionClass = Thread.currentThread().getContextClassLoader().loadClass(className);
      final AccessAssertion assertion =
          (AccessAssertion) applicationContext.getBean(assertionClass);
      assertion.unmarshal(encodedAssertion);
      return assertion;
    } catch (JSONException | ClassNotFoundException e) {
      throw new RuntimeException(e);
    }
  }

  /**
   * Marshal the given {@link AccessAssertion} to JSON.
   *
   * @param assertion the assertion to marshal
   */
  public JSONObject marshal(final AccessAssertion assertion) {
    final JSONObject jsonObject = assertion.marshal();
    if (jsonObject.has(JSON_CLASS_NAME)) {
      throw new AssertionError(
          "AccessAssertion.marshal() is not allowed to define the '"
              + JSON_CLASS_NAME
              + "' field. It is reserved for marshaling.");
    }
    try {
      jsonObject.put(JSON_CLASS_NAME, assertion.getClass().getName());
    } catch (JSONException e) {
      throw new RuntimeException(e);
    }
    return jsonObject;
  }
}

package org.mapfish.print.processor;

import com.codahale.metrics.MetricRegistry;
import com.codahale.metrics.Timer;
import com.google.common.collect.BiMap;
import com.google.common.collect.HashBiMap;
import jakarta.annotation.Nonnull;
import java.util.HashSet;
import java.util.IdentityHashMap;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.concurrent.RecursiveTask;
import java.util.concurrent.TimeUnit;
import org.locationtech.jts.util.Assert;
import org.mapfish.print.PrintException;
import org.mapfish.print.output.Values;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * A node in the processor graph.
 *
 * @param <IN> the input type
 * @param <OUT> the output type
 */
public final class ProcessorGraphNode<IN, OUT> {
  private static final Logger LOGGER = LoggerFactory.getLogger(ProcessorGraphNode.class);
  private final Processor<IN, OUT> processor;
  private final Set<ProcessorGraphNode<?, ?>> dependencies;
  private final Set<ProcessorGraphNode> requirements;
  private final MetricRegistry metricRegistry;

  /**
   * Constructor.
   *
   * @param processor the processor
   * @param metricRegistry the metric registry
   */
  public ProcessorGraphNode(
      @Nonnull final Processor<IN, OUT> processor, @Nonnull final MetricRegistry metricRegistry) {
    this.processor = processor;
    this.dependencies = new HashSet<>();
    this.requirements = new HashSet<>();
    this.metricRegistry = metricRegistry;
  }

  /**
   * Get the processor.
   *
   * @return the processor
   */
  public Processor<?, ?> getProcessor() {
    return this.processor;
  }

  /**
   * Add a dependency.
   *
   * @param node the node
   */
  public void addDependency(final ProcessorGraphNode node) {
    Assert.isTrue(node != this, "A processor can't depends on himself");
    this.dependencies.add(node);
    node.addRequirement(this);
  }

  private void addRequirement(final ProcessorGraphNode node) {
    this.requirements.add(node);
  }

  Set<ProcessorGraphNode> getRequirements() {
    return this.requirements;
  }

  Set<ProcessorGraphNode<?, ?>> getDependencies() {
    return this.dependencies;
  }

  /**
   * Create a task that can be executed by the Fork/Join framework.
   *
   * @param execContext the execution context
   * @return the task
   */
  public Optional<ProcessorNodeForkJoinTask<IN, OUT>> createTask(
      @Nonnull final ProcessorExecutionContext execContext) {
    if (!execContext.tryStart(this)) {
      return Optional.empty();
    }
    return Optional.of(new ProcessorNodeForkJoinTask(this, execContext));
  }

  /**
   * Get the output mapper.
   *
   * @return the output mapper
   */
  @Nonnull
  public BiMap<String, String> getOutputMapper() {
    return this.processor.getOutputMapperBiMap() != null
        ? this.processor.getOutputMapperBiMap()
        : HashBiMap.create();
  }

  /**
   * Get the input mapper.
   *
   * @return the input mapper
   */
  @Nonnull
  public BiMap<String, String> getInputMapper() {
    return this.processor.getInputMapperBiMap() != null
        ? this.processor.getInputMapperBiMap()
        : HashBiMap.create();
  }

  /**
   * Append the node and its subgraph to the given string builder.
   *
   * @param builder the string builder
   * @param indent the indent
   * @param parent the parent
   */
  public void toString(final StringBuilder builder, final int indent, final String parent) {
    this.processor.toString(builder, indent, parent);
    for (ProcessorGraphNode<?, ?> node : this.dependencies) {
      node.toString(builder, indent + 1, this.processor.toString());
    }
  }

  @Override
  public String toString() {
    final StringBuilder builder = new StringBuilder();
    this.toString(builder, 0, "?");
    return builder.toString();
  }

  /**
   * Get the name.
   *
   * @return the name
   */
  public String getName() {
    return this.processor.toString();
  }

  /**
   * Get all the processors.
   *
   * @return all the processors
   */
  public Set<? extends Processor<?, ?>> getAllProcessors() {
    final IdentityHashMap<Processor<?, ?>, Void> processors = new IdentityHashMap<>();
    processors.put(this.processor, null);
    for (ProcessorGraphNode<?, ?> node : this.dependencies) {
      processors.putAll(node.getAllProcessors());
    }
    return processors.keySet();
  }

  /**
   * A task that can be executed by the Fork/Join framework.
   *
   * @param <In> the input type
   * @param <Out> the output type
   */
  public static final class ProcessorNodeForkJoinTask<In, Out>
      extends RecursiveTask<Values> {
    private final ProcessorExecutionContext execContext;
    private final ProcessorGraphNode<In, Out> node;

    private ProcessorNodeForkJoinTask(
        final ProcessorGraphNode<In, Out> node, final ProcessorExecutionContext execContext) {
      this.node = node;
      this.execContext = execContext;
    }

    @Override
    protected Values compute() {
      final com.codahale.metrics.Timer.Context timerContext =
          this.node.metricRegistry.timer(
              MetricRegistry.name(ProcessorGraphNode.class.getSimpleName(), "compute",
                  this.node.processor.getClass().getSimpleName()))
              .time();
      try {
        this.execContext.getContext().mdcContext(() -> {
          final Values values = this.execContext.getValues();
          executeProcess(this.node.processor, values);
          this.execContext.getContext().stopIfCanceled();
          ProcessorDependencyGraph.tryExecuteNodes(this.node.dependencies, this.execContext, true);
          return values;
        });
      } catch (Exception e) {
        throw new PrintException(e);
      }
      timerContext.stop();
      LOGGER.info(
          "Time taken to run processor: '{}' was {} ms",
          this.node.processor.getClass(),
          TimeUnit.MILLISECONDS.convert(timerContext.stop(), TimeUnit.NANOSECONDS));
      return this.execContext.getValues();
    }

    private void executeProcess(
        final Processor<In, Out> process, final Values values) {
      final String timerName =
          MetricRegistry.name(ProcessorGraphNode.class.getSimpleName(), "compute",
              process.getClass().getSimpleName());
      final Timer.Context timerContext = this.node.metricRegistry.timer(timerName).time();
      try {
        final Object inputParameter = ProcessorUtils.populateInputParameter(process, values);
        Out output;
        try {
          LOGGER.debug("Executing process: {}", process);
          output = process.execute(inputParameter, this.execContext.getContext());
          LOGGER.debug("Succeeded in executing process: {}", process);
        } catch (RuntimeException e) {
          throw handleException(e, e, process, timerName);
        } catch (Exception e) {
          throw handleException(e, null, process, timerName);
        }
        if (output != null) {
          ProcessorUtils.writeProcessorOutputToValues(output, process, values);
        }
      } finally {
        this.execContext.finished(this.node);
        timerContext.stop();
        LOGGER.info(
            "Time taken to run processor: '{}' was {} ms",
            process.getClass(),
            TimeUnit.MILLISECONDS.convert(timerContext.stop(), TimeUnit.NANOSECONDS));
      }
    }

    private RuntimeException handleException(
        final Exception cause,
        final RuntimeException runtimeCause,
        final Processor<In, Out> process,
        final String timerName) {
      LOGGER.info("Error while executing process: {} {}", process, cause);
      try {
        this.execContext.getContext().stopIfCanceled();
      } catch (Exception e) {
        // If the processor is in cancel state, we don't care about the error
      }
      this.node.metricRegistry.counter(MetricRegistry.name(timerName, "error")).inc();
      return Objects.requireNonNullElseGet(runtimeCause, () -> new PrintException(cause));
    }
  }
}

package org.mapfish.print.attribute.map;

import java.awt.Rectangle;
import org.geotools.api.referencing.crs.CoordinateReferenceSystem;
import org.geotools.geometry.jts.ReferencedEnvelope;
import org.locationtech.jts.geom.Coordinate;
import org.mapfish.print.map.DistanceUnit;
import org.mapfish.print.map.Scale;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Abstract class for map bounds.
 *
 * @param <T> the type of the bounds
 */
public abstract class MapBounds {
  private static final Logger LOGGER = LoggerFactory.getLogger(MapBounds.class);
  private final CoordinateReferenceSystem projection;
  private final boolean useGeodeticCalculations;

  /**
   * Constructor.
   *
   * @param projection the projection
   * @param useGeodeticCalculations whether to use geodetic calculations
   */
  protected MapBounds(
      final CoordinateReferenceSystem projection, final boolean useGeodeticCalculations) {
    this.projection = projection;
    this.useGeodeticCalculations = useGeodeticCalculations;
  }

  /**
   * Constructor.
   *
   * @param projection the projection
   */
  protected MapBounds(final CoordinateReferenceSystem projection) {
    this(projection, false);
  }

  /**
   * Returns the bounds as a {@link ReferencedEnvelope}.
   *
   * @param paintArea the paint area
   */
  public abstract ReferencedEnvelope toReferencedEnvelope(Rectangle paintArea);

  /**
   * Returns the bounds adjusted to the given paint area.
   *
   * @param paintArea the paint area
   */
  public abstract MapBounds adjustedEnvelope(Rectangle paintArea);

  /**
   * Returns the scale for the given paint area.
   *
   * @param paintArea the paint area
   * @param dpi the dpi
   */
  public final CoordinateReferenceSystem getProjection() {
    return this.projection;
  }

  /**
   * Returns the bounds adjusted to the given zoom level.
   *
   * @param zoomLevels the zoom levels
   * @param tolerance the tolerance
   * @param zoomLevelSnapStrategy the zoom level snap strategy
   * @param geodetic whether to use geodetic calculations
   * @param paintArea the paint area
   * @param dpi the dpi
   */
  public abstract MapBounds adjustBoundsToNearestScale(
      ZoomLevels zoomLevels,
      double tolerance,
      ZoomLevelSnapStrategy zoomLevelSnapStrategy,
      boolean geodetic,
      Rectangle paintArea,
      double dpi);

  /**
   * Returns the nearest scale.
   *
   * @param zoomLevels the zoom levels
   * @param tolerance the tolerance
   * @param zoomLevelSnapStrategy the zoom level snap strategy
   * @param geodetic whether to use geodetic calculations
   * @param paintArea the paint area
   * @param dpi the dpi
   */
  public Scale getNearestScale(
      final ZoomLevels zoomLevels,
      final double tolerance,
      final ZoomLevelSnapStrategy zoomLevelSnapStrategy,
      final boolean geodetic,
      final Rectangle paintArea,
      final double dpi) {
    Scale scale = getScale(paintArea, dpi);
    double scaleRatio = 1;
    if (geodetic && !useGeodeticCalculations()) {
      scaleRatio =
          scale.getDenominator(dpi)
              / scale.getGeodeticDenominator(getProjection(), dpi, getCenter());
      scale =
          new Scale(
              scale.getResolution() / scaleRatio, getProjection(), dpi, scale.getMatrixSize());
    }
    final DistanceUnit unit = DistanceUnit.fromProjection(getProjection());
    final ZoomLevelSnapStrategy.SearchResult result =
        zoomLevelSnapStrategy.search(
            new Scale(scale.getDenominator(dpi) * scaleRatio, getProjection(), dpi),
            tolerance,
            zoomLevels);
    if (geodetic && !useGeodeticCalculations()) {
      return new Scale(
          result.getScale(unit).getDenominator(dpi) * scaleRatio, getProjection(), dpi);
    }
    return result.getScale(unit);
  }

  /**
   * Returns the scale for the given paint area.
   *
   * @param paintArea the paint area
   * @param dpi the dpi
   */
  public abstract Scale getScale(Rectangle paintArea, double dpi);

  /**
   * Returns the bounds adjusted to the given rotation.
   *
   * @param rotation the rotation
   */
  public abstract MapBounds adjustBoundsToRotation(double rotation);

  /**
   * Returns the bounds zoomed out.
   *
   * @param factor the zoom factor
   */
  public abstract MapBounds zoomOut(double factor);

  /**
   * Returns the bounds zoomed to the given scale.
   *
   * @param scale the scale
   */
  public abstract MapBounds zoomToScale(Scale scale);

  /**
   * Returns the center.
   *
   * @param scale the scale
   */
  public abstract Coordinate getCenter();

  /**
   * Returns whether to use geodetic calculations.
   *
   * @param scale the scale
   */
  public boolean useGeodeticCalculations() {
    return this.useGeodeticCalculations;
  }

  @Override
  public boolean equals(final Object o) {
    if (this == o) {
      return true;
    }
    if (o == null) {
      return false;
    }
    if (getClass() != o.getClass()) {
      return false;
    }
    MapBounds mapBounds = (MapBounds) o;
    return projection.equals(mapBounds.projection) && useGeodeticCalculations == mapBounds.useGeodeticCalculations;
  }

  @Override
  public int hashCode() {
    int result = projection.hashCode();
    result = 31 * result + (useGeodeticCalculations ? 1 : 0);
    return result;
  }
}

