package org.opentcs.util;

import static java.util.Objects.requireNonNull;

import jakarta.annotation.Nonnull;
import java.awt.Color;

/**
 * Provides methods concerning colors.
 */
public class Colors {

  /**
   * Prevents instantiation of this utility class.
   */
  private Colors() {
  }

  /**
   * Encodes a color to a hex string.
   *
   * @param color The color to be encoded.
   * @return The encoded color.
   */
  @Nonnull
  public static String encodeToHexRGB(
      @Nonnull
      Color color
  ) {
    requireNonNull(color, "color");

    return String.format(
        "#%06X",
        color.getRGB() & 0x00FFFFFF
    );
  }

  /**
   * Decodes a hex string to a color.
   *
   * @param rgbHex The hex string to be decoded.
   * @return The decoded color.
   * @throws NumberFormatException If the given string cannot be decoded to a color.
   */
  @Nonnull
  public static Color decodeFromHexRGB(
      @Nonnull
      String rgbHex
  )
      throws NumberFormatException {
    requireNonNull(rgbHex, "rgbHex");

    return Color.decode(rgbHex);
  }
}

package org.mapfish.print.processor.http.matcher;

import java.net.MalformedURLException;
import java.net.URI;
import org.apache.commons.lang3.Strings;
import org.apache.hc.client5.http.auth.AuthScope;
import org.springframework.http.HttpMethod;

/**
 * Contains the information from a URI or AuthScope.
 *
 * <p>If the matcher is created from a URI, then the scheme, host, port, path, query, and fragment
 * are set. If the matcher is created from an AuthScope, then the scheme, host, port, and realm
 * are set.
 */
public final class MatchInfo {
  /** The string representing the any scheme. */
  public static final String ANY_SCHEME = null;
  /** The string representing the any host. */
  public static final String ANY_HOST = null;
  /** The string representing the any realm. */
  public static final String ANY_REALM = null;
  /** The string representing the any path. */
  public static final String ANY_PATH = null;
  /** The string representing the any fragment. */
  public static final String ANY_FRAGMENT = null;
  /** The string representing the any query. */
  public static final String ANY_QUERY = null;
  /** The string representing the any method. */
  public static final HttpMethod ANY_METHOD = null;
  /** The int representing the any port. */
  public static final int ANY_PORT = -1;

  private final String scheme;
  private final String host;
  private final int port;
  private final String path;
  private final String fragment;
  private final String query;
  private final String realm;
  private final HttpMethod method;

  private MatchInfo(
      final String scheme, final String host, final int port, final String realm) {
    this.scheme = scheme;
    this.host = host;
    this.port = port;
    this.path = ANY_PATH;
    this.fragment = ANY_FRAGMENT;
    this.query = ANY_QUERY;
    this.realm = realm;
    this.method = ANY_METHOD;
  }

  private MatchInfo(final URI uri, final int port, final HttpMethod method) {
    this.scheme = uri.getScheme();
    this.host = uri.getHost();
    this.port = port;
    this.path = uri.getPath();
    this.fragment = uri.getFragment();
    this.query = uri.getQuery();
    this.realm = ANY_REALM;
    this.method = method;
  }

  /**
   * Create a MatchInfo from a URI.
   *
   * @param uri the URI
   * @param method the HTTP method
   */
  public static MatchInfo fromUri(final URI uri, final HttpMethod method) {
    int port = uri.getPort();
    if (port < 0) {
      try {
        port = uri.toURL().getDefaultPort();
      } catch (MalformedURLException e) {
        port = ANY_PORT;
      } catch (IllegalArgumentException e) {
        port = ANY_PORT;
      }
    }
    return new MatchInfo(uri, port, method);
  }

  /**
   * Create a MatchInfo from an AuthScope.
   *
   * @param authscope the AuthScope
   */
  public static MatchInfo fromAuthScope(final AuthScope authscope) {
    return new MatchInfo(
        Strings.CS.equals(authscope.getSchemeName(), ANY_SCHEME) ? null : authscope.getSchemeName(),
        Strings.CS.equals(authscope.getHost(), ANY_HOST) ? null : authscope.getHost(),
        authscope.getPort() == ANY_PORT ? -1 : authscope.getPort(),
        Strings.CS.equals(authscope.getRealm(), ANY_REALM) ? null : authscope.getRealm());
  }

  private static String valOrAny(final String val) {
    return val != null ? val : "*";
  }

  /**
   * Get the scheme.
   *
   * @return the scheme
   */
  public String getScheme() {
    return scheme;
  }

  /**
   * Get the host.
   *
   * @return the host
   */
  public String getHost() {
    return host;
  }

  /**
   * Get the port.
   *
   * @return the port
   */
  public int getPort() {
    return port;
  }

  /**
   * Get the path.
   *
   * @return the path
   */
  public String getPath() {
    return path;
  }

  /**
   * Get the fragment.
   *
   * @return the fragment
   */
  public String getFragment() {
    return fragment;
  }

  /**
   * Get the query.
   *
   * @return the query
   */
  public String getQuery() {
    return query;
  }

  /**
   * Get the realm.
   *
   * @return the realm
   */
  public String getRealm() {
    return realm;
  }

  @Override
  public String toString() {
    String str =
        String.format(
            "%s://%s:%s%s",
            valOrAny(scheme), valOrAny(host), Integer.toString(port), path);
    if (method != ANY_METHOD) {
      str = method + " " + str;
    }
    if (query != ANY_QUERY) {
      str += "?" + query;
    }
    if (fragment != ANY_FRAGMENT) {
      str += "#" + fragment;
    }
    return str;
  }
}

package org.mapfish.print.map.tiled;

import com.google.common.collect.HashMultimap;
import com.google.common.collect.Multimap;
import java.net.URI;
import java.net.URISyntaxException;
import java.util.Iterator;
import org.mapfish.print.parser.HasDefaultValue;
import org.mapfish.print.wrapper.PArray;
import org.mapfish.print.wrapper.PObject;
import org.mapfish.print.wrapper.json.PJsonObject;

/** Abstract class for WMS/WMTS layer parameters. */
public abstract class AbstractWMXLayerParams extends AbstractTiledLayerParams {
  private final Multimap<String, String> additionalCustomParam = HashMultimap.create();

  /**
   * Custom query parameters that are not mergeable. If the value is different, the layers will not
   * be merged.
   */
  @HasDefaultValue public PObject customParams;

  /**
   * Custom query parameters that are mergeable. If the value is different, the layers will be
   * merged.
   */
  @HasDefaultValue public PJsonObject mergeableParams;

  /** Constructor. */
  protected AbstractWMXLayerParams() {
    super();
  }

  /**
   * Copy constructor.
   *
   * @param other the object to copy
   */
  protected AbstractWMXLayerParams(final AbstractWMXLayerParams other) {
    super(other);
    this.additionalCustomParam.putAll(other.additionalCustomParam);
    this.customParams = other.customParams;
    this.mergeableParams = other.mergeableParams;
  }

  /**
   * Get the custom parameters.
   *
   * @return the custom parameters
   */
  public final Multimap<String, String> getCustomParams() {
    Multimap<String, String> result = convertToMultiMap(this.customParams);
    result.putAll(this.additionalCustomParam);
    return result;
  }

  /**
   * Get the mergeable parameters.
   *
   * @return the mergeable parameters
   */
  public final Multimap<String, String> getMergeableParams() {
    return convertToMultiMap(this.mergeableParams);
  }

  private Multimap<String, String> convertToMultiMap(final PObject objectParams) {
    Multimap<String, String> result = HashMultimap.create();
    if (objectParams != null) {
      final Iterator<String> keys = objectParams.keys();
      while (keys.hasNext()) {
        final String key = keys.next();
        if (objectParams.isArray(key)) {
          final PArray array = objectParams.optArray(key);
          for (int i = 0; i < array.size(); i++) {
            result.put(key, array.getString(i));
          }
        } else {
          result.put(key, objectParams.optString(key, ""));
        }
      }
    }
    return result;
  }

  @Override
  public String createCommonUrl() throws URISyntaxException {
    return getBaseUrl();
  }

  /**
   * Set a custom parameter.
   *
   * @param name the parameter name
   * @param value the parameter value
   */
  public final void setCustomParam(final String name, final String value) {
    this.additionalCustomParam.put(name, value);
  }

  @Override
  public boolean validateBaseUrl() {
    try {
      new URI(getBaseUrl());
      return true;
    } catch (URISyntaxException e) {
      return false;
    }
  }
}

