package org.opentcs.util;

import java.util.Comparator;
import org.opentcs.data.TCSObject;
import org.opentcs.data.TCSObjectReference;
import org.opentcs.data.order.TransportOrder;
import org.opentcs.data.peripherals.PeripheralJob;

/**
 * Provides various {@link Comparator}s.
 */
public final class Comparators {

  /**
   * Prevents instantiation of this utility class.
   */
  private Comparators() {
  }

  /**
   * Returns a {@link Comparator} that compares {@link TCSObject}s by name.
   *
   * @return A {@link Comparator} that compares {@link TCSObject}s by name.
   */
  public static Comparator<TCSObject<?>> objectsByName() {
    return Comparator.comparing(TCSObject::getName);
  }

  /**
   * Returns a {@link Comparator} that compares {@link TCSObjectReference}s by name.
   *
   * @return A {@link Comparator} that compares {@link TCSObjectReference}s by name.
   */
  public static Comparator<TCSObjectReference<?>> referencesByName() {
    return Comparator.comparing(TCSObjectReference::getName);
  }

  /**
   * Returns a {@link Comparator} that compares {@link TransportOrder}s by deadline.
   *
   * @return A {@link Comparator} that compares {@link TransportOrder}s by deadline.
   */
  public static Comparator<TransportOrder> ordersByDeadline() {
    return Comparator.comparing(TransportOrder::getDeadline)
        .thenComparing(ordersByAge());
  }

  /**
   * Returns a {@link Comparator} that compares {@link TransportOrder}s by age.
   *
   * @return A {@link Comparator} that compares {@link TransportOrder}s by age.
   */
  public static Comparator<TransportOrder> ordersByAge() {
    return Comparator.comparing(TransportOrder::getCreationTime)
        .thenComparing(objectsByName());
  }

  /**
   * Returns a {@link Comparator} that compares {@link PeripheralJob}s by age.
   *
   * @return A {@link Comparator} that compares {@link PeripheralJob}s by age.
   */
  public static Comparator<PeripheralJob> jobsByAge() {
    return Comparator.comparing(PeripheralJob::getCreationTime)
        .thenComparing(objectsByName());
  }
}

package org.mapfish.print.wrapper.yaml;

import java.util.Arrays;
import java.util.List;
import java.util.Map;
import org.json.JSONArray;
import org.mapfish.print.wrapper.ObjectMissingException;
import org.mapfish.print.wrapper.PArray;
import org.mapfish.print.wrapper.PElement;
import org.mapfish.print.wrapper.PObject;
import org.mapfish.print.wrapper.json.PJsonArray;

/** A wrapper for a Yaml array. */
public class PYamlArray extends PElement implements PArray {
  private final List<Object> array;

  /**
   * Constructor.
   *
   * @param parent the parent
   * @param array the array
   * @param contextName the context name
   */
  public PYamlArray(
      final PElement parent, final List<Object> array, final String contextName) {
    super(parent, contextName);
    this.array = array;
  }

  @Override
  public final int size() {
    return this.array.size();
  }

  @Override
  public final PObject getObject(final int i) {
    final Map<String, Object> val = (Map<String, Object>) this.array.get(i);
    final String context = "[" + i + "]";
    if (val == null) {
      throw new ObjectMissingException(this, context);
    }
    return new PYamlObject(this, val, context);
  }

  @Override
  public final PArray getArray(final int i) {
    final List<Object> val = (List<Object>) this.array.get(i);
    final String context = "[" + i + "]";
    if (val == null) {
      throw new ObjectMissingException(this, context);
    }
    return new PYamlArray(this, val, context);
  }

  @Override
  public final int getInt(final int i) {
    return (int) this.array.get(i);
  }

  @Override
  public final long getLong(final int i) {
    return ((Number) this.array.get(i)).longValue();
  }

  @Override
  public final float getFloat(final int i) {
    return ((Number) this.array.get(i)).floatValue();
  }

  @Override
  public final double getDouble(final int i) {
    return ((Number) this.array.get(i)).doubleValue();
  }

  @Override
  public final String getString(final int i) {
    return (String) this.array.get(i);
  }

  @Override
  public final boolean getBool(final int i) {
    return (boolean) this.array.get(i);
  }

  @SuppressWarnings("unchecked")
  @Override
  public final Object get(final int i) {
    final Object val = this.array.get(i);
    if (val instanceof Map<?, ?>) {
      return new PYamlObject(this, (Map<String, Object>) val, String.valueOf(i));
    } else if (val instanceof List<?>) {
      return new PYamlArray(this, (List<Object>) val, String.valueOf(i));
    } else if (val != null && val.getClass().isArray()) {
      return new PYamlArray(this, Arrays.asList((Object[]) val), String.valueOf(i));
    } else {
      return val;
    }
  }

  @Override
  public final String toString() {
    return "PYaml(" + getCurrentPath() + ":" + toJSON().getInternalArray().toString(2) + ")";
  }

  /** Convert to a JSON array. */
  public final PJsonArray toJSON() {
    final JSONArray jsonArray = new JSONArray();
    final int size = this.array.size();
    for (int i = 0; i < size; i++) {
      final Object val = get(i);
      if (val instanceof PYamlObject) {
        jsonArray.put(((PYamlObject) val).toJSON().getInternalObj());
      } else if (val instanceof PYamlArray) {
        jsonArray.put(((PYamlArray) val).toJSON().getInternalArray());
      } else {
        jsonArray.put(val);
      }
    }
    return new PJsonArray(null, jsonArray, getContextName());
  }
}

