package org.mapfish.print.map.style;

import jakarta.annotation.Nonnull;
import jakarta.annotation.Nullable;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.net.URI;
import java.net.URISyntaxException;
import java.net.URL;
import java.nio.charset.Charset;
import java.util.Objects;
import java.util.Optional;
import java.util.function.Function;
import javax.xml.XMLConstants;
import javax.xml.parsers.DocumentBuilder;
import javax.xml.parsers.DocumentBuilderFactory;
import javax.xml.parsers.ParserConfigurationException;
import org.geotools.api.style.Style;
import org.geotools.factory.CommonFactoryFinder;
import org.geotools.styling.DefaultResourceLocator;
import org.geotools.xml.styling.SLDParser;
import org.locationtech.jts.util.Assert;
import org.mapfish.print.Constants;
import org.mapfish.print.config.Configuration;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.http.HttpMethod;
import org.springframework.http.client.ClientHttpRequest;
import org.springframework.http.client.ClientHttpRequestFactory;
import org.xml.sax.SAXException;
import org.xml.sax.SAXParseException;
import org.xml.sax.helpers.DefaultHandler;

/**
 * Parses SLD documents.
 *
 * <p>Supports the following formats:
 *
 * <ul>
 *   <li>Direct SLD XML
 *   <li>URL to SLD
 *   <li>URL to SLD with style index (##)
 * </ul>
 */
public class SLDParserPlugin implements StyleParserPlugin {
  /** The separator between the style ref and the style index. */
  public static final String STYLE_INDEX_REF_SEPARATOR = "##";

  @Override
  public final Optional<Style> parseStyle(
      @Nullable final Configuration configuration,
      @Nonnull final ClientHttpRequestFactory clientHttpRequestFactory,
      @Nonnull final String styleString) {
    final byte[] bytes = styleString.getBytes(Constants.DEFAULT_CHARSET);
    final Optional<Style> style = tryLoadSLD(bytes, null, clientHttpRequestFactory);
    if (style.isPresent()) {
      return style;
    }

    final Optional<Integer> styleIndex = lookupStyleIndex(styleString);
    final String ref = removeIndexReference(styleString);
    final Function<byte[], Optional<Style>> loadFunction =
        (b) -> tryLoadSLD(b, styleIndex.orElse(null), clientHttpRequestFactory);
    return ParserPluginUtils.loadStyleAsURI(clientHttpRequestFactory, ref, loadFunction);
  }

  private String removeIndexReference(final String styleString) {
    final int index = styleString.lastIndexOf(STYLE_INDEX_REF_SEPARATOR);
    if (index > 0) {
      return styleString.substring(0, index);
    }
    return styleString;
  }

  private Optional<Integer> lookupStyleIndex(final String ref) {
    final int index = ref.lastIndexOf(STYLE_INDEX_REF_SEPARATOR);
    if (index > 0) {
      return Optional.of(Integer.parseInt(ref.substring(index + 2)) - 1);
    }
    return Optional.empty();
  }

  private Optional<Style> tryLoadSLD(
      final byte[] bytes,
      final Integer styleIndex,
      final ClientHttpRequestFactory clientHttpRequestFactory) {
    Assert.isTrue(
        styleIndex == null || styleIndex > -1,
        "Invalid style index: " + styleIndex);
    if (isNonXml(bytes)) {
      return Optional.empty();
    }

    try {
      final DocumentBuilderFactory factory = DocumentBuilderFactory.newInstance();
      factory.setNamespaceAware(true);
      factory.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
      factory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
      factory.setFeature("http://xml.org/sax/features/external-general-entities", false);
      factory.setFeature("http://xml.org/sax/features/external-parameter-entities", false);
      factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_DTD, "");
      factory.setAttribute(XMLConstants.ACCESS_EXTERNAL_SCHEMA, "");
      factory.setXIncludeAware(false);
      factory.setExpandEntityReferences(false);

      final DocumentBuilder builder = factory.newDocumentBuilder();
      builder.setErrorHandler(new ErrorHandler());
      builder.parse(new ByteArrayInputStream(bytes));
    } catch (ParserConfigurationException | SAXException | IOException e) {
      return Optional.empty();
    }

    final org.geotools.factory.CommonFactoryFinder.StyleFactory styleFactory =
        CommonFactoryFinder.getStyleFactory();
    final SLDParser parser = new SLDParser(styleFactory);
    parser.setOnLineResourceLocator(
        new DefaultResourceLocator() {
          @Override
          public URL locateResource(final String uri) {
            final URL theUri = super.locateResource(uri);
            if (theUri != null) {
              return theUri.toURI().toURL();
            }
            try {
              final ClientHttpRequest request =
                  clientHttpRequestFactory.createRequest(URI.create(uri), HttpMethod.GET);
              return request.getURI().toURL();
            } catch (IOException | URISyntaxException e) {
              return null;
            }
          }
        });
    try {
      parser.setInput(new ByteArrayInputStream(bytes));
      final Style[] styles = parser.readXML();
      if (styleIndex != null) {
        Assert.isTrue(
            styleIndex < styles.length,
            "Invalid style index: "
                + styles.length
                + " styles in the SLD file, but the index is "
                + styleIndex
                + 1);
        return Optional.of(styles[Objects.requireNonNullElse(styleIndex, 0)]);
      }
      Assert.isTrue(
          styles.length < 2,
          "Invalid style index: "
              + styles.length
              + " styles in the SLD file, but no index was provided. "
              + "Please specify the style index using the "
              + "thinline.sld##1 format. Example: "
              + "thinline.sld##1");
      return Optional.of(styles[0]);
    } catch (ParserConfigurationException | SAXException | IOException e) {
      return Optional.empty();
    }
  }

  private static boolean isNonXml(final byte[] bytes) {
    for (final byte b : bytes) {
      if (Charset.defaultCharset().decode(b).charAt(0) != ' ') {
        if (b != '<') {
          return true;
        }
      }
    }
    return false;
  }

  /** The error handler for the XML parser. */
  public static class ErrorHandler extends DefaultHandler {
    private static final Logger LOGGER = LoggerFactory.getLogger(ErrorHandler.class);

    /**
     * Log the error.
     *
     * @param e the error
     */
    public final void error(final SAXParseException e) throws SAXException {
      LOGGER.warn("XML error: {}", e.getLocalizedMessage(), e);
      super.error(e);
    }

    /**
     * Log the fatal error.
     *
     * @param e the error
     */
    public final void fatalError(final SAXParseException e) throws SAXException {
      LOGGER.warn("XML error: {}", e.getLocalizedMessage(), e);
      super.fatalError(e);
    }

    /**
     * Log the warning.
     *
     * @param e the warning
     */
    public final void warning(final SAXParseException e) throws SAXException {
      LOGGER.warn("XML error: {}", e.getLocalizedMessage(), e);
      super.warning(e);
    }
  }
}

