package org.mapfish.print.cli;

import ch.qos.logback.classic.LoggerContext;
import ch.qos.logback.classic.joran.JoranConfigurator;
import ch.qos.logback.core.joran.spi.JoranException;
import ch.qos.logback.core.util.StatusPrinter2;
import com.google.common.annotations.VisibleForTesting;
import com.sampullara.cli.Args;
import java.io.File;
import java.io.FileInputStream;
import java.io.FileNotFoundException;
import java.io.FileOutputStream;
import java.io.InputStream;
import java.io.OutputStream;
import java.io.OutputStreamWriter;
import java.net.URL;
import java.util.HashMap;
import java.util.List;
import org.apache.commons.io.IOUtils;
import org.json.JSONWriter;
import org.mapfish.print.Constants;
import org.mapfish.print.MapPrinter;
import org.mapfish.print.url.data.Handler;
import org.mapfish.print.wrapper.json.PJsonObject;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.support.AbstractXmlApplicationContext;
import org.springframework.context.support.ClassPathXmlApplicationContext;

/** The CLI entry point. */
public final class Main {
  /** The default spring context. */
  public static final String DEFAULT_SPRING_CONTEXT = "/mapfish-cli-spring-application-context.xml";

  private static final Logger LOGGER = LoggerFactory.getLogger(Main.class);

  private static final int LOGLEVEL_QUIET = 0;
  private static final int LOGLEVEL_INFO = 1;
  private static final int LOGLEVEL_DEFAULT = 2;
  private static final int LOGLEVEL_VERBOSE = 3;

  private static boolean exceptionOnFailure = false;

  @Autowired private MapPrinter mapPrinter;

  private Main() {
    // do nothing
  }

  /**
   * The main method.
   *
   * @param args the arguments
   */
  public static void main(final String[] args) throws Exception {
    runMain(args);
    System.exit(0);
  }

  @VisibleForTesting
  public static void runMain(final String[] args) throws Exception {
    CliHelpDefinition helpCli = new CliHelpDefinition();
    try {
      Args.parse(helpCli, args);
    } catch (IllegalArgumentException e) {
      // ignore
    }
    if (helpCli.help) {
      printUsage(0);
      return;
    }

    CliDefinition cli = new CliDefinition();
    try {
      List<String> unrecognized = Args.parse(cli, args);
      if (!unrecognized.isEmpty()) {
        System.out.println("\nThe following arguments are not recognized:");
        System.out.println(unrecognized);
        printUsage(1);
        return;
      }
    } catch (IllegalArgumentException e) {
      System.out.println("\n" + e.getMessage());
      printUsage(1);
      return;
    }

    configureLogs(cli.verbose);
    AbstractXmlApplicationContext context =
        new ClassPathXmlApplicationContext(DEFAULT_SPRING_CONTEXT);
    if (cli.springConfig != null) {
      context =
          new ClassPathXmlApplicationContext(
              DEFAULT_SPRING_CONTEXT, cli.springConfig);
    }
    try {
      Main main = context.getBean(Main.class);
      main.run(cli);
    } finally {
      context.close();
    }
  }

  private static void printUsage(final int exitCode) {
    Args.usage(new CliDefinition());
    if (exceptionOnFailure) {
      throw new Error("Printing Usage: " + exitCode);
    } else {
      System.exit(exitCode);
    }
  }

  private static void configureLogs(final String verbose) {
    ClassLoader classLoader = Main.class.getClassLoader();
    URL logfile =
        classLoader.getResource(
            Integer.parseInt(verbose) == LOGLEVEL_QUIET
                ? "shell-quiet-log.xml"
                : Integer.parseInt(verbose) == LOGLEVEL_INFO
                    ? "shell-info-log.xml"
                    : Integer.parseInt(verbose) == LOGLEVEL_VERBOSE
                        ? "shell-verbose-log.xml"
                        : "shell-default-log.xml");
    LoggerContext loggerContext = (LoggerContext) LoggerFactory.getILoggerFactory();
    try {
      JoranConfigurator configurator = new JoranConfigurator();
      configurator.setContext(loggerContext);
      loggerContext.reset();
      configurator.doConfigure(logfile);
    } catch (JoranException e) {
      // ignore
    }
    new StatusPrinter2().printInCaseOfErrorsOrWarnings(loggerContext);
  }

  private static LoggerContext getLoggerContext(final URL logfile) {
    LoggerContext loggerContext = (LoggerContext) LoggerFactory.getILoggerFactory();
    try {
      JoranConfigurator configurator = new JoranConfigurator();
      configurator.setContext(loggerContext);
      loggerContext.reset();
      configurator.doConfigure(logfile);
    } catch (JoranException e) {
      // ignore
    }
    return loggerContext;
  }

  @VisibleForTesting
  static void setExceptionOnFailure(final boolean exceptionOnFailure) {
    Main.exceptionOnFailure = exceptionOnFailure;
  }

  private void run(final CliDefinition cli) throws Exception {
    File configFile = new File(cli.config);
    mapPrinter.setConfiguration(configFile);

    if (cli.clientConfig) {
      try (OutputStream outFile = getOutputStream(cli.output, ".yaml");
          OutputStreamWriter writer = new OutputStreamWriter(outFile, Constants.DEFAULT_CHARSET);
          JSONWriter json = new JSONWriter(writer)) {
        json.object();
        mapPrinter.printClientConfig(json);
        json.endObject();
        writer.close();
      }
    } else {
      try (InputStream inFile = getInputStream(cli.spec)) {
        String spec = IOUtils.toString(inFile, Constants.DEFAULT_ENCODING);
        PJsonObject jsonSpec = mapPrinter.parseSpec(spec);
        try (OutputStream outFile = getOutputStream(cli.output, mapPrinter.getOutputFormat(jsonSpec).getFileSuffix())) {
          if (LOGGER.isDebugEnabled()) {
            LOGGER.debug("Request Data: \n{}", jsonSpec.getInternalObj().toString(2));
          }
          mapPrinter.print(new HashMap<>(), jsonSpec, outFile);
        }
      }
    }
  }

  private OutputStream getOutputStream(final String output, final String suffix)
      throws FileNotFoundException {
    String outputPath = output;
    if (outputPath != null) {
      if (!outputPath.endsWith("." + suffix)) {
        outputPath = outputPath + "." + suffix;
      }
      return new FileOutputStream(outputPath);
    }
    return System.out;
  }

  private InputStream getInputStream(final String spec) throws FileNotFoundException {
    if (spec != null) {
      return new FileInputStream(spec);
    }
    return System.in;
  }
}

