package org.opentcs.util;

import static java.util.Objects.requireNonNull;

import jakarta.annotation.Nonnull;
import java.util.Map;
import java.util.Optional;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Utility methods for extracting values from {@link Map}s.
 */
public class MapValueExtractor {

  /**
   * This class's logger.
   */
  private static final Logger LOG = LoggerFactory.getLogger(MapValueExtractor.class);

  /**
   * Creates a new instance.
   */
  public MapValueExtractor() {
  }

  /**
   * Extracts a string value from the given map.
   *
   * @param key The key.
   * @param map The map.
   * @return The value, or an empty {@link Optional} if the map does not contain the given key or the
   * value is {@code null}.
   */
  public Optional<String> extractString(
      @Nonnull
      String key,
      @Nonnull
      Map<String, String> map
  ) {
    requireNonNull(key, "key");
    requireNonNull(map, "map");

    return Optional.ofNullable(map.get(key));
  }

  /**
   * Extracts an integer value from the given map.
   *
   * @param key The key.
   * @param map The map.
   * @return The value, or an empty {@link Optional} if the map does not contain the given key or the
   * value is {@code null}.
   */
  public Optional<Integer> extractInteger(
      @Nonnull
      String key,
      @Nonnull
      Map<String, String> map
  ) {
    requireNonNull(key, "key");
    requireNonNull(map, "map");

    return map.get(key)
        .map(
            value -> {
              try {
                return Integer.valueOf(value);
              }
              catch (NumberFormatException e) {
                LOG.warn("Failed to parse integer value for key '{}': '{}'", key, value);
                return null;
              }
            }
        );
  }

  /**
   * Extracts a long value from the given map.
   *
   * @param key The key.
   * @param map The map.
   * @return The value, or an empty {@link Optional} if the map does not contain the given key or the
   * value is {@code null}.
   */
  public Optional<Long> extractLong(
      @Nonnull
      String key,
      @Nonnull
      Map<String, String> map
  ) {
    requireNonNull(key, "key");
    requireNonNull(map, "map");

    return map.get(key)
        .map(
            value -> {
              try {
                return Long.valueOf(value);
              }
              catch (NumberFormatException e) {
                LOG.warn("Failed to parse long value for key '{}': '{}'", key, value);
                return null;
              }
            }
        );
  }

  /**
   * Extracts a double value from the given map.
   *
   * @param key The key.
   * @param map The map.
   * @return The value, or an empty {@link Optional} if the map does not contain the given key or the
   * value is {@code null}.
   */
  public Optional<Double> extractDouble(
      @Nonnull
      String key,
      @Nonnull
      Map<String, String> map
  ) {
    requireNonNull(key, "key");
    requireNonNull(map, "map");

    return map.get(key)
        .map(
            value -> {
              try {
                return Double.valueOf(value);
              }
              catch (NumberFormatException e) {
                LOG.warn("Failed to parse double value for key '{}': '{}'", key, value);
                return null;
              }
            }
        );
  }

  /**
   * Extracts a boolean value from the given map.
   *
   * @param key The key.
   * @param map The map.
   * @return The value, or an empty {@link Optional} if the map does not contain the given key or the
   * value is {@code null}.
   */
  public Optional<Boolean> extractBoolean(
      @Nonnull
      String key,
      @Nonnull
      Map<String, String> map
  ) {
    requireNonNull(key, "key");
    requireNonNull(map, "map");

    return map.get(key)
        .map(Boolean::valueOf);
  }

  /**
   * Extracts an enum value from the given map.
   *
   * @param key The key.
   * @param map The map.
   * @param enumClass The enum class.
   * @param <E> The enum type.
   * @return The value, or an empty {@link Optional} if the map does not contain the given key or the
   * value is {@code null}.
   */
  public <E extends Enum<E>> Optional<E> extractEnum(
      @Nonnull
      String key,
      @Nonnull
      Map<String, String> map,
      @Nonnull
      Class<E> enumClass
  ) {
    requireNonNull(key, "key");
    requireNonNull(map, "map");
    requireNonNull(enumClass, "enumClass");

    return map.get(key)
        .map(
            value -> {
              try {
                return Enum.valueOf(enumClass, value);
              }
              catch (IllegalArgumentException e) {
                LOG.warn("Failed to parse enum value for key '{}': '{}'", key, value);
                return null;
              }
            }
        );
  }
}

