package org.opentcs.kernel.extensions.servicewebapi.v1;

import jakarta.annotation.Nullable;
import java.util.Objects;
import java.util.function.Predicate;
import org.opentcs.data.TCSObjectReference;
import org.opentcs.data.model.Vehicle;
import org.opentcs.data.order.OrderSequence;
import org.opentcs.data.order.TransportOrder;
import org.opentcs.data.peripherals.PeripheralJob;

/**
 * Filters for various types.
 */
public class Filters {

  private Filters() {
  }

  /**
   * Returns a filter that accepts transport orders with the given vehicle as intended vehicle.
   *
   * @param vehicleRef The vehicle reference.
   * @return A filter that accepts transport orders with the given vehicle as intended vehicle.
   */
  public static Predicate<TransportOrder> transportOrderWithIntendedVehicle(
      @Nullable
      TCSObjectReference<Vehicle> vehicleRef
  ) {
    return vehicleRef == null
        ? order -> true
        : order -> Objects.equals(vehicleRef, order.getIntendedVehicle());
  }

  /**
