package org.opentcs.kernel.extensions.servicewebapi.v8;

import static java.util.Objects.requireNonNull;

import jakarta.inject.Inject;
import org.opentcs.components.kernel.services.PeripheralService;
import org.opentcs.data.ObjectUnknownException;
import org.opentcs.data.model.Location;
import org.opentcs.drivers.peripherals.PeripheralCommAdapterDescription;
import org.opentcs.drivers.peripherals.management.PeripheralAttachmentInformation;
import org.opentcs.kernel.extensions.servicewebapi.common.KernelExecutorWrapper;

/**
 * Handles requests related to peripherals.
 */
public class PeripheralHandler {

  private final PeripheralService peripheralService;
  private final KernelExecutorWrapper executorWrapper;

  /**
   * Creates a new instance.
   *
   * @param peripheralService Used to manage peripherals.
   * @param executorWrapper Executes calls via the kernel executor and waits for the outcome.
   */
  @Inject
  public PeripheralHandler(
      PeripheralService peripheralService,
      KernelExecutorWrapper executorWrapper
  ) {
    this.peripheralService = requireNonNull(peripheralService, "peripheralService");
    this.executorWrapper = requireNonNull(executorWrapper, "executorWrapper");
  }

  /**
   * Attaches the comm adapter with the given name to the peripheral device at the given location.
   *
   * @param name The name of the location.
   * @param value The name of the comm adapter to be attached.
   * @throws ObjectUnknownException If the given location does not exist.
   */
  public void putPeripheralCommAdapter(String name, String value)
      throws ObjectUnknownException {
    requireNonNull(name, "name");
    requireNonNull(value, "value");

    executorWrapper.callAndWait(() -> {
      Location location = peripheralService.fetch(Location.class, name)
          .orElseThrow(() -> new ObjectUnknownException("Unknown location: " + name));

      PeripheralCommAdapterDescription newAdapter = peripheralService
          .fetchAttachmentInformation(location.getReference())
          .getAvailableCommAdapters()
          .stream()
          .filter(description -> description.getClass().getName().equals(value))
          .findAny()
          .orElseThrow(
              () -> new IllegalArgumentException(
                  "Unknown peripheral driver class name: " + value
              )
          );

      peripheralService.attachCommAdapter(location.getReference(), newAdapter);
    });
  }

  /**
   * Enables/disables the comm adapter attached to the peripheral device at the given location.
   *
   * @param name The name of the location.
   * @param value Whether to enable or disable the comm adapter.
   * @throws ObjectUnknownException If the given location does not exist.
   * @throws IllegalArgumentException If the given value is not a boolean.
   */
  public void putPeripheralCommAdapterEnabled(String name, String value)
      throws ObjectUnknownException,
        IllegalArgumentException {
    requireNonNull(name, "name");
    requireNonNull(value, "value");

    executorWrapper.callAndWait(() -> {
      Location location = peripheralService.fetch(Location.class, name)
          .orElseThrow(() -> new ObjectUnknownException("Unknown location: " + name));

      if (Boolean.parseBoolean(value)) {
        peripheralService.enableCommAdapter(location.getReference());
      }
      else {
        peripheralService.disableCommAdapter(location.getReference());
      }
    });
  }

  /**
   * Returns the comm adapter attached to the peripheral device at the given location.
   *
   * @param name The name of the location.
   * @return The comm adapter attached to the peripheral device at the given location.
   * @throws ObjectUnknownException If the given location does not exist.
   */
  public PeripheralAttachmentInformation getPeripheralCommAdapterAttachmentInformation(String name)
      throws ObjectUnknownException {
    requireNonNull(name, "name");

    return executorWrapper.callAndWait(() -> {
      Location location = peripheralService.fetch(Location.class, name)
          .orElseThrow(() -> new ObjectUnknownException("Unknown location: " + name));

      return peripheralService.fetchAttachmentInformation(location.getReference());
    });
  }
}

