import jakarta.annotation.Nonnull;
import jakarta.inject.Inject;
import java.util.Map;
import org.opentcs.guing.base.model.elements.PathModel;

/**
 * A composite of all configured path length functions.
 */
public class CompositePathLengthFunction
    implements
      PathLengthFunction {

  /**
   * The path length functions, mapped to the path model type for which they are valid.
   */
  private final Map<PathModel.Type, PathLengthFunction> pathLengthFunctions;
  /**
   * The default path length function to be used when there is no specific one for a path model type.
   */
  private final EuclideanDistance euclideanDistance;

  @Inject
  public CompositePathLengthFunction(
      @Nonnull
      Map<PathModel.Type, PathLengthFunction> pathLengthFunctions,
      @Nonnull
      EuclideanDistance euclideanDistance
  ) {
    this.pathLengthFunctions = requireNonNull(pathLengthFunctions, "pathLengthFunctions");
    this.euclideanDistance = requireNonNull(euclideanDistance, "euclideanDistance");
  }

  @Override
  public double applyAsDouble(PathModel path) {
    PathModel.Type pathModelType = path.getPropertyPathConnType().getValue();
    PathLengthFunction pathLengthFunction = pathLengthFunctions.getOrDefault(
        pathModelType,
        euclideanDistance
    );
    return pathLengthFunction.applyAsDouble(path);
  }
}

