package org.opentcs.strategies.basic.dispatching;

import static java.util.Objects.requireNonNull;

import jakarta.inject.Inject;
import java.util.ArrayList;
import java.util.List;
import java.util.Optional;
import org.opentcs.components.kernel.RouteSelector;
import org.opentcs.components.kernel.Router;
import org.opentcs.data.model.Point;
import org.opentcs.data.model.Vehicle;
import org.opentcs.data.order.DriveOrder;
import org.opentcs.data.order.Route;
import org.opentcs.data.order.TransportOrder;

/**
 * Assigns routes to drive orders in transport orders.
 */
public class DriveOrderRouteAssigner {

  private final Router router;
  private final DefaultDispatcherConfiguration configuration;
  private final RouteSelector routeSelector;

  @Inject
  public DriveOrderRouteAssigner(
      Router router,
      RouteSelector routeSelector,
      DefaultDispatcherConfiguration configuration
  ) {
    this.router = requireNonNull(router, "router");
    this.routeSelector = requireNonNull(routeSelector, "routeSelector");
    this.configuration = requireNonNull(configuration, "configuration");
  }

  /**
   * Assigns routes to drive orders in the given transport order.
   *
   * @param order The transport order to be processed.
   * @param vehicle The vehicle to be used for processing.
   * @param startPosition The position at which the vehicle starts processing the transport order.
   * @return A list of drive orders with routes assigned, or an empty list, if no route could be found.
   */
  public Optional<List<DriveOrder>> tryAssignRoutes(
      TransportOrder order,
      Vehicle vehicle,
      Point startPosition
  ) {
    return routeSelector.selectSequence(router.getRoutes(vehicle, startPosition, order, configuration.maxRoutesToConsider()))
        .map(
            routes -> {
              List<DriveOrder> result = new ArrayList<>();
              for (int i = 0; i < order.getFutureDriveOrders().size(); i++) {
                result.add(order.getFutureDriveOrders().get(i).withRoute(routes.get(i)));
              }
              return result;
            }
        );
  }
}

