package org.opentcs.modeleditor.math.path;

import static java.util.Objects.requireNonNull;
import static org.opentcs.util.Assertions.checkArgument;

import jakarta.annotation.Nonnull;
import jakarta.inject.Inject;
import org.opentcs.guing.base.components.properties.type.LengthProperty;
import org.opentcs.guing.base.model.elements.PathModel;
import org.opentcs.guing.base.model.elements.PointModel;
import org.opentcs.guing.common.persistence.ModelManager;

/**
 * Calculates the length of a Bezier curve.
 */
public class BezierLength
    implements
      PathLengthFunction {

  /**
   * The scale factor in the X direction.
   */
  private final double scaleX;
  /**
   * The scale factor in the Y direction.
   */
  private final double scaleY;
  /**
   * Provides methods concerning the length of Bezier curves.
   */
  private final PathLengthMath pathLengthMath;

  @Inject
  public BezierLength(
      @Nonnull
      ModelManager manager,
      @Nonnull
      PathLengthMath pathLengthMath
  ) {
    this.pathLengthMath = requireNonNull(pathLengthMath, "pathLengthMath");
    requireNonNull(manager, "manager");
    scaleX = manager.getModel().getLayoutModel().getPropertyScaleX().getValueByUnit(LengthProperty.Unit.MM);
    scaleY = manager.getModel().getLayoutModel().getPropertyScaleY().getValueByUnit(LengthProperty.Unit.MM);
  }

  @Override
  public double applyAsDouble(
      @Nonnull
      PathModel path
  ) {
    requireNonNull(path, "path");

    String[] controlPoints = path.getPropertyPathControlPoints().getText().split(";");
    checkArgument(
        controlPoints.length == 2,
        String.format(
            "Path '%s' does not have exactly two control points.",
            path.getName()
        )
    );

    PointModel start = (PointModel) path.getStartComponent();
    PointModel end = (PointModel) path.getEndComponent();
    Coordinate startPoint = new Coordinate(
        start.getPropertyModelPositionX().getValueByUnit(LengthProperty.Unit.MM),
        start.getPropertyModelPositionY().getValueByUnit(LengthProperty.Unit.MM)
    );
    Coordinate endPoint = new Coordinate(
        end.getPropertyModelPositionX().getValueByUnit(LengthProperty.Unit.MM),
        end.getPropertyModelPositionY().getValueByUnit(LengthProperty.Unit.MM)
    );

    String[] firstControlPoint = controlPoints[0].split(",");
    String[] secondControlPoint = controlPoints[1].split(",");
    Coordinate firstControlPointCoordinate = new Coordinate(
        Double.parseDouble(firstControlPoint[0]) * scaleX,
        Double.parseDouble(firstControlPoint[1]) * scaleY * -1
    );
    Coordinate secondControlPointCoordinate = new Coordinate(
        Double.parseDouble(secondControlPoint[0]) * scaleX,
        Double.parseDouble(secondControlPoint[1]) * scaleY * -1
    );

    return pathLengthMath.approximateCubicBezierCurveLength(
        startPoint,
        firstControlPointCoordinate,
        secondControlPointCoordinate,
        endPoint,
        1000
    );
  }
}

