package org.opentcs.kernel.vehicles.transformers;

import static java.util.Objects.requireNonNull;

import jakarta.annotation.Nonnull;
import java.util.Optional;
import org.opentcs.data.model.Vehicle;
import org.opentcs.drivers.vehicle.IncomingPoseTransformer;
import org.opentcs.drivers.vehicle.MovementCommandTransformer;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Maps a vehicle coordinate system to a plant model coordinate system.
 */
public class CoordinateSystemMapping {

  /**
   * The property key for the x-axis translation.
   */
  public static final String PROPKEY_TRANSLATION_X = "tcs:coordinateSystemMapper.translation.x";
  /**
   * The property key for the y-axis translation.
   */
  public static final String PROPKEY_TRANSLATION_Y = "tcs:coordinateSystemMapper.translation.y";
  /**
   * The property key for the z-axis translation.
   */
  public static final String PROPKEY_TRANSLATION_Z = "tcs:coordinateSystemMapper.translation.z";
  /**
   * The property key for the rotation.
   */
  public static final String PROPKEY_ROTATION_Z = "tcs:coordinateSystemMapper.rotation.z";

  /**
   * This class's logger.
   */
  private static final Logger LOG = LoggerFactory.getLogger(CoordinateSystemMapping.class);

  /**
   * The x-axis translation.
   */
  private final int translationX;
  /**
   * The y-axis translation.
   */
  private final int translationY;
  /**
   * The z-axis translation.
   */
  private final int translationZ;
  /**
   * The rotation.
   */
  private final double rotationZ;

  /**
   * Creates a new instance.
   *
   * @param translationX The x-axis translation.
   * @param translationY The y-axis translation.
   * @param translationZ The z-axis translation.
   * @param rotationZ The rotation.
   */
  public CoordinateSystemMapping(
      int translationX,
      int translationY,
      int translationZ,
      double rotationZ
  ) {
    this.translationX = translationX;
    this.translationY = translationY;
    this.translationZ = translationZ;
    this.rotationZ = rotationZ;
  }

  /**
   * Returns the x-axis translation.
   *
   * @return The x-axis translation.
   */
  public int getTranslationX() {
    return translationX;
  }

  /**
   * Returns the y-axis translation.
   *
   * @return The y-axis translation.
   */
  public int getTranslationY() {
    return translationY;
  }

  /**
   * Returns the z-axis translation.
   *
   * @return The z-axis translation.
   */
  public int getTranslationZ() {
    return translationZ;
  }

  /**
   * Returns the rotation.
   *
   * @return The rotation.
   */
  public double getRotationZ() {
    return rotationZ;
  }

  /**
   * Returns a new instance created from the given vehicle's properties.
   *
   * @param vehicle The vehicle to create the mapping from.
   * @return A new instance created from the given vehicle's properties, or an empty
   * {@link Optional} if the vehicle's properties are not set.
   */
  public static Optional<CoordinateSystemMapping> fromVehicle(
      @Nonnull
      Vehicle vehicle
  ) {
    requireNonNull(vehicle, "vehicle");

    try {
      return Optional.of(
          new CoordinateSystemMapping(
              getPropertyInteger(vehicle, PROPKEY_TRANSLATION_X, 0),
              getPropertyInteger(vehicle, PROPKEY_TRANSLATION_Y, 0),
              getPropertyInteger(vehicle, PROPKEY_TRANSLATION_Z, 0),
              getPropertyDouble(vehicle, PROPKEY_ROTATION_Z, 0.0)
          )
      );
    }
    catch (NumberFormatException e) {
      LOG.warn(
          "Failed to create coordinate system mapping from vehicle '{}' properties: {}",
          vehicle.getName(),
          e
      );
      return Optional.empty();
    }
  }

  private static int getPropertyInteger(Vehicle vehicle, String propertyKey, int defaultValue)
      throws NumberFormatException {
    String property = vehicle.getProperty(propertyKey);
    if (property != null) {
      return Integer.parseInt(property);
    }
    LOG.debug(
        "Property '{}' not set in vehicle '{}' configuration. Using default value: {}",
        propertyKey,
        vehicle.getName(),
        defaultValue
    );
    return defaultValue;
  }

  private static double getPropertyDouble(Vehicle vehicle, String propertyKey, double defaultValue)
      throws NumberFormatException {
    String property = vehicle.getProperty(propertyKey);
    if (property != null) {
      return Double.parseDouble(property);
    }
    LOG.debug(
        "Property '{}' not set in vehicle '{}' configuration. Using default value: {}",
        propertyKey,
        vehicle.getName(),
        defaultValue
    );
    return defaultValue;
  }
}

