package org.opentcs.strategies.basic.routing.jgrapht;

import static java.util.Objects.requireNonNull;

import jakarta.annotation.Nonnull;
import java.util.Set;
import java.util.stream.Collectors;
import org.jgrapht.Graph;
import org.jgrapht.graph.AbstractBaseGraph;
import org.opentcs.components.kernel.routing.Edge;
import org.opentcs.data.model.Path;
import org.opentcs.data.model.Point;
import org.opentcs.strategies.basic.routing.jgrapht.GraphProvider.GraphResult;

/**
 * Creates a derived routing graph from a given one.
 */
public class GraphMutator {

  /**
   * Creates a new instance.
   */
  public GraphMutator() {
  }

  /**
   * Creates a derived routing graph from a given one.
   *
   * @param pointsToExclude The points to exclude.
   * @param pathsToExclude The paths to exclude.
   * @param baseGraph The base graph to derive the routing graph from.
   * @return A derived routing graph.
   */
  public GraphResult deriveGraph(
      @Nonnull
      Set<Point> pointsToExclude,
      @Nonnull
      Set<Path> pathsToExclude,
      @Nonnull
      GraphResult baseGraph
  ) {
    requireNonNull(pointsToExclude, "pointsToExclude");
    requireNonNull(pathsToExclude, "pathsToExclude");
    requireNonNull(baseGraph, "baseGraph");

    AbstractBaseGraph<Vertex, Edge> base = (AbstractBaseGraph<Vertex, Edge>) baseGraph.getGraph();
    Graph<Vertex, Edge> derivedGraph = base.clone();

    Set<String> pathsToExcludeByName = pathsToExclude.stream()
        .map(path -> path.getName())
        .collect(Collectors.toSet());

    // Remove edges that are part of paths to be excluded.
    base.edgeSet().forEach(
        edge -> {
          if (pathsToExcludeByName.contains(edge.getPath().getName())) {
            derivedGraph.removeEdge(edge);
          }
          else {
            derivedGraph.setEdgeWeight(edge, base.getEdgeWeight(edge));
          }
        }
    );

    // Remove vertices that are part of points to be excluded.
    Set<String> pointsToExcludeByName = pointsToExclude.stream()
        .map(point -> point.getName())
        .collect(Collectors.toSet());

    base.vertexSet().stream()
        .filter(vertex -> pointsToExcludeByName.contains(vertex.getPoint().getName()))
        .forEach(vertex -> derivedGraph.removeVertex(vertex));

    return new GraphResult(
        baseGraph.getVehicle(),
        baseGraph.getPointBase(),
        baseGraph.getPathBase(),
        pointsToExclude,
        pathsToExclude,
        derivedGraph
    );
  }
}

