package org.opentcs.strategies.basic.routing.edgeevaluator;

import org.opentcs.data.model.BoundingBox;

/**
 * Checks whether a bounding box protrudes a given bounding box.
 */
public class BoundingBoxProtrusionCheck {

  /**
   * Creates a new instance.
   */
  public BoundingBoxProtrusionCheck() {
  }

  /**
   * Checks whether the given bounding box protrudes the given bounding box.
   *
   * @param inner The bounding box to be checked.
   * @param outer The bounding box to be checked against.
   * @return The protrusion.
   */
  public BoundingBoxProtrusion checkProtrusion(BoundingBox inner, BoundingBox outer) {
    double front = Math.max(
        0,
        inner.getLength() / 2.0 - inner.getReferenceOffset().getX()
            - (outer.getLength() / 2.0 - outer.getReferenceOffset().getX())
    );
    double back = Math.max(
        0,
        inner.getLength() / 2.0 + inner.getReferenceOffset().getX()
            - (outer.getLength() / 2.0 + outer.getReferenceOffset().getX())
    );
    double left = Math.max(
        0,
        inner.getWidth() / 2.0 - inner.getReferenceOffset().getY()
            - (outer.getWidth() / 2.0 - outer.getReferenceOffset().getY())
    );
    double right = Math.max(
        0,
        inner.getWidth() / 2.0 + inner.getReferenceOffset().getY()
            - (outer.getWidth() / 2.0 + outer.getReferenceOffset().getY())
    );
    double top = inner.getHeight() - outer.getHeight();
    return new BoundingBoxProtrusion(front, back, left, right, top);
  }

  /**
   * The protrusion of a bounding box.
   */
  public static class BoundingBoxProtrusion {

    private final double front;
    private final double back;
    private final double left;
    private final double right;
    private final double top;

    /**
     * Creates a new instance.
     *
     * @param front The protrusion in the front.
     * @param back The protrusion in the back.
     * @param left The protrusion on the left.
     * @param right The protrusion on the right.
     * @param top The protrusion on the top.
     */
    public BoundingBoxProtrusion(double front, double back, double left, double right, double top) {
      this.front = Math.max(0, front);
      this.back = Math.max(0, back);
      this.left = Math.max(0, left);
      this.right = Math.max(0, right);
      this.top = Math.max(0, top);
    }

    /**
     * Checks whether the bounding box protrudes in the front.
     *
     * @return Whether the bounding box protrudes in the front.
     */
    public boolean protrudesFront() {
      return front > 0;
    }

    /**
     * Checks whether the bounding box protrudes in the back.
     *
     * @return Whether the bounding box protrudes in the back.
     */
    public boolean protrudesBack() {
      return back > 0;
    }

    /**
     * Checks whether the bounding box protrudes on the left.
     *
     * @return Whether the bounding box protrudes on the left.
     */
    public boolean protrudesLeft() {
      return left > 0;
    }

    /**
     * Checks whether the bounding box protrudes on the right.
     *
     * @return Whether the bounding box protrudes on the right.
     */
    public boolean protrudesRight() {
      return right > 0;
    }

    /**
     * Checks whether the bounding box protrudes on the top.
     *
     * @return Whether the bounding box protrudes on the top.
     */
    public boolean protrudesTop() {
      return top > 0;
    }

    /**
     * Checks whether the bounding box protrudes in any direction.
     *
     * @return Whether the bounding box protrudes in any direction.
     */
    public boolean protrudesAnywhere() {
      return protrudesFront() || protrudesBack() || protrudesLeft() || protrudesRight() || protrudesTop();
    }
  }
}

