package org.opentcs.kernel.workingset;

import static java.util.Objects.requireNonNull;

import jakarta.inject.Inject;
import java.time.Instant;
import java.util.Objects;
import java.util.function.Predicate;
import org.opentcs.customizations.kernel.GlobalSyncObject;
import org.opentcs.data.TCSObjectReference;
import org.opentcs.data.model.EnvironmentalEntity;
import org.opentcs.data.order.OrderSequence;
import org.opentcs.data.order.TransportOrder;
import org.opentcs.data.peripherals.PeripheralJob;
import org.opentcs.kernel.OrderPoolConfiguration;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Periodically cleans up the working set.
 */
public class WorkingSetCleanupTask
    implements
      Runnable {

  /**
   * This class's logger.
   */
  private static final Logger LOG = LoggerFactory.getLogger(WorkingSetCleanupTask.class);
  /**
   * A global object to be used for synchronization within the kernel.
   */
  private final Object globalSyncObject;
  /**
   * Manages transport orders and order sequences.
   */
  private final TransportOrderPoolManager orderPoolManager;
  /**
   * Manages peripheral jobs.
   */
  private final PeripheralJobPoolManager peripheralJobPoolManager;
  /**
   * Manages environmental entities.
   */
  private final PlantModelManager plantModelManager;
  /**
   * Configuration for the order pool.
   */
  private final OrderPoolConfiguration configuration;
  /**
   * Checks whether an order sequence may be removed.
   */
  private final CompositeOrderSequenceCleanupApproval compositeOrderSequenceCleanupApproval;
  /**
   * Checks whether a transport order may be removed.
   */
  private final CompositeTransportOrderCleanupApproval compositeTransportOrderCleanupApproval;
  /**
   * Checks whether a peripheral job may be removed.
   */
  private final CompositePeripheralJobCleanupApproval compositePeripheralJobCleanupApproval;
  /**
   * Keeps track of the creation time threshold.
   */
  private final CreationTimeThreshold creationTimeThreshold;

  /**
   * Creates a new instance.
   *
   * @param globalSyncObject A global object to be used for synchronization within the kernel.
   * @param orderPoolManager Manages transport orders and order sequences.
   * @param peripheralJobPoolManager Manages peripheral jobs.
   * @param plantModelManager Manages environmental entities.
   * @param configuration Configuration for the order pool.
   * @param compositeOrderSequenceCleanupApproval Checks whether an order sequence may be removed.
   * @param compositeTransportOrderCleanupApproval Checks whether a transport order may be removed.
   * @param compositePeripheralJobCleanupApproval Checks whether a peripheral job may be removed.
   * @param creationTimeThreshold Keeps track of the creation time threshold.
   */
  @Inject
  public WorkingSetCleanupTask(
      @GlobalSyncObject
      Object globalSyncObject,
      TransportOrderPoolManager orderPoolManager,
      PeripheralJobPoolManager peripheralJobPoolManager,
      PlantModelManager plantModelManager,
      OrderPoolConfiguration configuration,
      CompositeOrderSequenceCleanupApproval compositeOrderSequenceCleanupApproval,
      CompositeTransportOrderCleanupApproval compositeTransportOrderCleanupApproval,
      CompositePeripheralJobCleanupApproval compositePeripheralJobCleanupApproval,
      CreationTimeThreshold creationTimeThreshold
  ) {
    this.globalSyncObject = requireNonNull(globalSyncObject, "globalSyncObject");
    this.orderPoolManager = requireNonNull(orderPoolManager, "orderPoolManager");
    this.peripheralJobPoolManager = requireNonNull(
        peripheralJobPoolManager,
        "peripheralJobPoolManager"
    );
    this.plantModelManager = requireNonNull(plantModelManager, "plantModelManager");
    this.configuration = requireNonNull(configuration, "configuration");
    this.compositeOrderSequenceCleanupApproval = requireNonNull(
        compositeOrderSequenceCleanupApproval,
        "compositeOrderSequenceCleanupApproval"
    );
    this.compositeTransportOrderCleanupApproval = requireNonNull(
        compositeTransportOrderCleanupApproval,
        "compositeTransportOrderCleanupApproval"
    );
    this.compositePeripheralJobCleanupApproval = requireNonNull(
        compositePeripheralJobCleanupApproval,
        "compositePeripheralJobCleanupApproval"
    );
    this.creationTimeThreshold = requireNonNull(creationTimeThreshold, "creationTimeThreshold");
  }

  /**
   * Returns the sweep interval.
   *
   * @return The sweep interval.
   */
  public long getSweepInterval() {
    return configuration.sweepInterval();
  }

  /**
   * Periodically cleans up the working set.
   */
  @Override
  public void run() {
    synchronized (globalSyncObject) {
      LOG.debug("Sweeping working set...");
      creationTimeThreshold.updateCurrentThreshold(configuration.sweepAge());

      // Clean up peripheral jobs.
      peripheralJobPoolManager.getObjectRepo()
          .getObjects(
              PeripheralJob.class,
              job -> job.getRelatedTransportOrder() == null
                  && compositePeripheralJobCleanupApproval.test(job)
          )
          .forEach(job -> peripheralJobPoolManager.removePeripheralJob(job.getReference()));

      // Clean up transport orders not part of order sequences.
      orderPoolManager.getObjectRepo()
          .getObjects(
              TransportOrder.class,
              transportOrder -> transportOrder.getWrappingSequence() == null
                  && compositeTransportOrderCleanupApproval.test(transportOrder)
          )
          .forEach(
              transportOrder -> {
                removeRelatedPeripheralJobs(transportOrder.getReference());
                orderPoolManager.removeTransportOrder(transportOrder.getReference());
              }
          );

      // Clean up order sequences.
      orderPoolManager.getObjectRepo()
          .getObjects(OrderSequence.class, compositeOrderSequenceCleanupApproval)
          .forEach(
              orderSequence -> {
                orderSequence.getOrders().forEach(orderRef -> removeRelatedPeripheralJobs(orderRef));
                orderPoolManager.removeFinishedOrderSequenceAndOrders(orderSequence.getReference());
              }
          );

      // Clean up environmental entities.
      Instant removalTimeThreshold = Instant.now().minusMillis(configuration.sweepAge());
      plantModelManager.getObjectRepo()
          .streamObjects(EnvironmentalEntity.class)
          .filter(entity -> entity.isRetired())
          .filter(entity -> entity.getRetiredTime().isBefore(removalTimeThreshold))
          .toList()
          .forEach(entity -> plantModelManager.removeEnvironmentalEntity(entity.getReference()));
    }
  }

  private void removeRelatedPeripheralJobs(TCSObjectReference<TransportOrder> transportOrderRef) {
    peripheralJobPoolManager.getObjectRepo()
        .getObjects(
            PeripheralJob.class,
            job -> Objects.equals(job.getRelatedTransportOrder(), transportOrderRef)
        )
        .forEach(job -> peripheralJobPoolManager.removePeripheralJob(job.getReference()));
  }
}

