package org.opentcs.kernel.extensions.controlcenter.vehicles;

import static java.util.Objects.requireNonNull;

import jakarta.annotation.Nonnull;
import jakarta.annotation.Nullable;
import jakarta.inject.Inject;
import java.util.Map;
import java.util.TreeMap;
import org.opentcs.components.Lifecycle;
import org.opentcs.components.kernel.services.TCSObjectService;
import org.opentcs.data.model.Vehicle;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Maintains a pool of {@link VehicleEntry}s for all vehicles in the kernel.
 */
public class VehicleEntryPool
    implements
      Lifecycle {

  /**
   * This class's logger.
   */
  private static final Logger LOG = LoggerFactory.getLogger(VehicleEntryPool.class);
  /**
   * The object service.
   */
  private final TCSObjectService objectService;
  /**
   * The vehicle entries.
   */
  private final Map<String, VehicleEntry> entries = new TreeMap<>();
  /**
   * Whether this component is initialized or not.
   */
  private boolean initialized;

  @Inject
  public VehicleEntryPool(
      @Nonnull
      TCSObjectService objectService
  ) {
    this.objectService = requireNonNull(objectService, "objectService");
  }

  @Override
  public void initialize() {
    if (isInitialized()) {
      LOG.debug("Already initialized.");
      return;
    }

    for (Vehicle vehicle : objectService.fetch(Vehicle.class)) {
      entries.put(vehicle.getName(), new VehicleEntry(vehicle));
    }

    LOG.debug("Initialized vehicle entry pool: {}", entries);
    initialized = true;
  }

  @Override
  public boolean isInitialized() {
    return initialized;
  }

  @Override
  public void terminate() {
    if (!isInitialized()) {
      LOG.debug("Not initialized.");
      return;
    }

    entries.clear();
    initialized = false;
  }

  @Nonnull
  public Map<String, VehicleEntry> getEntries() {
    return entries;
  }

  @Nullable
  public VehicleEntry getEntryFor(
      @Nonnull
      String vehicleName
  ) {
    requireNonNull(vehicleName, "vehicleName");
    return entries.get(vehicleName);
  }
}

