package org.opentcs.kernel.extensions.servicewebapi.common;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.SerializationFeature;
import com.fasterxml.jackson.datatype.jsr310.JavaTimeModule;
import java.io.IOException;

/**
 * Provides methods to serialize/deserialize JSON.
 */
public class JsonBinder {

  private final ObjectMapper objectMapper = new ObjectMapper()
      .registerModule(new JavaTimeModule())
      .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);

  /**
   * Creates a new instance.
   */
  public JsonBinder() {
  }

  /**
   * Deserializes the given JSON string to the given class.
   *
   * @param jsonString The JSON string to be deserialized.
   * @param clazz The class to be deserialized to.
   * @param <T> The class to be deserialized to.
   * @return The deserialized object.
   * @throws IllegalArgumentException If the given JSON string could not be parsed.
   */
  public <T> T fromJson(String jsonString, Class<T> clazz)
      throws IllegalArgumentException {
    try {
      return objectMapper.readValue(jsonString, clazz);
    }
    catch (IOException e) {
      throw new IllegalArgumentException("Could not parse JSON input", e);
    }
  }

  /**
   * Serializes the given object to a JSON string.
   *
   * @param object The object to be serialized.
   * @return The serialized object.
   * @throws IllegalStateException If the given object could not be serialized.
   */
  public String toJson(Object object)
      throws IllegalStateException {
    try {
      return objectMapper.writerWithDefaultPrettyPrinter().writeValueAsString(object);
    }
    catch (JsonProcessingException e) {
      throw new IllegalStateException("Could not produce JSON output", e);
    }
  }

  /**
   * Serializes the given Throwable to a JSON string.
   *
   * @param t The Throwable to be serialized.
   * @return The serialized Throwable.
   * @throws IllegalStateException If the given Throwable could not be serialized.
   */
  public String toJson(Throwable t)
      throws IllegalStateException {
    try {
      return objectMapper.writerWithDefaultPrettyPrinter()
          .writeValueAsString(objectMapper.createArrayNode().add(t.getMessage()));
    }
    catch (JsonProcessingException e) {
      throw new IllegalStateException("Could not produce JSON output", e);
    }
  }
}

