     */
    ACTIVE,
    /**
     * The order's state is dispatchable.
     */
    DISPATCHABLE,
    /**
     * The order's state is being processed.
     */
    BEING_PROCESSED,
    /**
     * The order's state is withdrawn.
     */
    WITHDRAWN,
    /**
     * The order's state is finished.
     */
    FINISHED,
    /**
     * The order's state is failed.
     */
    FAILED,
    /**
     * The order's state is unroutable.
     */
    UNROUTABLE;

    /**
     * Returns the corresponding order state for a transport order state.
     *
     * @param state The transport order state.
     * @return The corresponding order state.
     */
    public static OrderState fromTransportOrderState(TransportOrder.State state) {
      return switch (state) {
        case RAW -> RAW;
        case ACTIVE -> ACTIVE;
        case DISPATCHABLE -> DISPATCHABLE;
        case BEING_PROCESSED -> BEING_PROCESSED;
        case WITHDRAWN -> WITHDRAWN;
        case FINISHED -> FINISHED;
        case FAILED -> FAILED;
        case UNROUTABLE -> UNROUTABLE;
      };
    }
  }
}

