package org.opentcs.strategies.basic.scheduling.modules;

import static java.util.Objects.requireNonNull;

import jakarta.annotation.Nonnull;
import jakarta.inject.Inject;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import java.util.stream.Collectors;
import org.opentcs.components.kernel.Scheduler;
import org.opentcs.components.kernel.services.InternalPlantModelService;
import org.opentcs.customizations.kernel.GlobalSyncObject;
import org.opentcs.data.model.Block;
import org.opentcs.data.model.TCSResource;
import org.opentcs.data.model.TCSResourceReference;
import org.opentcs.strategies.basic.scheduling.ReservationPool;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Allows allocations only if the requested resources are not in blocks of type
 * {@link Block.Type#SINGLE_VEHICLE_ONLY}.
 */
public class SingleVehicleBlockModule
    implements
      Scheduler.Module {

  /**
   * This class's logger.
   */
  private static final Logger LOG = LoggerFactory.getLogger(SingleVehicleBlockModule.class);
  /**
   * The reservation pool.
   */
  private final ReservationPool reservationPool;
  /**
   * The plant model service.
   */
  private final InternalPlantModelService plantModelService;
  /**
   * A global object to be used for synchronization within the kernel.
   */
  private final Object globalSyncObject;
  /**
   * Whether this module is initialized.
   */
  private boolean initialized;

  /**
   * Creates a new instance.
   *
   * @param reservationPool The reservation pool.
   * @param plantModelService The plant model service.
   * @param globalSyncObject A global object to be used for synchronization within the kernel.
   */
  @Inject
  public SingleVehicleBlockModule(
      @Nonnull
      ReservationPool reservationPool,
      @Nonnull
      InternalPlantModelService plantModelService,
      @Nonnull
      @GlobalSyncObject
      Object globalSyncObject
  ) {
    this.reservationPool = requireNonNull(reservationPool, "reservationPool");
    this.plantModelService = requireNonNull(plantModelService, "plantModelService");
    this.globalSyncObject = requireNonNull(globalSyncObject, "globalSyncObject");
  }

  @Override
  public void initialize() {
    if (isInitialized()) {
      return;
    }

    initialized = true;
  }

  @Override
  public boolean isInitialized() {
    return initialized;
  }

  @Override
  public void terminate() {
    if (!isInitialized()) {
      return;
    }

    initialized = false;
  }

  @Override
  public void setAllocationState(
      Scheduler.Client client,
      Set<TCSResource<?>> alloc,
      List<Set<TCSResource<?>>> remainingClaim
  ) {
    // Do nothing.
  }

  @Override
  public boolean mayAllocate(
      Scheduler.Client client,
      Set<TCSResource<?>> resources
  ) {
    requireNonNull(client, "client");
    requireNonNull(resources, "resources");

    synchronized (globalSyncObject) {
      Set<Block> blocks = filterBlocksContainingResources(resources, Block.Type.SINGLE_VEHICLE_ONLY);
      if (blocks.isEmpty()) {
        LOG.debug("{}: No blocks containing the requested resources, allowing allocation.", client.getId());
        return true;
      }

      Set<TCSResource<?>> resourcesExpanded = expandResources(resources);
      Set<TCSResource<?>> relevantResources = filterRelevantResources(resourcesExpanded, blocks);
      LOG.debug(
          "{}: Checking whether the requested resources are available for allocation: {}",
          client.getId(),
          relevantResources
      );
      if (!reservationPool.resourcesAvailableForUser(relevantResources, client)) {
        LOG.debug("{}: Resources not available, denying allocation.", client.getId());
        return false;
      }

      LOG.debug("{}: Resources available, allowing allocation.", client.getId());
      return true;
    }
  }

  @Override
  public void prepareAllocation(
      Scheduler.Client client,
      Set<TCSResource<?>> resources
  ) {
    // Do nothing.
  }

  @Override
  public boolean hasPreparedAllocation(
      Scheduler.Client client,
      Set<TCSResource<?>> resources
  ) {
    return true;
  }

  @Override
  public void allocationReleased(
      Scheduler.Client client,
      Set<TCSResource<?>> resources
  ) {
    // Do nothing.
  }

  private Set<Block> filterBlocksContainingResources(
      Set<TCSResource<?>> resources,
      Block.Type type
  ) {
    Set<Block> blocks = new HashSet<>();
    for (Block block : plantModelService.fetch(Block.class, block -> block.getType() == type)) {
      for (TCSResourceReference<?> ref : block.getMembers()) {
        if (resources.contains(ref.getResource())) {
          blocks.add(block);
          break;
        }
      }
    }
    return blocks;
  }

  private Set<TCSResource<?>> filterRelevantResources(
      Set<TCSResource<?>> resources,
      Set<Block> blocks
  ) {
    Set<TCSResourceReference<?>> refs = blocks.stream()
        .flatMap(block -> block.getMembers().stream())
        .collect(Collectors.toSet());
    return resources.stream()
        .filter(resource -> refs.contains(resource.getReference()))
        .collect(Collectors.toSet());
  }

  private Set<TCSResource<?>> expandResources(Set<TCSResource<?>> resources) {
    requireNonNull(resources, "resources");

    Set<TCSResourceReference<?>> refs = resources.stream()
        .map(resource -> resource.getReference())
        .collect(Collectors.toSet());
    Set<TCSResource<?>> resourcesExpanded = plantModelService.expandResources(refs);
    LOG.debug(
        "Expanded resources from {} to {}.",
        resources,
        resourcesExpanded
    );
    return resourcesExpanded;
  }
}

