package org.opentcs.strategies.basic.scheduling.modules.areaAllocation;

import static java.util.Objects.requireNonNull;
import static org.opentcs.strategies.basic.util.CustomGeometryFactory.EMPTY_GEOMETRY;

import jakarta.annotation.Nonnull;
import jakarta.inject.Inject;
import java.util.HashMap;
import java.util.Map;
import java.util.Objects;
import java.util.Optional;
import java.util.Set;
import java.util.stream.Collectors;
import org.locationtech.jts.geom.Geometry;
import org.opentcs.components.kernel.services.InternalTCSObjectService;
import org.opentcs.data.model.Envelope;
import org.opentcs.data.model.Path;
import org.opentcs.data.model.Point;
import org.opentcs.data.model.TCSResource;
import org.opentcs.strategies.basic.util.CustomGeometryFactory;
import org.opentcs.strategies.basic.util.MultiPlaneGeometryCollection;

/**
 * Provides areas for vehicle occupations and resource conflicts.
 */
public class CachingAreaProvider
    implements
      AreaProvider {

  /**
   * The object service.
   */
  private final InternalTCSObjectService objectService;
  /**
   * A factory for various JTS specific methods.
   */
  private final CustomGeometryFactory geometryFactory;
  /**
   * A cache for areas.
   */
  private final Map<CacheKey, Geometry> cache;
  /**
   * A cache for points.
   */
  private final Map<String, Point> points;
  /**
   * Whether this component is initialized or not.
   */
  private boolean initialized;

  @Inject
  public CachingAreaProvider(InternalTCSObjectService objectService) {
    this.objectService = requireNonNull(objectService, "objectService");
    geometryFactory = new CustomGeometryFactory();
    cache = new HashMap<>();
    points = new HashMap<>();
    initialized = false;
  }

  @Override
  public void initialize() {
    if (isInitialized()) {
      return;
    }

    objectService.stream(Point.class)
        .forEach(point -> points.put(point.getName(), point));
    populateCache();

    initialized = true;
  }

  @Override
  public boolean isInitialized() {
    return initialized;
  }

  @Override
  public void terminate() {
    if (!isInitialized()) {
      return;
    }

    cache.clear();
    points.clear();
    initialized = false;
  }

  @Override
  public MultiPlaneGeometryCollection getAreas(
      @Nonnull
      String envelopeKey,
      @Nonnull
      Set<TCSResource<?>> resources
  ) {
    requireNonNull(envelopeKey, "envelopeKey");
    requireNonNull(resources, "resources");

    Map<Long, Geometry> areasByPlane = resources.stream()
        .flatMap(resource -> toPlaneGeometries(envelopeKey, resource).stream())
        .collect(Collectors.groupingBy(PlaneGeometry::plane, Collectors.mapping(PlaneGeometry::geometry, Collectors.toList())))
        .entrySet()
        .stream()
        .collect(Collectors.toMap(
            Map.Entry::getKey,
            entry -> geometryFactory.createGeometryCollection(entry.getValue().toArray(Geometry[]::new))
        ));

    return new MultiPlaneGeometryCollection(areasByPlane);
  }

  private void populateCache() {
    objectService.fetch(Point.class, point -> !point.getVehicleEnvelopes().isEmpty())
        .forEach(point -> {
          point.getVehicleEnvelopes().entrySet().forEach(entry -> {
            Optional<Geometry> area = computeArea(entry.getKey(), point);
            if (area.isPresent()) {
              cache.put(new CacheKey(entry.getKey(), point), area.get());
            }
          });
        });

    objectService.fetch(Path.class, path -> !path.getVehicleEnvelopes().isEmpty())
        .forEach(path -> {
          path.getVehicleEnvelopes().entrySet().forEach(entry -> {
            Optional<Geometry> area = computeArea(entry.getKey(), path);
            if (area.isPresent()) {
              cache.put(new CacheKey(entry.getKey(), path), area.get());
            }
          });
        });
  }

  private Optional<Geometry> computeArea(String envelopeKey, TCSResource<?> resource) {
    Map<String, Envelope> vehicleEnvelopes = extractVehicleEnvelopes(resource);
    if (!vehicleEnvelopes.containsKey(envelopeKey)) {
      return Optional.empty();
    }

    return Optional.of(geometryFactory.createPolygonOrEmptyGeometry(vehicleEnvelopes.get(envelopeKey)));
  }

  private Map<String, Envelope> extractVehicleEnvelopes(TCSResource<?> resource) {
    if (resource instanceof Point point) {
      return point.getVehicleEnvelopes();
    }
    if (resource instanceof Path path) {
      return path.getVehicleEnvelopes();
    }
    return Map.of();
  }

  private Set<PlaneGeometry> toPlaneGeometries(String envelopeKey, TCSResource<?> resource) {
    if (resource instanceof Point point) {
      Geometry area = lookupArea(envelopeKey, point);
      if (area == EMPTY_GEOMETRY) {
        return Set.of();
      }
      return Set.of(new PlaneGeometry(point.getPose().getPosition().getZ(), area));
    }
    if (resource instanceof Path path) {
      Geometry area = lookupArea(envelopeKey, path);
      if (area == EMPTY_GEOMETRY) {
        return Set.of();
      }
      Point sourcePoint = points.get(path.getSourcePoint().getName());
      Point destinationPoint = points.get(path.getDestinationPoint().getName());
      long sourcePlane = sourcePoint.getPose().getPosition().getZ();
      long destinationPlane = destinationPoint.getPose().getPosition().getZ();
      if (sourcePlane == destinationPlane) {
        return Set.of(new PlaneGeometry(sourcePlane, area));
      }
      return Set.of(
          new PlaneGeometry(sourcePlane, area),
          new PlaneGeometry(destinationPlane, area)
      );
    }
    return Set.of();
  }

  private Geometry lookupArea(String envelopeKey, TCSResource<?> resource) {
    return cache.getOrDefault(
        new CacheKey(envelopeKey, resource),
        EMPTY_GEOMETRY
    );
  }

  private static class CacheKey {
    private final String envelopeKey;
    private final TCSResource<?> resource;

    CacheKey(String envelopeKey, TCSResource<?> resource) {
      this.envelopeKey = requireNonNull(envelopeKey, "envelopeKey");
      this.resource = requireNonNull(resource, "resource");
    }

    @Override
    public int hashCode() {
      int hash = 7;
      hash = 37 * hash + Objects.hashCode(envelopeKey);
      hash = 37 * hash + Objects.hashCode(resource);
      return hash;
    }

    @Override
    public boolean equals(Object obj) {
      if (this == obj) {
        return true;
      }
      if (!(obj instanceof CacheKey)) {
        return false;
      }
      CacheKey other = (CacheKey) obj;
      return Objects.equals(envelopeKey, other.envelopeKey)
          && Objects.equals(resource, other.resource);
    }
  }

  private record PlaneGeometry(long plane, Geometry geometry) {

    @Override
    public int hashCode() {
      int hash = 7;
      hash = 37 * hash + Objects.hashCode(plane);
      hash = 37 * hash + Objects.hashCode(geometry);
      return hash;
    }

    @Override
    public boolean equals(Object obj) {
      if (this == obj) {
        return true;
      }
      if (!(obj instanceof PlaneGeometry)) {
        return false;
      }
      PlaneGeometry other = (PlaneGeometry) obj;
      return plane == other.plane && Objects.equals(geometry, other.geometry);
    }
  }
}

