package org.opentcs.kernel.extensions.watchdog;

import static java.util.Objects.requireNonNull;

import jakarta.inject.Inject;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import org.opentcs.components.Lifecycle;
import org.opentcs.components.kernel.services.NotificationService;
import org.opentcs.customizations.kernel.KernelExecutor;
import org.opentcs.data.notification.UserNotification;
import org.opentcs.data.order.TransportOrder;

/**
 * Checks for transport orders that are idle or have expired.
 */
public class TransportOrderCheck
    implements
      Runnable,
      Lifecycle {

  /**
   * The source of notifications.
   */
  private static final String NOTIFICATION_SOURCE = "Watchdog - Transport order check";
  /**
   * A formatter for timestamps in notifications.
   */
  private static final DateTimeFormatter TIMESTAMP_FORMATTER = DateTimeFormatter.ofPattern(
      "yyyy-MM-dd HH:mm:ss"
  ).withZone(ZoneId.systemDefault());
  /**
   * The notification service.
   */
  private final NotificationService notificationService;
  /**
   * The kernel executor.
   */
  private final ScheduledExecutorService kernelExecutor;
  /**
   * The watchdog configuration.
   */
  private final WatchdogConfiguration configuration;
  /**
   * Keeps track of idle and expired transport orders.
   */
  private final IdleAndExpiredTransportOrders idleAndExpiredTransportOrders;
  /**
   * Whether this component is initialized.
   */
  private boolean initialized;
  /**
   * The scheduled future for the periodic check.
   */
  private ScheduledFuture<?> scheduledFuture;

  /**
   * Creates a new instance.
   *
   * @param kernelExecutor The kernel executor.
   * @param notificationService The notification service.
   * @param configuration The watchdog configuration.
   * @param idleAndExpiredTransportOrders Keeps track of idle and expired transport orders.
   */
  @Inject
  public TransportOrderCheck(
      @KernelExecutor
      ScheduledExecutorService kernelExecutor,
      NotificationService notificationService,
      WatchdogConfiguration configuration,
      IdleAndExpiredTransportOrders idleAndExpiredTransportOrders
  ) {
    this.kernelExecutor = requireNonNull(kernelExecutor, "kernelExecutor");
    this.notificationService = requireNonNull(notificationService, "notificationService");
    this.configuration = requireNonNull(configuration, "configuration");
    this.idleAndExpiredTransportOrders = requireNonNull(
        idleAndExpiredTransportOrders,
        "idleAndExpiredTransportOrders"
    );
  }

  @Override
  public void initialize() {
    if (isInitialized()) {
      return;
    }

    idleAndExpiredTransportOrders.initialize();
    scheduledFuture = kernelExecutor.scheduleAtFixedRate(this, configuration.transportOrderCheckInterval(), configuration.transportOrderCheckInterval(), TimeUnit.MILLISECONDS);
    initialized = true;
  }

  @Override
  public boolean isInitialized() {
    return initialized;
  }

  @Override
  public void terminate() {
    if (!isInitialized()) {
      return;
    }

    if (scheduledFuture != null) {
      scheduledFuture.cancel(true);
      scheduledFuture = null;
    }

    idleAndExpiredTransportOrders.terminate();
    initialized = false;
  }

  @Override
  public void run() {
    long currentTime = System.currentTimeMillis();
    long idleTimeThreshold = configuration.idleTransportOrderDurationThreshold();
    idleAndExpiredTransportOrders.identifyIdleOrExpiredTransportOrders(currentTime, idleTimeThreshold);

    Set<IdleAndExpiredTransportOrders.TransportOrderSnapshot> newlyIdleTransportOrders
        = idleAndExpiredTransportOrders.newlyIdleTransportOrders();
    Set<IdleAndExpiredTransportOrders.TransportOrderSnapshot> newlyExpiredTransportOrders
        = idleAndExpiredTransportOrders.newlyExpiredTransportOrders();
    Set<TransportOrder> newlyTransportOrdersInFinalState
        = idleAndExpiredTransportOrders.newTransportOrdersInFinalState();

    for (IdleAndExpiredTransportOrders.TransportOrderSnapshot transportOrderSnapshot
        : newlyIdleTransportOrders) {
      TransportOrder transportOrder = transportOrderSnapshot.getTransportOrder();
      String transportOrderName = transportOrder.getName();
      Instant idleStart = Instant.ofEpochMilli(transportOrderSnapshot.getLastRelevantStateChange());
      String idleStartText = TIMESTAMP_FORMATTER.format(idleStart);
      notificationService.publishUserNotification(
          new UserNotification(
              NOTIFICATION_SOURCE,
              String.format(
                  "Transport order '%s' is waiting to be processed and idle since: %s",
                  transportOrderName,
                  idleStartText
              ),
              UserNotification.Level.INFORMATIONAL
          )
      );
    }

    for (IdleAndExpiredTransportOrders.TransportOrderSnapshot transportOrderSnapshot
        : newlyExpiredTransportOrders) {
      TransportOrder transportOrder = transportOrderSnapshot.getTransportOrder();
      Instant deadline = transportOrder.getDeadline();
      String deadlineText = TIMESTAMP_FORMATTER.format(deadline);
      String transportOrderName = transportOrder.getName();
      notificationService.publishUserNotification(
          new UserNotification(
              NOTIFICATION_SOURCE,
              String.format(
                  "The deadline ('%s') for transport order '%s' has expired.",
                  deadlineText,
                  transportOrderName
              ),
              UserNotification.Level.INFORMATIONAL
          )
      );
    }

    for (TransportOrder transportOrder : newlyTransportOrdersInFinalState) {
      String transportOrderName = transportOrder.getName();
      notificationService.publishUserNotification(
          new UserNotification(
              NOTIFICATION_SOURCE,
              String.format(
                  "Transport order '%s' has reached a final state.",
                  transportOrderName
              ),
              UserNotification.Level.INFORMATIONAL
          )
      );
    }
  }
}

