package org.opentcs.kernel.extensions.watchdog;

import static java.util.Objects.requireNonNull;

import jakarta.inject.Inject;
import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.Set;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledFuture;
import java.util.concurrent.TimeUnit;
import org.opentcs.components.Lifecycle;
import org.opentcs.components.kernel.services.NotificationService;
import org.opentcs.customizations.kernel.KernelExecutor;
import org.opentcs.data.notification.UserNotification;
import org.opentcs.kernel.extensions.watchdog.StrandedVehicles.VehicleSnapshot;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

/**
 * Periodically checks whether any vehicles are stranded and publishes a notification for each
 * newly stranded vehicle.
 */
public class StrandedVehicleCheck
    implements
      Runnable,
      Lifecycle {

  /**
   * This class's logger.
   */
  private static final Logger LOG = LoggerFactory.getLogger(StrandedVehicleCheck.class);
  /**
   * The notification source.
   */
  private static final String NOTIFICATION_SOURCE = "Watchdog - Stranded vehicle check";
  /**
   * A formatter for formatting timestamps in notifications.
   */
  private static final DateTimeFormatter TIMESTAMP_FORMATTER = DateTimeFormatter.ofPattern(
      "yyyy-MM-dd HH:mm:ss"
  ).withZone(ZoneId.systemDefault());
  /**
   * The notification service.
   */
  private final NotificationService notificationService;
  /**
   * The kernel executor.
   */
  private final ScheduledExecutorService kernelExecutor;
  /**
   * The watchdog configuration.
   */
  private final WatchdogConfiguration configuration;
  /**
   * Keeps track of stranded vehicles.
   */
  private final StrandedVehicles stranded;
  /**
   * Whether this component is initialized.
   */
  private boolean initialized;
  /**
   * The scheduled future for the periodic check.
   */
  private ScheduledFuture<?> scheduledFuture;

  /**
   * Creates a new instance.
   *
   * @param kernelExecutor The kernel executor.
   * @param notificationService The notification service.
   * @param configuration The watchdog configuration.
   * @param stranded Keeps track of stranded vehicles.
   */
  @Inject
  public StrandedVehicleCheck(
      @KernelExecutor
      ScheduledExecutorService kernelExecutor,
      NotificationService notificationService,
      WatchdogConfiguration configuration,
      StrandedVehicles stranded
  ) {
    this.kernelExecutor = requireNonNull(kernelExecutor, "kernelExecutor");
    this.notificationService = requireNonNull(notificationService, "notificationService");
    this.configuration = requireNonNull(configuration, "configuration");
    this.stranded = requireNonNull(stranded, "stranded");
  }

  @Override
  public void initialize() {
    if (isInitialized()) {
      return;
    }

    scheduledFuture = kernelExecutor.scheduleAtFixedRate(this, configuration.strandedVehicleCheckInterval(), configuration.strandedVehicleCheckInterval(), TimeUnit.MILLISECONDS);
    stranded.initialize();
    initialized = true;
  }

  @Override
  public boolean isInitialized() {
    return initialized;
  }

  @Override
  public void terminate() {
    if (!isInitialized()) {
      return;
    }

    if (scheduledFuture != null) {
      scheduledFuture.cancel(true);
      scheduledFuture = null;
    }

    stranded.terminate();
    initialized = false;
  }

  @Override
  public void run() {
    long currentTime = System.currentTimeMillis();
    long strandedTimeThreshold = configuration.strandedVehicleDurationThreshold();

    stranded.identifyStrandedVehicles(currentTime, strandedTimeThreshold);

    Set<VehicleSnapshot> newlyStrandedVehicles = stranded.newlyStrandedVehicles();
    Set<VehicleSnapshot> noLongerStrandedVehicles = stranded.noLongerStrandedVehicles();

    for (VehicleSnapshot vehicleSnapshot : newlyStrandedVehicles) {
      String vehicleName = vehicleSnapshot.getVehicle().getName();
      Instant timestamp = Instant.ofEpochMilli(vehicleSnapshot.getLastRelevantStateChange());
      String message = String.format(
          "Vehicle '%s' is stranded since: %s",
          vehicleName,
          TIMESTAMP_FORMATTER.format(timestamp)
      );

      notificationService.publishUserNotification(
          new UserNotification(
              NOTIFICATION_SOURCE,
              message,
              UserNotification.Level.INFORMATIONAL
          )
      );
    }

    for (VehicleSnapshot vehicleSnapshot : noLongerStrandedVehicles) {
      String vehicleName = vehicleSnapshot.getVehicle().getName();
      String message = String.format("Vehicle '%s' is no longer stranded.", vehicleName);

      notificationService.publishUserNotification(
          new UserNotification(
              NOTIFICATION_SOURCE,
              message,
              UserNotification.Level.INFORMATIONAL
          )
      );
    }
  }
}

