  @JsonCreator
  public PropertyTO(
      @Nonnull
      @JsonProperty(value = "name", required = true)
      String name,
      @Nonnull
      @JsonProperty(value = "value", required = true)
      String value
  ) {
    this.name = requireNonNull(name, "name");
    this.value = requireNonNull(value, "value");
  }

  @Nonnull
  public String getName() {
    return name;
  }

  public PropertyTO setName(
      @Nonnull
