    /**
     * 根据 IP 地址，获得地区编号
     *
     * @param ip IP 地址
     * @return 地区编号
     */
    @SneakyThrows
    public static Integer getAreaId(String ip) {
        return Integer.parseInt(SEARCHER.search(ip.trim()));
    }

    /**
     * 根据 IP 地址，获得地区编号
     *
     * @param ip IP 地址
     * @return 地区编号
