     *
     * @param ip IP 地址
     * @return 地区对象
     */
    public static Area getArea(String ip) {
        return AreaUtils.getArea(getAreaId(ip));
    }

    /**
     * 根据 IP 地址，获得地区对象
     *
     * @param ip IP 地址
     * @return 地区对象
     */
    public static Area getArea(long ip) {
        return AreaUtils.getArea(getAreaId(ip));
    }

}

