/**
 * Used to perform limited integrity checks on the results of a
 * {@link ContourBuilderForTin} instance.
 * <p>
 * This class is intended for testing, diagnostic and debugging purposes
 * only. It is not intended to be used to determine if the results of
 * a {@link ContourBuilderForTin} are correct in all respects.
 */

package org.tinfour.contour;

import java.util.List;
import org.tinfour.contour.Contour.ContourType;
import org.tinfour.contour.ContourRegion.ContourRegionType;

/**
 * Used to perform limited integrity checks on the results of a
 * {@link ContourBuilderForTin} instance.
 * <p>
 * This class is intended for testing, diagnostic and debugging purposes
 * only. It is not intended to be used to determine if the results of
 * a {@link ContourBuilderForTin} are correct in all respects.
 */
public class ContourIntegrityCheck {

    private final ContourBuilderForTin builder;
    String message;

    /**
     * Construct a new instance.
     *
     * @param builder the {@link ContourBuilderForTin} to be checked
     */
    public ContourIntegrityCheck(ContourBuilderForTin builder) {
        if (builder == null) {
            throw new IllegalArgumentException("A null reference for the builder is not supported");
        }
        this.builder = builder;
    }

    /**
     * Perform the integrity checks.
     *
     * @return true if the checks pass, otherwise false
     */
    public boolean inspect() {
        List<ContourRegion> regions = builder.getRegions();
        if (!regions.isEmpty()) {
            if (!checkRegionAreas(regions)) {
                return false;
            }
            if (!checkContourTraversal(regions)) {
                return false;
            }
        } else {
            message = "Inspection passed";
        }
        return true;
    }

    /**
     * Return a message with the results of the last inspection.
     *
     * @return a message with the results of the last inspection
     */
    public String getMessage() {
        return message;
    }

    private boolean checkRegionAreas(List<ContourRegion> regions) {
        double[] xy = builder.getEnvelope();
        double xOffset = xy[0];
        double yOffset = xy[1];
        double envelopeArea = 0.0;
        for (int i = 2; i < xy.length; i += 2) {
            double x0 = xy[i] - xOffset;
            double y0 = xy[i + 1] - yOffset;
            double x1 = xy[i + 2] - xOffset;
            double y1 = xy[i + 3] - yOffset;
            envelopeArea += x0 * y1 - x1 * y0;
            x0 = x1;
            y0 = y1;
        }
        envelopeArea /= 2.0;
        double aSum = 0.0;
        double adjustedSum = 0.0;
        for (ContourRegion region : regions) {
            if (region.getContourRegionType() == ContourRegionType.Perimeter) {
                aSum += region.getArea();
            }
            adjustedSum += region.getAdjustedArea();
        }
        if (Math.abs(aSum - envelopeArea) > envelopeArea * 1.0e-6) {
            message = "The area of the primary contour regions does not match the area of the enclosing envelope";
            return false;

