   * Creates a peripheral job.
   *
   * @param to Describes the peripheral job to be created.
   * @return The newly created peripheral job.
   * @throws ObjectUnknownException If any referenced object does not exist.
   * @throws ObjectExistsException If an object with the same name already exists in the model.
   * @throws IllegalArgumentException If the given transfer object violates any business rule.
   */
  public PeripheralJob createPeripheralJob(PeripheralJobCreationTO to)
      throws ObjectUnknownException,
        ObjectExistsException,
        IllegalArgumentException {
    checkArgument(
        !hasCompletionRequiredAndExecutionTriggerImmediate(to),
        "Peripheral job operations with immediate execution trigger and completion required are "
            + "not allowed."
    );

    String name = nameFor(to);
    PeripheralOperation peripheralOperation = toPeripheralOperation(to.getPeripheralOperation());
    PeripheralJob job = new PeripheralJob(
        name,
        to.getReservationToken(),
        peripheralOperation
    );
    job = job.withRelatedVehicle(toVehicleReference(to.getRelatedVehicleName()))
        .withRelatedTransportOrder(toTransportOrderReference(to.getRelatedTransportOrderName()))
        .withProperties(to.getProperties());

    LOG.info(
        "Creating peripheral job '{}' with peripheral operation '{}'",
        job.getName(),
        job.getPeripheralOperation().getName()
    );
    getObjectRepo().addObject(job);
    emitObjectEvent(job, null, TCSObjectEvent.Type.OBJECT_CREATED);
    return job;
  }

  /**
   * Sets a peripheral job's state.
   *
   * @param ref A reference to the peripheral job to be modified.
   * @param newState The peripheral job's new state.
   * @return The modified peripheral job.
   * @throws ObjectUnknownException If the referenced peripheral job does not exist.
   */
  public PeripheralJob setPeripheralJobState(
      TCSObjectReference<PeripheralJob> ref,
      PeripheralJob.State newState
  )
      throws ObjectUnknownException {
    PeripheralJob job = getObjectRepo().getObject(PeripheralJob.class, ref);
    if (job.getState().isFinalState()) {
      checkArgument(
          false,
          "Peripheral job '%s' is in state '%s' and cannot be modified",
          job.getName(),
          job.getState()
      );
    }

    LOG.info(
        "Setting peripheral job '{}' state from '{}' to '{}'",
        job.getName(),
        job.getState(),
        newState
    );
    PeripheralJob previousState = job;
    job = job.withState(newState);
    getObjectRepo().replaceObject(job);
    emitObjectEvent(job, previousState, TCSObjectEvent.Type.OBJECT_MODIFIED);
    return job;
  }

  /**
   * Removes a peripheral job.
   *
   * @param ref A reference to the peripheral job to be removed.
   * @return The removed peripheral job.
   * @throws ObjectUnknownException If the referenced peripheral job does not exist.
   */
  public PeripheralJob removePeripheralJob(TCSObjectReference<PeripheralJob> ref)
      throws ObjectUnknownException {
    PeripheralJob job = getObjectRepo().getObject(PeripheralJob.class, ref);
    if (!job.getState().isFinalState()) {
      checkArgument(
          false,
          "Peripheral job '%s' is in state '%s' and cannot be removed",
          job.getName(),
          job.getState()
      );
    }

    getObjectRepo().removeObject(ref);
    emitObjectEvent(null, job, TCSObjectEvent.Type.OBJECT_REMOVED);
    return job;
  }

  private PeripheralOperation toPeripheralOperation(PeripheralOperationCreationTO to)
      throws ObjectUnknownException {
    TCSResourceReference<Location> location = toLocationReference(to.getLocationName());
    return new PeripheralOperation(
        to.getName(),
        location,
        toExecutionTrigger(to.getExecutionTrigger()),
        to.isCompletionRequired()
    );
  }

  private TCSResourceReference<Location> toLocationReference(String locationName)
      throws ObjectUnknownException {
    Location location = getObjectRepo().getObject(Location.class, locationName);
    return location.getReference();
  }

  private TCSObjectReference<Vehicle> toVehicleReference(String vehicleName)
      throws ObjectUnknownException {
    if (vehicleName == null) {
      return null;
    }
    Vehicle vehicle = getObjectRepo().getObject(Vehicle.class, vehicleName);
    return vehicle.getReference();
  }

  private TCSObjectReference<TransportOrder> toTransportOrderReference(String transportOrderName)
      throws ObjectUnknownException {
    if (transportOrderName == null) {
      return null;
    }
    TransportOrder transportOrder = getObjectRepo().getObject(TransportOrder.class, transportOrderName);
    return transportOrder.getReference();
  }

  @Nonnull
  private String nameFor(
      @Nonnull
      PeripheralJobCreationTO to
  ) {
    if (to.hasIncompleteName()) {
      return objectNameProvider.apply(to);
    }
    return to.getName();
  }

  private boolean hasCompletionRequiredAndExecutionTriggerImmediate(
      PeripheralJobCreationTO to
  ) {
    return to.getPeripheralOperation().isCompletionRequired()
        && to.getPeripheralOperation().getExecutionTrigger() == PeripheralOperationCreationTO.ExecutionTrigger.IMMEDIATE;
  }

  private PeripheralOperation.ExecutionTrigger toExecutionTrigger(
      PeripheralOperationCreationTO.ExecutionTrigger executionTrigger
  ) {
    return switch (executionTrigger) {
      case AFTER_ALLOCATION -> PeripheralOperation.ExecutionTrigger.AFTER_ALLOCATION;
      case AFTER_MOVEMENT -> PeripheralOperation.ExecutionTrigger.AFTER_MOVEMENT;
      case IMMEDIATE -> PeripheralOperation.ExecutionTrigger.IMMEDIATE;
    };
  }
}

