package org.opentcs.strategies.basic.dispatching.phase.assignment;

import static java.util.Objects.requireNonNull;
import static org.opentcs.data.order.TransportOrderHistoryCodes.ORDER_ASSIGNED_TO_VEHICLE;
import static org.opentcs.data.order.TransportOrderHistoryCodes.ORDER_DISPATCHING_DEFERRED;
import static org.opentcs.data.order.TransportOrderHistoryCodes.ORDER_DISPATCHING_RESUMED;
import static org.opentcs.data.order.TransportOrderHistoryCodes.ORDER_RESERVED_FOR_VEHICLE;

import jakarta.inject.Inject;
import java.util.Arrays;
import java.util.Collection;
import java.util.List;
import java.util.Optional;
import org.opentcs.components.kernel.services.TCSObjectService;
import org.opentcs.data.ObjectHistory;
import org.opentcs.data.model.Vehicle;
import org.opentcs.data.order.TransportOrder;
import org.opentcs.strategies.basic.dispatching.phase.OrderFilterResult;

/**
 * Appends history entries to transport orders to mark them as deferred, resumed, assigned or
 * reserved.
 */
public class DispatchingStatusMarker {

  private final TCSObjectService objectService;

  @Inject
  public DispatchingStatusMarker(TCSObjectService objectService) {
    this.objectService = requireNonNull(objectService, "objectService");
  }

  /**
   * Marks the given transport order as deferred.
   *
   * @param filterResult The filter result to be marked as deferred.
   */
  public void markOrderAsDeferred(OrderFilterResult filterResult) {
    TransportOrder transportOrder = filterResult.getOrder();
    objectService.appendObjectHistoryEntry(
        transportOrder.getReference(),
        new ObjectHistory.Entry(
            ORDER_DISPATCHING_DEFERRED,
            List.copyOf(filterResult.getFilterReasons())
        )
    );
  }

  /**
   * Marks the given transport order as resumed.
   *
   * @param transportOrder The transport order to be marked as resumed.
   */
  public void markOrderAsResumed(TransportOrder transportOrder) {
    objectService.appendObjectHistoryEntry(
        transportOrder.getReference(),
        new ObjectHistory.Entry(ORDER_DISPATCHING_RESUMED, List.of())
    );
  }

  /**
   * Checks whether the given transport order is marked as deferred.
   *
   * @param transportOrder The transport order to be checked.
   * @return Whether the given transport order is marked as deferred.
   */
  public boolean isOrderMarkedAsDeferred(TransportOrder transportOrder) {
    return lastRelevantDeferredHistoryEntry(transportOrder).isPresent();
  }

  /**
   * Marks the given transport order as assigned.
   *
   * @param transportOrder The transport order to be marked as assigned.
   * @param vehicle The vehicle the transport order is assigned to.
   */
  public void markOrderAsAssigned(TransportOrder transportOrder, Vehicle vehicle) {
    objectService.appendObjectHistoryEntry(
        transportOrder.getReference(),
        new ObjectHistory.Entry(
            ORDER_ASSIGNED_TO_VEHICLE,
            List.of(vehicle.getName())
        )
    );
  }

  /**
   * Marks the given transport order as reserved.
   *
   * @param transportOrder The transport order to be marked as reserved.
   * @param vehicle The vehicle the transport order is reserved for.
   */
  public void markOrderAsReserved(TransportOrder transportOrder, Vehicle vehicle) {
    objectService.appendObjectHistoryEntry(
        transportOrder.getReference(),
        new ObjectHistory.Entry(
            ORDER_RESERVED_FOR_VEHICLE,
            List.of(vehicle.getName())
        )
    );
  }

  /**
   * Checks whether the given transport order's deferral reasons have changed.
   *
   * @param filterResult The filter result to be checked.
   * @return Whether the given transport order's deferral reasons have changed.
   */
  public boolean haveDeferralReasonsForOrderChanged(OrderFilterResult filterResult) {
    Collection<String> newReasons = filterResult.getFilterReasons();
    Optional<ObjectHistory.Entry> lastRelevantHistoryEntry = lastRelevantDeferredHistoryEntry(
        filterResult.getOrder()
    );
    Collection<String> oldReasons = lastRelevantHistoryEntry.map(entry -> entry.getSupplements())
        .orElse(List.of());

    return newReasons.size() != oldReasons.size()
        || !newReasons.containsAll(oldReasons);
  }

  private Optional<ObjectHistory.Entry> lastRelevantDeferredHistoryEntry(
      TransportOrder transportOrder
  ) {
    return transportOrder.getHistory().getEntries().stream()
        .filter(entry -> equalsAny(entry.getEventCode(), ORDER_DISPATCHING_DEFERRED, ORDER_DISPATCHING_RESUMED))
        .reduce((firstEntry, secondEntry) -> secondEntry)
        .filter(entry -> equalsAny(entry.getEventCode(), ORDER_DISPATCHING_DEFERRED))
        .map(entry -> entry);
  }

  private boolean equalsAny(String string, String... others) {
    return Arrays.asList(others).stream().anyMatch(other -> string.equals(other));
  }
}

package cn.iocoder.yudao.framework.ip.core.utils;

import cn.hutool.core.io.resource.ResourceUtil;
import cn.hutool.core.lang.Assert;
import cn.hutool.core.text.csv.CsvRow;
import cn.hutool.core.text.csv.CsvUtil;
import cn.iocoder.yudao.framework.common.util.object.ObjectUtils;
import cn.iocoder.yudao.framework.ip.core.Area;
import cn.iocoder.yudao.framework.ip.core.enums.AreaTypeEnum;
import lombok.NonNull;
import lombok.experimental.UtilityClass;
import lombok.extern.slf4j.Slf4j;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;

import static cn.iocoder.yudao.framework.common.util.collection.CollectionUtils.convertList;
import static cn.iocoder.yudao.framework.common.util.collection.CollectionUtils.findFirst;

/**
 * 区域工具类
 *
 * 包括国家、省份、城市、区县、乡镇、村庄等信息
 *
 * @author 芋道源码
 */
@Slf4j
@UtilityClass
public class AreaUtils {

    /**
     * 区域缓存
     */
    private static Map<Integer, Area> areas;

    /**
     * 初始化
     */
    static {
        try {
            long start = System.currentTimeMillis();
            areas = new HashMap<>();
            // 1. 加载 area.csv 文件
            List<CsvRow> rows = CsvUtil.getReader().read(ResourceUtil.getUtf8Reader("area.csv")).getRows();
            rows.remove(0); // 去掉表头
            // 2.1 加载国家
            Area global = new Area(Area.ID_GLOBAL, "全球", AreaTypeEnum.COUNTRY.getType(), null, new ArrayList<>());
            areas.put(global.getId(), global);
            for (CsvRow row : rows) {
                Integer id = Integer.valueOf(row.get(0));
                String name = row.get(1);
                Integer type = Integer.valueOf(row.get(2));
                Area area = new Area(id, name, type, null, new ArrayList<>());
                areas.put(id, area);
            }
            // 2.2 加载省份
            for (CsvRow row : rows) {
                Area area = areas.get(Integer.valueOf(row.get(0)));
                Area parent = areas.get(Integer.valueOf(row.get(3)));
                Assert.isTrue(area != parent, "{}:父子节点相同", area.getName());
                area.setParent(parent);
                parent.getChildren().add(area);
            }
            log.info("[init][加载 AreaUtils 成功，耗时 {} 毫秒]", System.currentTimeMillis() - start);
        } catch (Exception e) {
            throw new RuntimeException("AreaUtils 初始化失败", e);
        }
    }

    /**
     * 根据编号获得区域
     *
     * @param id 编号
     * @return 区域
     */
    public static Area getArea(Integer id) {
        return areas.get(id);
    }

    /**
     * 根据路径获得区域
     *
     * 路径格式：省份/城市/区县
     *
     * @param pathStr 路径
     * @return 区域
     */
    public static Area parseArea(String pathStr) {
        String[] paths = pathStr.split("/");
        Area area = findFirst(areas.values(), area -> area.getName().equals(paths[0]));
        for (int i = 1; i < paths.length; i++) {
            area = findFirst(area.getChildren(), area -> area.getName().equals(paths[i]));
        }
        return area;
    }

    /**
     * 获得区域节点路径
     *
     * 格式：省份/城市/区县
     *
     * @param areas 区域节点
     * @return 区域节点路径
     */
    public static List<String> getAreaNodePathList(List<Area> areas) {
        List<String> paths = new ArrayList<>();
        for (Area area : areas) {
            getAreaNodePathList(area, "", paths);
        }
        return paths;
    }

    private static void getAreaNodePathList(Area node, String path, List<String> paths) {
        if (node == null) {
            return;
        }
        if (path.isEmpty()) {
            path = node.getName();
        } else {
            path = path + "/" + node.getName();
        }
        paths.add(path);
        for (Area child : node.getChildren()) {
            getAreaNodePathList(child, path, paths);
        }
    }

    /**
     * 格式化区域
     *
     * 格式：省份/城市/区县
     *
     * @param id 区域编号
     * @return 区域名字
     */
    public static String format(Integer id) {
        return format(id, " ");
    }

    /**
     * 格式化区域
     *
     * 格式：省份/城市/区县
     *
     * @param id 区域编号
     * @param separator 分隔符
     * @return 区域名字
     */
    public static String format(Integer id, String separator) {
        Area area = getArea(id);
        if (area == null) {
            return null;
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < AreaTypeEnum.values().length; i++) {
            sb.insert(0, area.getName());
            area = area.getParent();
            if (area == null || ObjectUtils.equalsAny(area.getId(), Area.ID_GLOBAL, Area.ID_CHINA)) {
                break;
            }
            sb.insert(0, separator);
        }
        return sb.toString();
    }

    /**
     * 获得区域节点
     *
     * @param type 区域类型
     * @param func 转换函数
     * @param <T> 转换类型
     * @return 区域节点
     */
    public static <T> List<T> getByType(AreaTypeEnum type, Function<Area, T> func) {
        return convertList(areas.values(), area -> func.apply(area), area -> area.getType() == type.getType());
    }

    /**
     * 获得父节点编号
     *
     * @param id 编号
     * @param type 类型
     * @return 父节点编号
     */
    public static Integer getParentIdByType(Integer id, @NonNull AreaTypeEnum type) {
        Area area = getArea(id);
        if (area == null) {
            return null;
        }
        for (int i = 0; i < Byte.MAX_VALUE; i++) {
            if (area.getType() == type.getType()) {
                return area.getId();
            }
            if (area.getParent() == null || area.getParent().getId() == null) {
                return null;
            }
            area = getArea(area.getParent().getId());
        }
        return null;
    }

}

package cn.iocoder.yudao.framework.signature.core.aop;

import cn.hutool.core.lang.Assert;
import cn.hutool.core.map.MapUtil;
import cn.hutool.core.util.BooleanUtil;
import cn.hutool.core.util.ObjUtil;
import cn.hutool.core.util.StrUtil;
import cn.hutool.crypto.digest.DigestUtil;
import cn.iocoder.yudao.framework.common.exception.ServiceException;
import cn.iocoder.yudao.framework.common.exception.enums.GlobalErrorCodeConstants;
import cn.iocoder.yudao.framework.common.util.servlet.ServletUtils;
import cn.iocoder.yudao.framework.signature.core.annotation.ApiSignature;
import cn.iocoder.yudao.framework.signature.core.redis.ApiSignatureRedisDAO;
import lombok.AllArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.aspectj.lang.JoinPoint;
import org.aspectj.lang.annotation.Aspect;
import org.aspectj.lang.annotation.Before;

import javax.servlet.http.HttpServletRequest;
import java.util.Map;
import java.util.Objects;
import java.util.SortedMap;
import java.util.TreeMap;

import static cn.iocoder.yudao.framework.common.exception.enums.GlobalErrorCodeConstants.BAD_REQUEST;

/**
 * 签名拦截器
 *
 * @author 芋道源码
 */
@Aspect // 使用 Spring AOP
@Slf4j // 使用 Lombok 日志
@AllArgsConstructor // 使用 Lombok 构造器
public class ApiSignatureAspect {

    private final ApiSignatureRedisDAO signatureRedisDAO;

    /**
     * 拦截方法
     *
     * @param joinPoint 连接点
     * @param signature 注解
     */
    @Before("@annotation(signature)")
    public void beforePointCut(JoinPoint joinPoint, ApiSignature signature) {
        HttpServletRequest request = ServletUtils.getRequest();
        if (Objects.requireNonNull(request, "request 不能为空")
                && verifySignature(signature, request)) {
            return;
        }
        // 拦截
        log.error("[beforePointCut][拦截请求，请求方法：{}，请求参数：{}]",
                joinPoint.getSignature().toString(), joinPoint.getArgs());
        throw new ServiceException(BAD_REQUEST.getCode(),
                StrUtil.blankToDefault(signature.message(), BAD_REQUEST.getMsg()));
    }

    /**
     * 验证签名
     *
     * @param signature 注解
     * @param request 请求
     * @return 是否验证成功
     */
    public boolean verifySignature(ApiSignature signature, HttpServletRequest request) {
        if (!verifyHeaders(signature, request)) {
            return false;
        }
        // 从请求头中获取 appId
        String appId = request.getHeader(signature.appId());
        String appSecret = signatureRedisDAO.getAppSecret(appId);
        Assert.notNull(appSecret, "appSecret 不能为空，appId 为：{}", appId);
        // 从请求头中获取 sign
        String sign = request.getHeader(signature.sign());
        // 拼接签名字符串
        String signatureString = buildSignatureString(signature, request, appSecret);
        // 计算签名
        String sha256Hex = DigestUtil.sha256Hex(signatureString);
        if (ObjUtil.notEqual(sign, sha256Hex)) {
            return false;
        }
        // 写入 nonce 防止重放
        String nonce = request.getHeader(signature.nonce());
        if (BooleanUtil.isFalse(signatureRedisDAO.setNonce(appId, nonce, signature.timeout() * 2, signature.timeUnit()))) {
            log.error("[verifySignature][存在重复请求，appId：{}，timestamp：{}，nonce：{}，sign：{}]",
                    appId, request.getHeader(signature.timestamp()), nonce, sign);
            throw new ServiceException(GlobalErrorCodeConstants.REPEATED_REQUESTS.getCode(), "存在重复请求");
        }
        return true;
    }

    /**
     * 验证请求头
     *
     * @param signature 注解
     * @param request 请求
     * @return 是否验证成功
     */
    private boolean verifyHeaders(ApiSignature signature, HttpServletRequest request) {
        // 验证 appId
        String appId = request.getHeader(signature.appId());
        if (StrUtil.isBlank(appId)) {
            return false;
        }
        // 验证 timestamp
        String timestamp = request.getHeader(signature.timestamp());
        if (StrUtil.isBlank(timestamp)) {
            return false;
        }
        // 验证 nonce
        String nonce = request.getHeader(signature.nonce());
        if (StrUtil.isBlank(nonce) || StrUtil.length(nonce) < 10) {
            return false;
        }
        // 验证 sign
        String sign = request.getHeader(signature.sign());
        if (StrUtil.isBlank(sign)) {
            return false;
        }
        // 验证时间戳
        long timeout = signature.timeUnit().toMillis(signature.timeout());
        long diff = Math.abs(Long.parseLong(timestamp) - System.currentTimeMillis());
        if (diff > timeout) {
            return false;
        }
        // 验证 nonce
        if (signatureRedisDAO.getNonce(appId, nonce) != null) {
            return false;
        }
        return true;
    }

    /**
     * 拼接签名字符串
     *
     * @param signature 注解
     * @param request 请求
     * @param appSecret 应用密钥
     * @return 签名字符串
     */
    private String buildSignatureString(ApiSignature signature, HttpServletRequest request, String appSecret) {
        // 拼接参数
        SortedMap<String, String> parameters = getRequestParameterMap(request);
        // 拼接请求头
        SortedMap<String, String> headers = getRequestHeaderMap(signature, request);
        // 拼接请求体
        String body = ServletUtils.getBody(request);
        body = StrUtil.nullToDefault(body, "");
        // 拼接
        return MapUtil.join(parameters, "&", "=") + body + MapUtil.join(headers, "&", "=") + appSecret;
    }

    /**
     * 获取请求头
     *
     * @param signature 注解
     * @param request 请求
     * @return 请求头
     */
    private static SortedMap<String, String> getRequestHeaderMap(ApiSignature signature, HttpServletRequest request) {
        SortedMap<String, String> headerMap = new TreeMap<>();
        headerMap.put(signature.appId(), request.getHeader(signature.appId()));
        headerMap.put(signature.timestamp(), request.getHeader(signature.timestamp()));
        headerMap.put(signature.nonce(), request.getHeader(signature.nonce()));
        return headerMap;
    }

    /**
     * 获取请求参数
     *
     * @param request 请求
     * @return 请求参数
     */
    private static SortedMap<String, String> getRequestParameterMap(HttpServletRequest request) {
        SortedMap<String, String> parameterMap = new TreeMap<>();
        for (Map.Entry<String, String[]> entry : request.getParameterMap().entrySet()) {
            parameterMap.put(entry.getKey(), entry.getValue()[0]);
        }
        return parameterMap;
    }

}

