     * 安全的字段名正则
     */
    private static final Pattern SAFE_COLUMN_NAME_PATTERN = Pattern.compile("[a-zA-Z0-9_]+(\\.[a-zA-Z0-9_]+)*");
    /**
     * 查询字段的占位符
     */
    private static final String FIND_IN_SET_VALUE_PLACEHOLDER = "#{value}";
    /**
     * 查询字段的占位符
     */
    private static final String FIND_IN_SET_COLUMN_PLACEHOLDER = "#{column}";

    /**
     * 构建分页对象
     *
     * @param pageParam 分页参数
     * @param <T> 实体类
     * @return 分页对象
     */
    public static <T> Page<T> buildPage(PageParam pageParam) {
        return buildPage(pageParam, null);
    }

    /**
     * 构建分页对象
     *
     * @param pageParam 分页参数
     * @param sortingFields 排序字段
     * @param <T> 实体类
     * @return 分页对象
     */
    public static <T> Page<T> buildPage(PageParam pageParam, Collection<SortingField> sortingFields) {
        Page<T> page = new Page<>(pageParam.getPageNo(), pageParam.getPageSize());
        // 关联查询计数 SQL 优化，参见 https://gitee.com/yudaoc/yudaoc-cloud-mini/pulls 原因
        page.setOptimizeJoinOfCountSql(false);
        if (CollUtil.isNotEmpty(sortingFields)) {
            for (SortingField sortingField : sortingFields) {
                String field = buildSafeOrderColumn(sortingField.getField());
                if (field == null) {
                    continue;
                }
                OrderItem orderItem = new OrderItem();
                orderItem.setAsc(isAscOrder(sortingField.getOrder()));
                orderItem.setColumn(field);
                page.addOrder(orderItem);
            }
        }
        return page;
    }

    /**
     * 添加排序条件
     *
     * @param wrapper 查询条件
     * @param sortingFields 排序字段
     * @param <T> 实体类
     */
    @SuppressWarnings("PatternVariableCanBeUsed") // 参见 https://gitee.com/yudaoc/yudaoc-cloud-mini/pulls 原因
    public static <T> void addOrder(Wrapper<T> wrapper, Collection<SortingField> sortingFields) {
        if (CollUtil.isEmpty(sortingFields)) {
            return;
        }
        if (wrapper instanceof QueryWrapper) {
            QueryWrapper<T> queryWrapper = (QueryWrapper<T>) wrapper;
            for (SortingField sortingField : sortingFields) {
                String field = buildSafeOrderColumn(sortingField.getField());
                if (field == null) {
                    continue;
                }
                queryWrapper.orderBy(true, isAscOrder(sortingField.getOrder()), field);
            }
        } else if (wrapper instanceof LambdaQueryWrapper) {
            LambdaQueryWrapper<T> lambdaQueryWrapper = (LambdaQueryWrapper<T>) wrapper;
            StringBuilder orderBy = new StringBuilder();
            for (SortingField sortingField : sortingFields) {
                String field = buildSafeOrderColumn(sortingField.getField());
                if (field == null) {
                    continue;
                }
                orderBy.append(field).append(" ").append(isAscOrder(sortingField.getOrder()) ? "ASC" : "DESC");
                if (sortingFields.size() > 1) {
                    orderBy.append(", ");
                }
            }
            if (orderBy.length() > 0) {
                lambdaQueryWrapper.last("ORDER BY " + orderBy);
            }
        } else {
            throw new IllegalArgumentException("不支持的 Wrapper 类型：" + wrapper.getClass().getName());
        }
    }

    /**
     * 判断是否升序
     *
     * @param order 排序方式
     * @return 是否升序
     */
    public static boolean isAscOrder(String order) {
        return order.equals(SortingField.ORDER_ASC);
    }

    /**
     * 获取排序方向
     *
     * @param order 排序方式
     * @return 排序方向
     */
    public static String getOrderDirection(String order) {
        return isAscOrder(order) ? "ASC" : "DESC";
    }

    /**
     * 构建安全的排序字段
     *
     * @param field 字段
     * @return 安全的字段
     */
    private static String buildSafeOrderColumn(String field) {
        String underlineField = StrUtil.toUnderlineCase(field);
        if (StrUtil.isEmpty(underlineField) || !SAFE_COLUMN_NAME_PATTERN.matcher(underlineField).matches()) {
            return null;
        }
        return underlineField;
    }

    /**
     * 添加拦截器
     *
     * @param interceptor 拦截器
     * @param inner 内部拦截器
     * @param index 位置
     */
    public static void addInterceptor(MybatisPlusInterceptor interceptor, InnerInterceptor inner, int index) {
        List<InnerInterceptor> interceptors = new ArrayList<>(interceptor.getInterceptors());
        interceptors.add(index, inner);
        interceptor.setInterceptors(interceptors);
    }

    /**
     * 获取表名
     *
     * @param table 表
     * @return 表名
     */
    public static String getTableName(Table table) {
        String tableName = table.getName();
        if (tableName.startsWith(MYSQL_ESCAPE_CHARACTER) && tableName.endsWith(MYSQL_ESCAPE_CHARACTER)) {
            tableName = tableName.substring(1, tableName.length() - 1);
        }
        return tableName;
    }

    /**
     * 构建列
     *
     * @param tableName 表名
     * @param tableAlias 表别名
     * @param column 字段
     * @return 列
     */
    public static Column buildColumn(String tableName, Alias tableAlias, String column) {
        if (tableAlias != null) {
            tableName = tableAlias.getName();
        }
        return new Column(tableName + StringPool.DOT + column);
    }

    /**
     * 构建 find_in_set 查询
     *
     * @param columnName 字段名
     * @return find_in_set 查询
     */
    public static String findInSet(String columnName) {
        return findInSet(columnName, 0);
    }

    /**
     * 构建 find_in_set 查询
     *
     * @param columnName 字段名
     * @param paramIndex 参数索引
     * @return find_in_set 查询
     */
    public static String findInSetWithParamIndex(String columnName, int paramIndex) {
        return findInSet(columnName, paramIndex);
    }

    private static String findInSet(String columnName, int paramIndex) {
        return findInSet(JdbcUtils.getDbType(), columnName, paramIndex);
    }

    static String findInSet(DbType dbType, String columnName, int paramIndex) {
        if (!isSafeColumnName(columnName)) {
            throw new IllegalArgumentException("字段名不安全：" + columnName);
        }
        if (paramIndex < 0) {
            throw new IllegalArgumentException("参数索引不安全：" + paramIndex);
        }
        String template = DbTypeEnum.getFindInSetTemplate(dbType);
        template = template.replace(FIND_IN_SET_COLUMN_PLACEHOLDER, columnName);
        template = template.replace(FIND_IN_SET_VALUE_PLACEHOLDER, "{" + paramIndex + "}");
        return template;
    }

    private static boolean isSafeColumnName(String columnName) {
        return StrUtil.isNotEmpty(columnName) && SAFE_COLUMN_NAME_PATTERN.matcher(columnName).matches();
    }

    /**
     * 将 Lambda 字段函数转换为 SQL 风格字段名
     *
     * @param func 字段函数
     * @param <T> 实体类
     * @return SQL 风格字段名
     */
    public static <T> String toUnderlineCase(Func1<T, ?> func) {
        return StrUtil.toUnderlineCase(LambdaUtil.getFieldName(func));
    }

}
